def _filters_cache_key(endpoint: str, school_code: str) -> str:
    school = (school_code or "").strip().upper()
    return f"{endpoint}|{school}"


def _filters_cache_get(key: str) -> Any:
    if _FILTERS_CACHE_TTL_SECONDS <= 0:
        return None
    now = time.time()
    with _FILTERS_CACHE_LOCK:
        hit = _FILTERS_CACHE.get(key)
        if not hit:
            return None
        ts, value = hit
        if now - ts > _FILTERS_CACHE_TTL_SECONDS:
            _FILTERS_CACHE.pop(key, None)
            return None
        return value


def _filters_cache_set(key: str, value: Any) -> None:
    if _FILTERS_CACHE_TTL_SECONDS <= 0:
        return
    now = time.time()
    with _FILTERS_CACHE_LOCK:
        _FILTERS_CACHE[key] = (now, value)
        if len(_FILTERS_CACHE) > _FILTERS_CACHE_MAX_ENTRIES:
            stale_count = max(1, len(_FILTERS_CACHE) - _FILTERS_CACHE_MAX_ENTRIES)
            for stale_key, _ in sorted(_FILTERS_CACHE.items(), key=lambda item: item[1][0])[:stale_count]:
                _FILTERS_CACHE.pop(stale_key, None)


def _filters_cache_invalidate_school(school_code: str) -> None:
    school = (school_code or "").strip().upper()
    if not school:
        return
    token = f"|{school}"
    with _FILTERS_CACHE_LOCK:
        keys = [key for key in _FILTERS_CACHE.keys() if key.endswith(token)]
        for key in keys:
            _FILTERS_CACHE.pop(key, None)


def _ensure_filters_snapshot_schema() -> None:
    global _FILTERS_SNAPSHOT_SCHEMA_READY
    if _FILTERS_SNAPSHOT_SCHEMA_READY:
        return
    with _FILTERS_SNAPSHOT_SCHEMA_LOCK:
        if _FILTERS_SNAPSHOT_SCHEMA_READY:
            return
        try:
            with get_conn() as conn, conn.cursor() as cur:
                cur.execute("SET LOCAL lock_timeout = '2s'")
                cur.execute("SET LOCAL statement_timeout = '30s'")
                cur.execute(
                    """
                    CREATE TABLE IF NOT EXISTS public.dashboard_filters_snapshot (
                      school_code TEXT NOT NULL,
                      domain TEXT NOT NULL,
                      level_bucket TEXT NOT NULL DEFAULT 'All',
                      payload_json JSONB NOT NULL,
                      updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                      PRIMARY KEY (school_code, domain, level_bucket)
                    )
                    """
                )
                cur.execute(
                    """
                    CREATE INDEX IF NOT EXISTS idx_dashboard_filters_snapshot_updated_at
                    ON public.dashboard_filters_snapshot (updated_at DESC)
                    """
                )
            _FILTERS_SNAPSHOT_SCHEMA_READY = True
        except Exception:
            # Non-fatal: request path can proceed without persistent snapshots.
            return


def _save_filters_snapshot(
    *,
    school_code: str,
    domain: str,
    payload: Any,
    level_bucket: str = "All",
) -> None:
    _ensure_filters_snapshot_schema()
    school = (school_code or "").strip().upper()
    lvl = (level_bucket or "All").strip() or "All"
    dom = (domain or "").strip().lower()
    if not school or not dom:
        return
    try:
        payload_json = json.loads(json.dumps(_json_stable(payload), default=str))
        with get_conn() as conn, conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO public.dashboard_filters_snapshot (
                  school_code, domain, level_bucket, payload_json, updated_at
                )
                VALUES (%(school_code)s, %(domain)s, %(level_bucket)s, %(payload_json)s::jsonb, NOW())
                ON CONFLICT (school_code, domain, level_bucket)
                DO UPDATE
                  SET payload_json = EXCLUDED.payload_json,
                      updated_at = NOW()
                """,
                {
                    "school_code": school,
                    "domain": dom,
                    "level_bucket": lvl,
                    "payload_json": json.dumps(payload_json),
                },
            )
    except Exception:
        return


def _load_filters_snapshot(
    *,
    school_code: str,
    domain: str,
    level_bucket: str = "All",
) -> Optional[Dict[str, Any]]:
    payload, _ = _load_filters_snapshot_with_meta(
        school_code=school_code,
        domain=domain,
        level_bucket=level_bucket,
    )
    return payload


def _load_filters_snapshot_with_meta(
    *,
    school_code: str,
    domain: str,
    level_bucket: str = "All",
) -> tuple[Optional[Dict[str, Any]], Optional[datetime]]:
    school = (school_code or "").strip().upper()
    lvl = (level_bucket or "All").strip() or "All"
    dom = (domain or "").strip().lower()
    if not school or not dom:
        return None, None
    try:
        with get_conn() as conn, conn.cursor() as cur:
            cur.execute(
                """
                SELECT payload_json, updated_at
                FROM public.dashboard_filters_snapshot
                WHERE school_code = %(school_code)s
                  AND domain = %(domain)s
                  AND level_bucket = %(level_bucket)s
                LIMIT 1
                """,
                {
                    "school_code": school,
                    "domain": dom,
                    "level_bucket": lvl,
                },
            )
            row = cur.fetchone() or {}
            payload = row.get("payload_json")
            updated_at = row.get("updated_at")
            if isinstance(payload, dict):
                return payload, updated_at if isinstance(updated_at, datetime) else None
            if isinstance(payload, str) and payload.strip():
                try:
                    loaded = json.loads(payload)
                    if isinstance(loaded, dict):
                        return loaded, updated_at if isinstance(updated_at, datetime) else None
                    return None, updated_at if isinstance(updated_at, datetime) else None
                except Exception:
                    return None, None
            return None, updated_at if isinstance(updated_at, datetime) else None
    except Exception:
        return None, None


def _filters_snapshot_is_stale(updated_at: Optional[datetime]) -> bool:
    if not isinstance(updated_at, datetime):
        return True
    try:
        if updated_at.tzinfo is None:
            updated_at = updated_at.replace(tzinfo=timezone.utc)
        age_seconds = (datetime.now(timezone.utc) - updated_at.astimezone(timezone.utc)).total_seconds()
        return age_seconds > float(_FILTERS_SNAPSHOT_MAX_AGE_SECONDS)
    except Exception:
        return True


def _kick_filters_snapshot_refresh_background(
    *,
    school_code: str,
    domain: str,
    level_bucket: str = "All",
) -> None:
    school = (school_code or "").strip().upper()
    dom = (domain or "").strip().lower()
    lvl = (level_bucket or "All").strip() or "All"
    if not school or dom not in {"pitching", "hitting", "catching"}:
        return
    key = f"{school}|{dom}|{lvl}"
    now = time.monotonic()
    with _FILTERS_SNAPSHOT_REFRESH_LOCK:
        if key in _FILTERS_SNAPSHOT_REFRESH_RUNNING:
            return
        last_at = float(_FILTERS_SNAPSHOT_REFRESH_LAST_AT.get(key, 0.0))
        if (now - last_at) < _FILTERS_SNAPSHOT_REFRESH_COOLDOWN_SECONDS:
            return
        _FILTERS_SNAPSHOT_REFRESH_RUNNING.add(key)
        _FILTERS_SNAPSHOT_REFRESH_LAST_AT[key] = now

    def _worker() -> None:
        try:
            if dom == "pitching":
                pitching_filters(
                    school_code=school,
                    level=lvl if school == "PRO" else None,
                    force_refresh=True,
                )
            elif dom == "hitting":
                hitting_filters(
                    school_code=school,
                    level=lvl if school == "PRO" else None,
                    force_refresh=True,
                )
            else:
                catching_filters(
                    school_code=school,
                    level=lvl if school == "PRO" else None,
                    force_refresh=True,
                )
        except Exception:
            return
        finally:
            with _FILTERS_SNAPSHOT_REFRESH_LOCK:
                _FILTERS_SNAPSHOT_REFRESH_RUNNING.discard(key)

    try:
        thread = threading.Thread(target=_worker, name=f"filters-snapshot-refresh-{dom}-{school.lower()}-{lvl.lower()}", daemon=True)
        thread.start()
    except Exception:
        with _FILTERS_SNAPSHOT_REFRESH_LOCK:
            _FILTERS_SNAPSHOT_REFRESH_RUNNING.discard(key)


def _ensure_home_trends_snapshot_schema() -> None:
    global _HOME_TRENDS_SNAPSHOT_SCHEMA_READY
    if _HOME_TRENDS_SNAPSHOT_SCHEMA_READY:
        return
    with _HOME_TRENDS_SNAPSHOT_SCHEMA_LOCK:
        if _HOME_TRENDS_SNAPSHOT_SCHEMA_READY:
            return
        try:
            with get_conn() as conn, conn.cursor() as cur:
                cur.execute("SET LOCAL lock_timeout = '2s'")
                cur.execute("SET LOCAL statement_timeout = '30s'")
                cur.execute(
                    """
                    CREATE TABLE IF NOT EXISTS public.dashboard_home_trends_snapshot (
                      school_code TEXT NOT NULL,
                      level_bucket TEXT NOT NULL DEFAULT 'All',
                      season_start DATE NOT NULL,
                      season_end DATE NOT NULL,
                      recent_start DATE NOT NULL,
                      recent_end DATE NOT NULL,
                      scoped_pitcher TEXT NOT NULL DEFAULT '',
                      scoped_hitter TEXT NOT NULL DEFAULT '',
                      payload_json JSONB NOT NULL,
                      updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                      PRIMARY KEY (
                        school_code, level_bucket, season_start, season_end, recent_start, recent_end, scoped_pitcher, scoped_hitter
                      )
                    )
                    """
                )
                cur.execute(
                    """
                    CREATE INDEX IF NOT EXISTS idx_dashboard_home_trends_snapshot_updated_at
                    ON public.dashboard_home_trends_snapshot (updated_at DESC)
                    """
                )
            _HOME_TRENDS_SNAPSHOT_SCHEMA_READY = True
        except Exception:
            return


def _load_home_trends_snapshot_with_meta(
    *,
    school_code: str,
    level_bucket: str,
    season_start: date,
    season_end: date,
    recent_start: date,
    recent_end: date,
    scoped_pitcher: str,
    scoped_hitter: str,
) -> tuple[Optional[Dict[str, Any]], Optional[datetime]]:
    _ensure_home_trends_snapshot_schema()
    school = (school_code or "").strip().upper()
    if not school:
        return None, None
    level = (level_bucket or "All").strip() or "All"
    pitch_scope = _normalize_name_key(scoped_pitcher or "")
    hit_scope = _normalize_name_key(scoped_hitter or "")
    try:
        with get_conn() as conn, conn.cursor() as cur:
            cur.execute(
                """
                SELECT payload_json, updated_at
                FROM public.dashboard_home_trends_snapshot
                WHERE school_code = %(school_code)s
                  AND level_bucket = %(level_bucket)s
                  AND season_start = %(season_start)s::date
                  AND season_end = %(season_end)s::date
                  AND recent_start = %(recent_start)s::date
                  AND recent_end = %(recent_end)s::date
                  AND scoped_pitcher = %(scoped_pitcher)s
                  AND scoped_hitter = %(scoped_hitter)s
                LIMIT 1
                """,
                {
                    "school_code": school,
                    "level_bucket": level,
                    "season_start": season_start,
                    "season_end": season_end,
                    "recent_start": recent_start,
                    "recent_end": recent_end,
                    "scoped_pitcher": pitch_scope,
                    "scoped_hitter": hit_scope,
                },
            )
            row = cur.fetchone() or {}
            payload = row.get("payload_json")
            updated_at = row.get("updated_at")
            if isinstance(payload, dict):
                return payload, updated_at if isinstance(updated_at, datetime) else None
            if isinstance(payload, str) and payload.strip():
                try:
                    parsed = json.loads(payload)
                    if isinstance(parsed, dict):
                        return parsed, updated_at if isinstance(updated_at, datetime) else None
                except Exception:
                    return None, None
            return None, updated_at if isinstance(updated_at, datetime) else None
    except Exception:
        return None, None


def _save_home_trends_snapshot(
    *,
    school_code: str,
    level_bucket: str,
    season_start: date,
    season_end: date,
    recent_start: date,
    recent_end: date,
    scoped_pitcher: str,
    scoped_hitter: str,
    payload: Dict[str, Any],
) -> None:
    _ensure_home_trends_snapshot_schema()
    school = (school_code or "").strip().upper()
    if not school:
        return
    level = (level_bucket or "All").strip() or "All"
    pitch_scope = _normalize_name_key(scoped_pitcher or "")
    hit_scope = _normalize_name_key(scoped_hitter or "")
    try:
        payload_json = json.loads(json.dumps(_json_stable(payload), default=str))
        with get_conn() as conn, conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO public.dashboard_home_trends_snapshot (
                  school_code, level_bucket, season_start, season_end, recent_start, recent_end,
                  scoped_pitcher, scoped_hitter, payload_json, updated_at
                )
                VALUES (
                  %(school_code)s, %(level_bucket)s, %(season_start)s::date, %(season_end)s::date,
                  %(recent_start)s::date, %(recent_end)s::date, %(scoped_pitcher)s, %(scoped_hitter)s,
                  %(payload_json)s::jsonb, NOW()
                )
                ON CONFLICT (
                  school_code, level_bucket, season_start, season_end, recent_start, recent_end, scoped_pitcher, scoped_hitter
                )
                DO UPDATE SET payload_json = EXCLUDED.payload_json, updated_at = NOW()
                """,
                {
                    "school_code": school,
                    "level_bucket": level,
                    "season_start": season_start,
                    "season_end": season_end,
                    "recent_start": recent_start,
                    "recent_end": recent_end,
                    "scoped_pitcher": pitch_scope,
                    "scoped_hitter": hit_scope,
                    "payload_json": json.dumps(payload_json),
                },
            )
    except Exception:
        return


def _home_trends_snapshot_is_stale(updated_at: Optional[datetime]) -> bool:
    if not isinstance(updated_at, datetime):
        return True
    try:
        ts = updated_at if updated_at.tzinfo is not None else updated_at.replace(tzinfo=timezone.utc)
        age_seconds = (datetime.now(timezone.utc) - ts.astimezone(timezone.utc)).total_seconds()
        return age_seconds > float(_HOME_TRENDS_SNAPSHOT_MAX_AGE_SECONDS)
    except Exception:
        return True


def _display_name_first_last(value: str) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    if "," not in raw:
        return raw
    parts = [part.strip() for part in raw.split(",")]
    if len(parts) < 2:
        return raw
    combined = " ".join([*parts[1:], parts[0]]).strip()
    return re.sub(r"\s+", " ", combined) or raw


def _home_metric_number(value: Any) -> Optional[float]:
    if value is None:
        return None
    if isinstance(value, (int, float)):
        if isinstance(value, float) and (isnan(value) or not isfinite(value)):
            return None
        return float(value)
    raw = str(value).strip()
    if not raw:
        return None
    cleaned = raw.replace("%", "").replace(",", "").replace("$", "")
    try:
        parsed = float(cleaned)
        if isnan(parsed) or not isfinite(parsed):
            return None
        return parsed
    except Exception:
        return None


def _home_metric_from_row(row: Dict[str, Any], aliases: List[str], *, pct_like: bool = False) -> Optional[float]:
    keys = list(row.keys())
    alias_norm = {_normalize_name_key(alias): alias for alias in aliases if str(alias).strip()}
    for key in keys:
        key_str = str(key)
        if key_str in aliases:
            metric = _home_metric_number(row.get(key))
            if metric is None:
                continue
            if pct_like and metric > 100.0:
                continue
            return metric
    for key in keys:
        key_norm = _normalize_name_key(str(key))
        if key_norm in alias_norm:
            metric = _home_metric_number(row.get(key))
            if metric is None:
                continue
            if pct_like and metric > 100.0:
                continue
            return metric
    return None


def _rows_from_overview_payload(payload: Any) -> List[Dict[str, Any]]:
    rows: Any = None
    if isinstance(payload, dict):
        rows = payload.get("table_rows")
    elif hasattr(payload, "table_rows"):
        rows = getattr(payload, "table_rows", None)
    if not isinstance(rows, list):
        return []
    out: List[Dict[str, Any]] = []
    for row in rows:
        if isinstance(row, dict):
            out.append(row)
        elif hasattr(row, "model_dump"):
            try:
                dumped = row.model_dump()
                if isinstance(dumped, dict):
                    out.append(dumped)
            except Exception:
                continue
    return out


def _build_home_pitching_rows(
    season_rows: List[Dict[str, Any]],
    recent_rows: List[Dict[str, Any]],
    season_fbsi_rows: List[Dict[str, Any]],
    recent_fbsi_rows: List[Dict[str, Any]],
    *,
    allowed_pitcher_keys: Optional[Set[str]],
    min_season_sample: int,
) -> List[Dict[str, Any]]:
    season_velo: Dict[str, Optional[float]] = {}
    recent_velo: Dict[str, Optional[float]] = {}
    for row in season_fbsi_rows:
        name_raw = str(row.get("Pitcher") or row.get("pitcher") or row.get("Name") or "").strip()
        key = _normalize_name_key(name_raw)
        if not key or key == "all":
            continue
        season_velo[key] = _home_metric_number(row.get("Velo"))
    for row in recent_fbsi_rows:
        name_raw = str(row.get("Pitcher") or row.get("pitcher") or row.get("Name") or "").strip()
        key = _normalize_name_key(name_raw)
        if not key or key == "all":
            continue
        recent_velo[key] = _home_metric_number(row.get("Velo"))

    by_name: Dict[str, Dict[str, Any]] = {}
    for row in season_rows:
        name_raw = str(row.get("Pitcher") or row.get("pitcher") or row.get("Name") or "").strip()
        key = _normalize_name_key(name_raw)
        if not key or key == "all":
            continue
        if allowed_pitcher_keys and key not in allowed_pitcher_keys:
            continue
        by_name[key] = {
            "name": _display_name_first_last(name_raw),
            "sample": int(_home_metric_number(row.get("#")) or 0),
            "recentSample": 0,
            "metrics": {
                "Velo": {"season": season_velo.get(key), "recent": None},
                "K%": {"season": _home_metric_number(row.get("K%")), "recent": None},
                "BB%": {"season": _home_metric_number(row.get("BB%")), "recent": None},
                "E+A%": {"season": _home_metric_number(row.get("E+A%")), "recent": None},
            },
        }
    for row in recent_rows:
        name_raw = str(row.get("Pitcher") or row.get("pitcher") or row.get("Name") or "").strip()
        key = _normalize_name_key(name_raw)
        if not key or key == "all" or key not in by_name:
            continue
        by_name[key]["recentSample"] = int(_home_metric_number(row.get("#")) or by_name[key]["recentSample"])
        by_name[key]["metrics"]["Velo"]["recent"] = recent_velo.get(key)
        by_name[key]["metrics"]["K%"]["recent"] = _home_metric_number(row.get("K%"))
        by_name[key]["metrics"]["BB%"]["recent"] = _home_metric_number(row.get("BB%"))
        by_name[key]["metrics"]["E+A%"]["recent"] = _home_metric_number(row.get("E+A%"))
    rows = [row for row in by_name.values() if int(row.get("sample") or 0) >= int(min_season_sample)]
    rows.sort(key=lambda row: (-(int(row.get("recentSample") or 0)), -(int(row.get("sample") or 0)), str(row.get("name") or "")))
    return rows


def _build_home_hitting_rows(
    season_rows: List[Dict[str, Any]],
    recent_rows: List[Dict[str, Any]],
    *,
    allowed_hitter_keys: Optional[Set[str]],
    min_season_sample: int,
) -> List[Dict[str, Any]]:
    by_name: Dict[str, Dict[str, Any]] = {}
    for row in season_rows:
        name_raw = str(row.get("Batter") or row.get("Hitter") or row.get("hitter") or row.get("Name") or "").strip()
        key = _normalize_name_key(name_raw)
        if not key or key == "all":
            continue
        if allowed_hitter_keys and key not in allowed_hitter_keys:
            continue
        sample = int(_home_metric_number(row.get("#")) or _home_metric_number(row.get("PA")) or 0)
        by_name[key] = {
            "name": _display_name_first_last(name_raw),
            "sample": sample,
            "recentSample": 0,
            "metrics": {
                "xWOBA": {"season": _home_metric_from_row(row, ["xWOBA"]), "recent": None},
                "Barrel%": {"season": _home_metric_from_row(row, ["Barrel%", "BarrelPct"], pct_like=True), "recent": None},
                "GoZoneSw%": {
                    "season": _home_metric_from_row(
                        row,
                        ["GoZoneSw%", "GoZoneSwPct", "GoZoneSwing%", "GoZoneSwingPct", "GoZoneSw"],
                        pct_like=True,
                    ),
                    "recent": None,
                },
            },
        }
    for row in recent_rows:
        name_raw = str(row.get("Batter") or row.get("Hitter") or row.get("hitter") or row.get("Name") or "").strip()
        key = _normalize_name_key(name_raw)
        if not key or key == "all" or key not in by_name:
            continue
        by_name[key]["recentSample"] = int(
            _home_metric_number(row.get("#")) or _home_metric_number(row.get("PA")) or by_name[key]["recentSample"]
        )
        by_name[key]["metrics"]["xWOBA"]["recent"] = _home_metric_from_row(row, ["xWOBA"])
        by_name[key]["metrics"]["Barrel%"]["recent"] = _home_metric_from_row(row, ["Barrel%", "BarrelPct"], pct_like=True)
        by_name[key]["metrics"]["GoZoneSw%"]["recent"] = _home_metric_from_row(
            row,
            ["GoZoneSw%", "GoZoneSwPct", "GoZoneSwing%", "GoZoneSwingPct", "GoZoneSw"],
            pct_like=True,
        )
    rows = [row for row in by_name.values() if int(row.get("sample") or 0) >= int(min_season_sample)]
    rows.sort(key=lambda row: (-(int(row.get("recentSample") or 0)), -(int(row.get("sample") or 0)), str(row.get("name") or "")))
    return rows


def _compute_home_trends_payload(
    *,
    school_code: str,
    season_start: date,
    season_end: date,
    recent_start: date,
    recent_end: date,
    scoped_pitcher: str,
    scoped_hitter: str,
    level_bucket: str,
) -> Dict[str, Any]:
    school = _validate_school_code(school_code)
    level = (level_bucket or "All").strip() or "All"
    is_scoped = bool((scoped_pitcher or "").strip() or (scoped_hitter or "").strip())
    min_pitching_sample = 0 if is_scoped else 25
    min_hitting_sample = 0 if is_scoped else 20

    roster = _load_school_roster(school)
    allowed_pitcher_keys: Optional[Set[str]] = None
    allowed_hitter_keys: Optional[Set[str]] = None
    if school not in {"PRO", "LEAGUE"}:
        roster_pitchers = {str(key).strip() for key in roster.get("team_only_norm", []) if str(key).strip()}
        roster_hitters = {str(key).strip() for key in roster.get("hitter_norm", []) if str(key).strip()}
        roster_pitchers.update(
            _normalize_name_key(name)
            for name in _load_dashboard_csv_pitchers(school)
            if _normalize_name_key(name)
        )
        allowed_pitcher_keys = roster_pitchers if roster_pitchers else None
        allowed_hitter_keys = roster_hitters if roster_hitters else None
    pitching_defaults = {
        "team_type": "All",
        "opp_hitter": None,
        "with_video": None,
        "break_lines": None,
        "stuff_level": None,
        "stuff_base": None,
        "hand": None,
        "batter_side": None,
        "venue": None,
        "session_type": None,
        "visual_option": None,
        "in_zone": None,
        "qp_locations": None,
        "ball_types": None,
        "zone_locations": None,
        "pitch_results": None,
        "count_filter": None,
        "after_count_filter": None,
        "velo_min": None,
        "velo_max": None,
        "ivb_min": None,
        "ivb_max": None,
        "hb_min": None,
        "hb_max": None,
        "pc_min": None,
        "pc_max": None,
        "bf_min": None,
        "bf_max": None,
        "ip_min": None,
        "ip_max": None,
        "chart_points_limit": None,
        "chart_only": False,
        "force_raw": False,
    }
    hitting_defaults = {
        "session_type": None,
        "team_type": "All",
        "opp_pitcher": None,
        "hand": None,
        "batter_side": None,
        "venue": None,
        "in_zone": None,
        "pitch_types": None,
        "zone_locations": None,
        "pitch_results": None,
        "count_filter": None,
        "after_count_filter": None,
        "bip_result": None,
        "velo_min": None,
        "velo_max": None,
        "ivb_min": None,
        "ivb_max": None,
        "hb_min": None,
        "hb_max": None,
        "pc_min": None,
        "pc_max": None,
        "chart_points_limit": None,
        "chart_only": False,
        "force_raw": False,
        "recent_pa_mode": None,
        "recent_pa_count": None,
        "recent_pa_ignore_dates": False,
    }

    season_pitching = pitching_overview(
        school_code=school,
        start_date=season_start,
        end_date=season_end,
        level=(level if school == "PRO" else None),
        pitcher=(scoped_pitcher or None),
        table_mode="Custom",
        split_by="Pitcher",
        custom_columns="K%,BB%,E+A%",
        pitch_types=None,
        include_chart_points=False,
        include_row_pitches=False,
        include_trend_rows=False,
        **pitching_defaults,
    )
    recent_pitching = pitching_overview(
        school_code=school,
        start_date=recent_start,
        end_date=recent_end,
        level=(level if school == "PRO" else None),
        pitcher=(scoped_pitcher or None),
        table_mode="Custom",
        split_by="Pitcher",
        custom_columns="K%,BB%,E+A%",
        pitch_types=None,
        include_chart_points=False,
        include_row_pitches=False,
        include_trend_rows=False,
        **pitching_defaults,
    )
    season_pitching_fbsi = pitching_overview(
        school_code=school,
        start_date=season_start,
        end_date=season_end,
        level=(level if school == "PRO" else None),
        pitcher=(scoped_pitcher or None),
        table_mode="Custom",
        split_by="Pitcher",
        custom_columns="Velo",
        pitch_types="Fastball,Sinker",
        include_chart_points=False,
        include_row_pitches=False,
        include_trend_rows=False,
        **pitching_defaults,
    )
    recent_pitching_fbsi = pitching_overview(
        school_code=school,
        start_date=recent_start,
        end_date=recent_end,
        level=(level if school == "PRO" else None),
        pitcher=(scoped_pitcher or None),
        table_mode="Custom",
        split_by="Pitcher",
        custom_columns="Velo",
        pitch_types="Fastball,Sinker",
        include_chart_points=False,
        include_row_pitches=False,
        include_trend_rows=False,
        **pitching_defaults,
    )
    season_hitting = hitting_overview(
        school_code=school,
        start_date=season_start,
        end_date=season_end,
        level=(level if school == "PRO" else None),
        hitter=(scoped_hitter or None),
        table_mode="Custom",
        split_by="Batter",
        custom_columns="xWOBA,Barrel%,GoZoneSw%",
        include_chart_points=False,
        **hitting_defaults,
    )
    recent_hitting = hitting_overview(
        school_code=school,
        start_date=recent_start,
        end_date=recent_end,
        level=(level if school == "PRO" else None),
        hitter=(scoped_hitter or None),
        table_mode="Custom",
        split_by="Batter",
        custom_columns="xWOBA,Barrel%,GoZoneSw%",
        include_chart_points=False,
        **hitting_defaults,
    )

    pitching_rows = _build_home_pitching_rows(
        _rows_from_overview_payload(season_pitching),
        _rows_from_overview_payload(recent_pitching),
        _rows_from_overview_payload(season_pitching_fbsi),
        _rows_from_overview_payload(recent_pitching_fbsi),
        allowed_pitcher_keys=allowed_pitcher_keys,
        min_season_sample=min_pitching_sample,
    )
    hitting_rows = _build_home_hitting_rows(
        _rows_from_overview_payload(season_hitting),
        _rows_from_overview_payload(recent_hitting),
        allowed_hitter_keys=allowed_hitter_keys,
        min_season_sample=min_hitting_sample,
    )
    return {
        "school_code": school,
        "season_start": season_start.isoformat(),
        "season_end": season_end.isoformat(),
        "recent_start": recent_start.isoformat(),
        "recent_end": recent_end.isoformat(),
        "pitching": pitching_rows,
        "hitting": hitting_rows,
    }


def _kick_home_trends_snapshot_refresh_background(
    *,
    school_code: str,
    season_start: date,
    season_end: date,
    recent_start: date,
    recent_end: date,
    scoped_pitcher: str,
    scoped_hitter: str,
    level_bucket: str = "All",
) -> None:
    school = _validate_school_code(school_code)
    level = (level_bucket or "All").strip() or "All"
    pitch_scope = _normalize_name_key(scoped_pitcher or "")
    hit_scope = _normalize_name_key(scoped_hitter or "")
    key = "|".join(
        [
            school,
            level,
            season_start.isoformat(),
            season_end.isoformat(),
            recent_start.isoformat(),
            recent_end.isoformat(),
            pitch_scope,
            hit_scope,
        ]
    )
    now = time.monotonic()
    with _HOME_TRENDS_SNAPSHOT_REFRESH_LOCK:
        if key in _HOME_TRENDS_SNAPSHOT_REFRESH_RUNNING:
            return
        last_at = float(_HOME_TRENDS_SNAPSHOT_REFRESH_LAST_AT.get(key, 0.0))
        if (now - last_at) < _HOME_TRENDS_SNAPSHOT_REFRESH_COOLDOWN_SECONDS:
            return
        _HOME_TRENDS_SNAPSHOT_REFRESH_RUNNING.add(key)
        _HOME_TRENDS_SNAPSHOT_REFRESH_LAST_AT[key] = now

    def _worker() -> None:
        try:
            payload = _compute_home_trends_payload(
                school_code=school,
                season_start=season_start,
                season_end=season_end,
                recent_start=recent_start,
                recent_end=recent_end,
                scoped_pitcher=scoped_pitcher,
                scoped_hitter=scoped_hitter,
                level_bucket=level,
            )
            _save_home_trends_snapshot(
                school_code=school,
                level_bucket=level,
                season_start=season_start,
                season_end=season_end,
                recent_start=recent_start,
                recent_end=recent_end,
                scoped_pitcher=scoped_pitcher,
                scoped_hitter=scoped_hitter,
                payload=payload,
            )
        except Exception:
            return
        finally:
            with _HOME_TRENDS_SNAPSHOT_REFRESH_LOCK:
                _HOME_TRENDS_SNAPSHOT_REFRESH_RUNNING.discard(key)

    try:
        thread = threading.Thread(target=_worker, name=f"home-trends-refresh-{school.lower()}-{level.lower()}", daemon=True)
        thread.start()
    except Exception:
        with _HOME_TRENDS_SNAPSHOT_REFRESH_LOCK:
            _HOME_TRENDS_SNAPSHOT_REFRESH_RUNNING.discard(key)


def _downsample_rows_for_chart_points(rows: List[Dict[str, Any]], max_points: int = _CHART_POINTS_MAX) -> List[Dict[str, Any]]:
    total = len(rows)
    if max_points <= 0 or total <= max_points:
        return rows
    if max_points == 1:
        return [rows[-1]]
    step = (total - 1) / float(max_points - 1)
    out: List[Dict[str, Any]] = []
    used = set()
    for i in range(max_points):
        idx = int(round(i * step))
        idx = min(total - 1, max(0, idx))
        if idx in used:
            continue
        used.add(idx)
        out.append(rows[idx])
    if out[-1] is not rows[-1]:
        out[-1] = rows[-1]
    return out


def _latest_rows_for_chart_points(rows: List[Dict[str, Any]], max_points: int) -> List[Dict[str, Any]]:
    if max_points <= 0:
        return []
    if len(rows) <= max_points:
        return rows
    ordered = sorted(
        rows,
        key=lambda r: (
            str(r.get("session_date") or ""),
            int(r.get("pitch_number") or 0),
            int(r.get("pitch_no") or 0),
            int(r.get("id") or 0),
        ),
    )
    return ordered[-max_points:]


def _dynamic_chart_points_limit(
    *,
    team_type_value: Optional[str],
    primary_selected_count: int,
    secondary_selected_count: int = 0,
) -> int:
    team_val = str(team_type_value or "").strip().lower()
    all_all = team_val in {"", "all"} and primary_selected_count == 0 and secondary_selected_count == 0
    # Keep broad-scope defaults smaller so dashboards return faster under heavy load.
    base_limit = 700 if all_all else 3000
    return max(100, min(base_limit, _CHART_POINTS_MAX))


def _is_num(value: Any) -> bool:
    if value is None:
        return False
    try:
        return isfinite(float(value))
    except (TypeError, ValueError):
        return False


def _mean(values: List[Optional[float]]) -> Optional[float]:
    nums = [float(v) for v in values if _is_num(v)]  # type: ignore[arg-type]
    if not nums:
        return None
    return sum(nums) / len(nums)


def _std_ivb(pitch_type: str, rel_height: Optional[float]) -> Optional[float]:
    if pitch_type not in {"Fastball", "Sinker"} or not _is_num(rel_height):
        return None
    rh = float(rel_height)
    if pitch_type == "Fastball":
        if rh >= 6.2:
            return 17.0
        if rh >= 5.8:
            return 15.5
        if rh >= 5.4:
            return 15.0
        if rh >= 5.0:
            return 12.5
        if rh >= 4.5:
            return 11.0
        return 10.0
    if rh >= 6.2:
        return 10.0
    if rh >= 5.8:
        return 7.0
    if rh >= 5.4:
        return 6.0
    if rh >= 5.0:
        return 4.0
    if rh >= 4.5:
        return 3.0
    return 3.0


def _std_hb_right(pitch_type: str, rel_height: Optional[float]) -> Optional[float]:
    if pitch_type not in {"Fastball", "Sinker"} or not _is_num(rel_height):
        return None
    rh = float(rel_height)
    if pitch_type == "Fastball":
        if rh >= 6.2:
            return 9.0
        if rh >= 5.8:
            return 10.0
        if rh >= 5.4:
            return 11.0
        if rh >= 5.0:
            return 12.0
        if rh >= 4.5:
            return 13.0
        return 11.0
    if rh >= 6.2:
        return 15.0
    if rh >= 5.8:
        return 15.5
    if rh >= 5.4:
        return 16.7
    if rh >= 5.0:
        return 17.0
    if rh >= 4.5:
        return 17.0
    return 17.5


def _compute_stuff_by_pitch_type(
    rows: List[Dict[str, object]],
    base_type: str,
    level: str,
    annotate_key: Optional[str] = None,
) -> tuple[Optional[float], Dict[str, float]]:
    weight_tbl = PITCH_WEIGHTS_FB if base_type == "Fastball" else PITCH_WEIGHTS_SI
    seps_ivb = SEP_FB_IVB if base_type == "Fastball" else SEP_SI_IVB
    seps_hb = SEP_FB_HB if base_type == "Fastball" else SEP_SI_HB
    vel_avg = VELO_AVG_BY_LEVEL.get(level, VELO_AVG_BY_LEVEL["College"])

    base_vel = _mean(
        [row.get("rel_speed") for row in rows if row.get("pitch_type") == base_type]  # type: ignore[list-item]
    )
    base_ivb_val = _mean(
        [row.get("ivb") for row in rows if row.get("pitch_type") == base_type]  # type: ignore[list-item]
    )
    base_hb_val = _mean(
        [row.get("hb_adj") for row in rows if row.get("pitch_type") == base_type]  # type: ignore[list-item]
    )
    # Row-scoped queries (e.g., single pitch-type percentile baselines) may not
    # include any base-pitch rows. Use level/height-derived anchors so Stuff+
    # remains computable instead of returning null for entire pitch groups.
    base_ivb_fallback = _mean(
        [
            _std_ivb(base_type, row.get("rel_height") if _is_num(row.get("rel_height")) else None)
            for row in rows
        ]
    )
    base_hb_right_fallback = _mean(
        [
            _std_hb_right(base_type, row.get("rel_height") if _is_num(row.get("rel_height")) else None)
            for row in rows
        ]
    )
    base_hb_fallback = (-abs(float(base_hb_right_fallback))) if _is_num(base_hb_right_fallback) else None

    alpha = 4.0
    beta = 2.0
    values_by_type: Dict[str, List[float]] = {}

    for row in rows:
        pitch_type = str(row.get("pitch_type") or "")
        rel_speed = row.get("rel_speed")
        ivb = row.get("ivb")
        hb_adj = row.get("hb_adj")
        rel_height = row.get("rel_height")
        ext_value = row.get("ext_value")
        is_lefty = bool(row.get("is_lefty"))

        if pitch_type not in weight_tbl:
            continue
        if not (_is_num(rel_speed) and _is_num(ivb) and _is_num(hb_adj)):
            continue
        rel_speed = float(rel_speed)  # type: ignore[arg-type]
        ivb = float(ivb)  # type: ignore[arg-type]
        hb_adj = float(hb_adj)  # type: ignore[arg-type]

        std_ivb = _std_ivb(pitch_type, rel_height if _is_num(rel_height) else None)  # type: ignore[arg-type]
        std_hb_r = _std_hb_right(pitch_type, rel_height if _is_num(rel_height) else None)  # type: ignore[arg-type]
        std_hb = (-std_hb_r if is_lefty else std_hb_r) if std_hb_r is not None else None

        if pitch_type in {"Fastball", "Sinker"}:
            r_vel = rel_speed / max(vel_avg, 1e-6)
        else:
            off = OFF_OFF.get(pitch_type)
            if not _is_num(base_vel) or off is None:
                continue
            denom = float(base_vel) - off
            if abs(denom) < 1e-6:
                continue
            r_vel = rel_speed / denom

        r_vel = (r_vel**alpha) if r_vel < 1 else (r_vel**beta)
        if pitch_type in {"ChangeUp", "Splitter"}:
            r_vel = 1.0 / max(r_vel, 1e-6)

        if pitch_type == "Fastball":
            if not _is_num(std_ivb):
                continue
            r_ivb = ivb / float(std_ivb)
        elif pitch_type == "Sinker":
            if not _is_num(std_ivb):
                continue
            r_ivb = (float(std_ivb) / ivb) if ivb > 0 else 1.0
        elif base_type == "Sinker" and pitch_type in {"Cutter", "Sweeper"}:
            base_ivb_anchor = base_ivb_val if _is_num(base_ivb_val) else base_ivb_fallback
            if not _is_num(base_ivb_anchor):
                continue
            endpoint = float(base_ivb_anchor) + seps_ivb[pitch_type]
            if abs(endpoint) < 1e-6:
                continue
            r_ivb = abs(ivb - endpoint) / endpoint
        elif base_type == "Fastball" and pitch_type == "Sweeper":
            base_ivb_anchor = base_ivb_val if _is_num(base_ivb_val) else base_ivb_fallback
            if not _is_num(base_ivb_anchor):
                continue
            endpoint = float(base_ivb_anchor) + seps_ivb[pitch_type]
            if abs(endpoint) < 1e-6:
                continue
            r_ivb = abs(ivb - endpoint) / abs(endpoint)
        else:
            base_ivb_anchor = base_ivb_val if _is_num(base_ivb_val) else base_ivb_fallback
            if not _is_num(base_ivb_anchor):
                continue
            sep = abs(seps_ivb.get(pitch_type, 0.0))
            if sep < 1e-6:
                continue
            r_ivb = (float(base_ivb_anchor) - ivb) / sep

        if pitch_type == "Fastball":
            if not _is_num(std_hb):
                continue
            hb_mag = abs(hb_adj)
            std_mag = abs(float(std_hb))
            if std_mag < 1e-6:
                continue
            r_hb = max(hb_mag / std_mag, std_mag / max(hb_mag, 1e-6))
            if abs(hb_mag - std_mag) < 2:
                r_hb = 1.0
        elif pitch_type == "Sinker":
            if not _is_num(std_hb):
                continue
            denom = abs(float(std_hb))
            if denom < 1e-6:
                continue
            r_hb = abs(hb_adj / float(std_hb))
        elif pitch_type == "Curveball":
            base_hb_anchor = base_hb_val if _is_num(base_hb_val) else base_hb_fallback
            if not _is_num(base_hb_anchor):
                continue
            sep = abs(seps_hb.get("Curveball", 0.0))
            if sep < 1e-6:
                continue
            r_hb = abs(hb_adj - float(base_hb_anchor)) / sep
        elif base_type == "Sinker" and pitch_type in {"Sweeper", "Cutter"}:
            base_hb_anchor = base_hb_val if _is_num(base_hb_val) else base_hb_fallback
            if not _is_num(base_hb_anchor):
                continue
            endpoint = float(base_hb_anchor) + seps_hb[pitch_type]
            if abs(endpoint) < 1e-6:
                continue
            r_hb = abs(hb_adj) / abs(endpoint)
        elif base_type == "Sinker" and pitch_type in {"ChangeUp", "Splitter"}:
            base_hb_anchor = base_hb_val if _is_num(base_hb_val) else base_hb_fallback
            if not _is_num(base_hb_anchor):
                continue
            sep = seps_hb.get(pitch_type, 0.0)
            if abs(sep) < 1e-6:
                continue
            r_hb = (float(base_hb_anchor) - hb_adj) / sep
        else:
            base_hb_anchor = base_hb_val if _is_num(base_hb_val) else base_hb_fallback
            if not _is_num(base_hb_anchor):
                continue
            sep = seps_hb.get(pitch_type, 0.0)
            if abs(sep) < 1e-6:
                continue
            r_hb = (hb_adj - float(base_hb_anchor)) / sep

        r_ivb = min(r_ivb, 2.0)
        r_hb = min(r_hb, 2.0)

        weights = weight_tbl[pitch_type]
        w_ext = weights["w_ext"]
        w_raw_vel = weights["w_raw_vel"]
        base_scale = max(1.0 - (w_ext + w_raw_vel), 0.01)

        ext_target = EXT_TARGETS.get(pitch_type)
        if _is_num(ext_value) and ext_target is not None:
            ext_range = ext_target["great"] - ext_target["poor"]
            ext_range = ext_range if ext_range > 0 else 1.0
            ext_norm = (float(ext_value) - ext_target["avg"]) / ext_range  # type: ignore[arg-type]
            r_ext = min(max(1.0 + 0.25 * ext_norm, 0.8), 1.2)
        else:
            r_ext = 1.0

        bvt = BREAKING_VEL_TARGETS.get(pitch_type)
        if bvt is not None:
            vel_range = bvt["great"] - bvt["poor"]
            vel_range = vel_range if vel_range > 0 else 1.0
            vel_norm = (rel_speed - bvt["avg"]) / vel_range
            r_raw_vel = min(max(1.0 + 0.25 * vel_norm, 0.8), 1.2)
        else:
            r_raw_vel = 1.0

        raw = (
            (weights["w_vel"] * base_scale) * r_vel
            + (weights["w_ivb"] * base_scale) * r_ivb
            + (weights["w_hb"] * base_scale) * r_hb
            + w_ext * r_ext
            + w_raw_vel * r_raw_vel
        )
        stuff = round(raw * 100.0, 1)
        if annotate_key:
            try:
                row[annotate_key] = stuff
            except Exception:
                pass
        values_by_type.setdefault(pitch_type, []).append(stuff)

    avg_by_type: Dict[str, float] = {
        pitch_type: round(sum(vals) / len(vals), 1) for pitch_type, vals in values_by_type.items() if vals
    }
    all_vals = [value for vals in values_by_type.values() for value in vals]
    avg_stuff = round(sum(all_vals) / len(all_vals), 1) if all_vals else None
    return avg_stuff, avg_by_type


def _validate_school_code(value: str) -> str:
    school_code = (value or "").strip().upper()
    if not school_code:
        raise HTTPException(status_code=400, detail="school_code is required.")
    return school_code


def _parse_csv_list(value: Optional[str]) -> List[str]:
    text = (value or "").strip()
    if not text:
        return []
    delimiter = ";" if ";" in text else ","
    return [part.strip() for part in text.split(delimiter) if part.strip() and part.strip().lower() != "all"]


def _parse_name_list(value: Optional[str]) -> List[str]:
    text = (value or "").strip()
    if not text:
        return []
    # Names can contain commas ("Last, First"), so semicolon is the preferred delimiter.
    if ";" in text:
        parts = [part.strip() for part in text.split(";") if part.strip() and part.strip().lower() != "all"]
        return parts

    # Backward-compat: older clients may still send comma-joined names.
    comma_parts = [part.strip() for part in text.split(",") if part.strip() and part.strip().lower() != "all"]
    if len(comma_parts) >= 2 and len(comma_parts) % 2 == 0:
        rebuilt = [f"{comma_parts[i]}, {comma_parts[i + 1]}" for i in range(0, len(comma_parts), 2)]
        return rebuilt

    return [text] if text.lower() != "all" else []


def _parse_optional_float(value: Optional[str], field_name: str) -> Optional[float]:
    text = (value or "").strip()
    if not text:
        return None
    try:
        return float(text)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=f"{field_name} must be numeric.") from exc


def _parse_optional_int(value: Optional[str], field_name: str) -> Optional[int]:
    text = (value or "").strip()
    if not text:
        return None
    try:
        return int(text)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=f"{field_name} must be an integer.") from exc


def _apply_pitch_count_row_threshold(
    table_rows: List[Dict[str, Any]],
    pc_min: Optional[int] = None,
    pc_max: Optional[int] = None,
    bf_min: Optional[int] = None,
    bf_max: Optional[int] = None,
    ip_min: Optional[float] = None,
    ip_max: Optional[float] = None,
) -> List[Dict[str, Any]]:
    if (
        pc_min is None
        and pc_max is None
        and bf_min is None
        and bf_max is None
        and ip_min is None
        and ip_max is None
    ):
        return table_rows

    def _row_ip_to_decimal(value: Any) -> Optional[float]:
        if value is None:
            return None
        if _is_num(value):
            return float(value)
        outs = _pro_ip_string_to_outs(value)
        if outs is not None:
            return float(outs) / 3.0
        text = str(value).strip()
        if not text:
            return None
        try:
            return float(text)
        except Exception:
            return None

    filtered: List[Dict[str, Any]] = []
    for row in table_rows:
        # Pitching aggregate count is normally "#"; include fallbacks for
        # custom/alternate table modes to avoid accidental empty tables.
        if pc_min is not None or pc_max is not None:
            count_value = row.get("#")
            if not _is_num(count_value):
                count_value = row.get("P")
            if not _is_num(count_value):
                count_value = row.get("BF")
            if not _is_num(count_value):
                count_value = row.get("PA")
            if _is_num(count_value):
                total_pitches = int(float(count_value))
                if pc_min is not None and total_pitches < pc_min:
                    continue
                if pc_max is not None and total_pitches > pc_max:
                    continue

        if bf_min is not None or bf_max is not None:
            bf_value = row.get("BF")
            if not _is_num(bf_value):
                bf_value = row.get("PA")
            if not _is_num(bf_value):
                continue
            bf_num = int(float(bf_value))
            if bf_min is not None and bf_num < bf_min:
                continue
            if bf_max is not None and bf_num > bf_max:
                continue

        if ip_min is not None or ip_max is not None:
            ip_num = _row_ip_to_decimal(row.get("IP"))
            if ip_num is None:
                continue
            if ip_min is not None and ip_num < ip_min:
                continue
            if ip_max is not None and ip_num > ip_max:
                continue

        filtered.append(row)
    return filtered


def _normalize_session_type_filter(value: Optional[str]) -> Optional[str]:
    text = (value or "").strip().lower()
    if not text or text == "all":
        return None
    if "season" in text:
        return "Season"
    if "bull" in text or "prac" in text or text == "bp" or " bp" in text or "bp " in text:
        return "Bullpen"
    if "live" in text or "game" in text or "ab" in text:
        return "Live"
    return None


def _session_bucket_for_row(row: Dict[str, Any], team_markers_norm) -> Optional[str]:
    st_compact = re.sub(r"\s+", "", str(row.get("session_type_norm") or "").strip().lower())
    if "bull" in st_compact or "prac" in st_compact or st_compact == "bp":
        return "Bullpen"
    pitcher_team_code = _normalize_team_code(str(row.get("pitcher_team_code") or ""))
    batter_team_code = _normalize_team_code(str(row.get("batter_team_code") or ""))
    pitcher_is_marker = pitcher_team_code in team_markers_norm if pitcher_team_code else False
    batter_is_marker = batter_team_code in team_markers_norm if batter_team_code else False
    if pitcher_is_marker and batter_is_marker and bool(batter_team_code):
        return "Live"
    if pitcher_is_marker and bool(batter_team_code) and not batter_is_marker:
        return "Season"
    if batter_is_marker and bool(pitcher_team_code) and not pitcher_is_marker:
        return "Season"
    return None


def _norm_hand(value: Optional[str]) -> str:
    v = (value or "").strip().upper()
    if v.startswith("L"):
        return "Left"
    if v.startswith("R"):
        return "Right"
    return "Unknown"


def _bucket_metric(value: Optional[float], step: float, unit: str) -> str:
    if not _is_num(value):
        return "Unknown"
    v = float(value)
    start = int(v // step) * step
    end = start + step
    if unit:
        return f"{start:.1f}-{end:.1f} {unit}"
    return f"{start:.1f}-{end:.1f}"


def _convert_tilt_degrees_to_clock(value: float) -> str:
    # Mirrors Shiny convert_to_clock(): h24 = 6 + x/30 then 12-hour clock string.
    h24 = 6.0 + (float(value) / 30.0)
    h12 = ((h24 - 1.0) % 12.0) + 1.0
    hour = int(h12)
    mins = int(round((h12 - hour) * 60.0))
    if mins == 60:
        mins = 0
        hour = 1 if hour == 12 else hour + 1
    return f"{hour}:{mins:02d}"


def _normalize_clock_string(value: str) -> Optional[str]:
    text = (value or "").strip()
    if not text:
        return None
    parts = text.split(":")
    if len(parts) < 2:
        return None
    try:
        hour = int(parts[0])
        mins = int(parts[1])
    except ValueError:
        return None
    if mins < 0:
        mins = 0
    if mins > 59:
        mins = mins % 60
    if hour <= 0:
        hour = 12
    if hour > 12:
        hour = ((hour - 1) % 12) + 1
    return f"{hour}:{mins:02d}"


def _clock_string_to_tilt_degrees(value: str) -> Optional[float]:
    norm = _normalize_clock_string(value)
    if not norm:
        return None
    parts = norm.split(":")
    if len(parts) != 2:
        return None
    try:
        hour = int(parts[0])
        mins = int(parts[1])
    except ValueError:
        return None
    h12 = float(hour) + (float(mins) / 60.0)
    # Inverse of _convert_tilt_degrees_to_clock (using 12-hour representation).
    deg = (h12 - 6.0) * 30.0
    while deg <= -180.0:
        deg += 360.0
    while deg > 180.0:
        deg -= 360.0
    return deg


def _tilt_values_to_clock(values: List[Any]) -> Optional[str]:
    degree_vals: List[float] = []
    fallback_clock_vals: List[str] = []
    for raw in values:
        if raw is None:
            continue
        if _is_num(raw):
            degree_vals.append(float(raw))
            continue
        text = str(raw).strip()
        if not text:
            continue
        if ":" in text:
            deg = _clock_string_to_tilt_degrees(text)
            if _is_num(deg):
                degree_vals.append(float(deg))
            else:
                norm = _normalize_clock_string(text)
                if norm:
                    fallback_clock_vals.append(norm)
            continue
        try:
            degree_vals.append(float(text))
        except ValueError:
            continue
    if degree_vals:
        # Circular mean so values around wrap boundaries average correctly.
        x = sum(cos(radians(v)) for v in degree_vals)
        y = sum(sin(radians(v)) for v in degree_vals)
        if abs(x) < 1e-9 and abs(y) < 1e-9:
            return _convert_tilt_degrees_to_clock(sum(degree_vals) / len(degree_vals))
        mean_deg = degrees(atan2(y, x))
        return _convert_tilt_degrees_to_clock(mean_deg)
    if fallback_clock_vals:
        return fallback_clock_vals[0]
    return None


def _tilt_clock_from_vector(x_sum: Any, y_sum: Any, n: Any) -> Optional[str]:
    if not (_is_num(x_sum) and _is_num(y_sum) and _is_num(n)):
        return None
    n_i = int(float(n))
    if n_i <= 0:
        return None
    x = float(x_sum)
    y = float(y_sum)
    if abs(x) < 1e-9 and abs(y) < 1e-9:
        return None
    deg = degrees(atan2(y, x))
    return _convert_tilt_degrees_to_clock(deg)


def _movement_to_break_tilt_clock(ivb_value: Any, hb_value: Any) -> Optional[str]:
    if not _is_num(ivb_value) and not _is_num(hb_value):
        return None
    ivb = float(ivb_value) if _is_num(ivb_value) else 0.0
    hb = float(hb_value) if _is_num(hb_value) else 0.0
    if abs(ivb) < 1e-9 and abs(hb) < 1e-9:
        return None
    # Axes:
    # +HB -> 3:00, -HB -> 9:00, +IVB -> 12:00, -IVB -> 6:00.
    angle_deg = degrees(atan2(ivb, hb))
    hour_float = 3.0 - (angle_deg / 30.0)
    h12 = ((hour_float - 1.0) % 12.0) + 1.0
    hour = int(h12)
    mins = int(round((h12 - hour) * 60.0))
    if mins == 60:
        mins = 0
        hour = 1 if hour == 12 else hour + 1
    return f"{hour}:{mins:02d}"


EXPECTED_MOVEMENT_BALL_RADIUS_M = 0.0366
EXPECTED_MOVEMENT_BALL_MASS_KG = 0.145
EXPECTED_MOVEMENT_AIR_DENSITY_KG_M3 = 1.225
EXPECTED_MOVEMENT_LIFT_A = 0.336
EXPECTED_MOVEMENT_LIFT_B = 6.041
EXPECTED_MOVEMENT_MPH_TO_MPS = 0.44704
EXPECTED_MOVEMENT_FT_TO_M = 0.3048
EXPECTED_MOVEMENT_M_TO_IN = 39.3700787402
EXPECTED_MOVEMENT_RUBBER_TO_PLATE_FT = 60.5
EXPECTED_MOVEMENT_PLATE_DEPTH_FT = 17.0 / 12.0


def _tilt_degrees(value: Any) -> Optional[float]:
    if value is None:
        return None
    if _is_num(value):
        return float(value) % 360.0
    text = str(value).strip()
    if not text:
        return None
    if ":" in text or "." in text:
        separator = ":" if ":" in text else "."
        parts = text.split(separator)
        if len(parts) == 2:
            try:
                hour = int(parts[0])
                minute = int(parts[1])
            except ValueError:
                return None
            if 1 <= hour <= 12 and 0 <= minute <= 59:
                return ((((hour % 12) * 60.0 + minute) / 2.0) - 180.0) % 360.0
    try:
        return float(text) % 360.0
    except ValueError:
        return None


def _movement_break_tilt_degrees(ivb_value: Any, hb_value: Any) -> Optional[float]:
    if not (_is_num(ivb_value) and _is_num(hb_value)):
        return None
    ivb = float(ivb_value)
    hb = float(hb_value)
    if abs(ivb) < 1e-9 and abs(hb) < 1e-9:
        return None
    return (degrees(atan2(hb, ivb)) + 180.0) % 360.0


def _tilt_deviation_minutes(
    release_tilt: Any,
    break_tilt: Any,
    ivb_value: Any = None,
    hb_value: Any = None,
) -> Optional[float]:
    release_deg = _tilt_degrees(release_tilt)
    break_deg = _tilt_degrees(break_tilt)
    if break_deg is None:
        break_deg = _movement_break_tilt_degrees(ivb_value, hb_value)
    if release_deg is None or break_deg is None:
        return None
    delta_deg = ((break_deg - release_deg + 180.0) % 360.0) - 180.0
    return delta_deg * 2.0


def _tilt_deviation_from_averages(release_tilt_clock: Any, break_tilt_clock: Any) -> Optional[float]:
    """TiltDev computed from already-averaged rTilt/bTilt clock values (bTilt - rTilt),
    so the displayed TiltDev always reconciles with the displayed rTilt/bTilt columns.
    This intentionally differs from averaging each pitch's individual deviation, which
    can diverge from (avg bTilt - avg rTilt) whenever there's pitch-to-pitch tilt variance."""
    return _tilt_deviation_minutes(release_tilt_clock, break_tilt_clock)


def _format_tilt_deviation(value: Any) -> Optional[str]:
    if not _is_num(value):
        return None
    total_minutes = int(round(float(value)))
    sign = "+" if total_minutes > 0 else "-" if total_minutes < 0 else ""
    absolute = abs(total_minutes)
    return f"{sign}{absolute // 60}:{absolute % 60:02d}"


def _expected_movement_values(row: Dict[str, Any]) -> Optional[tuple[float, float]]:
    velocity = float(row.get("rel_speed")) if _is_num(row.get("rel_speed")) else None
    total_spin = float(row.get("spin_rate")) if _is_num(row.get("spin_rate")) else None
    extension = float(row.get("ext_value")) if _is_num(row.get("ext_value")) else None
    tilt_deg = _tilt_degrees(row.get("release_tilt"))
    active_spin = float(row.get("active_spin")) if _is_num(row.get("active_spin")) else None
    spin_eff = float(row.get("spin_eff")) if _is_num(row.get("spin_eff")) else None
    if velocity is None or velocity <= 0 or total_spin is None or total_spin <= 0:
        return None
    if extension is None or extension < 0 or tilt_deg is None:
        return None
    if active_spin is not None and not (0 <= active_spin <= total_spin * 1.05):
        active_spin = None
    if active_spin is None and spin_eff is not None:
        efficiency = spin_eff / 100.0 if spin_eff > 1 else spin_eff
        if 0 <= efficiency <= 1:
            active_spin = total_spin * efficiency
    if active_spin is None:
        return None

    ball_area = pi * EXPECTED_MOVEMENT_BALL_RADIUS_M * EXPECTED_MOVEMENT_BALL_RADIUS_M
    magnus_k = (
        0.5 * EXPECTED_MOVEMENT_AIR_DENSITY_KG_M3 * ball_area
    ) / EXPECTED_MOVEMENT_BALL_MASS_KG
    velocity_mps = velocity * EXPECTED_MOVEMENT_MPH_TO_MPS
    active_spin_rad_s = active_spin * (2.0 * pi / 60.0)
    spin_factor = EXPECTED_MOVEMENT_BALL_RADIUS_M * active_spin_rad_s / velocity_mps
    lift_coefficient = EXPECTED_MOVEMENT_LIFT_A * (
        1.0 - exp(-EXPECTED_MOVEMENT_LIFT_B * spin_factor)
    )
    flight_distance_ft = (
        EXPECTED_MOVEMENT_RUBBER_TO_PLATE_FT
        - EXPECTED_MOVEMENT_PLATE_DEPTH_FT
        - extension
    )
    if flight_distance_ft <= 0:
        return None
    distance_m = flight_distance_ft * EXPECTED_MOVEMENT_FT_TO_M
    magnitude_in = (
        0.5
        * magnus_k
        * lift_coefficient
        * distance_m
        * distance_m
        * EXPECTED_MOVEMENT_M_TO_IN
    )
    movement_angle = radians(tilt_deg - 180.0)
    expected_hb = magnitude_in * sin(movement_angle)
    expected_ivb = magnitude_in * cos(movement_angle)
    if not (_is_num(expected_hb) and _is_num(expected_ivb)):
        return None
    return expected_ivb, expected_hb


def _expected_movement_sql(axis: str, alias: str) -> str:
    component = "COS" if axis.lower() == "ivb" else "SIN"
    active_spin = (
        f"CASE WHEN {alias}.active_spin IS NOT NULL "
        f"AND {alias}.active_spin BETWEEN 0 AND ({alias}.spin_rate * 1.05) "
        f"THEN {alias}.active_spin "
        f"WHEN {alias}.spin_eff IS NOT NULL "
        f"AND (CASE WHEN {alias}.spin_eff > 1 THEN {alias}.spin_eff / 100.0 ELSE {alias}.spin_eff END) BETWEEN 0 AND 1 "
        f"THEN {alias}.spin_rate * (CASE WHEN {alias}.spin_eff > 1 THEN {alias}.spin_eff / 100.0 ELSE {alias}.spin_eff END) "
        "ELSE NULL END"
    )
    return f"""
      CASE
        WHEN {alias}.rel_speed > 0
          AND {alias}.spin_rate > 0
          AND {alias}.ext_value >= 0
          AND {alias}.release_tilt_deg IS NOT NULL
          AND {alias}.ivb IS NOT NULL
          AND {alias}.hb IS NOT NULL
          AND ({active_spin}) IS NOT NULL
          AND (60.5 - (17.0 / 12.0) - {alias}.ext_value) > 0
        THEN (
          0.5
          * ((0.5 * 1.225 * PI() * POWER(0.0366, 2)) / 0.145)
          * (0.336 * (
              1.0 - EXP(
                -6.041
                * (
                    0.0366
                    * (({active_spin}) * (2.0 * PI() / 60.0))
                    / ({alias}.rel_speed * 0.44704)
                  )
              )
            ))
          * POWER((60.5 - (17.0 / 12.0) - {alias}.ext_value) * 0.3048, 2)
          * 39.3700787402
          * {component}(RADIANS({alias}.release_tilt_deg - 180.0))
        )
        ELSE NULL
      END
    """


def _magnus_angle(expected_ivb: Any, expected_hb: Any) -> Optional[float]:
    if not (_is_num(expected_ivb) and _is_num(expected_hb)):
        return None
    ivb = abs(float(expected_ivb))
    hb = abs(float(expected_hb))
    if ivb <= 1e-9 and hb <= 1e-9:
        return None
    return degrees(atan2(ivb, hb))


def _tilt_deviation_sql(alias: str) -> str:
    derived_break_degrees = f"(DEGREES(ATAN2({alias}.hb, {alias}.ivb)) + 180.0)"
    break_degrees = f"COALESCE({alias}.break_tilt_deg, {derived_break_degrees})"
    return f"""
      CASE
        WHEN {alias}.release_tilt_deg IS NOT NULL
          AND (
            {alias}.break_tilt_deg IS NOT NULL
            OR (
              {alias}.ivb IS NOT NULL
              AND {alias}.hb IS NOT NULL
              AND (ABS({alias}.ivb) > 1e-9 OR ABS({alias}.hb) > 1e-9)
            )
          )
        THEN DEGREES(
          ATAN2(
            SIN(RADIANS(({break_degrees}) - {alias}.release_tilt_deg)),
            COS(RADIANS(({break_degrees}) - {alias}.release_tilt_deg))
          )
        ) * 2.0
        ELSE NULL
      END
    """


PRO_APPROACH_Y0_FT = 50.0
PRO_APPROACH_PLATE_Y_FT = 17.0 / 12.0
NVAA_REFERENCE_HEIGHT_FT = 2.5

# Pitch-type height slopes (degrees of VAA per foot of plate height), fit on
# the full available tracking history on 2026-07-28. PRO uses VAA derived from
# Statcast kinematics; non-PRO uses TrackMan's supplied VertApprAngle.
PRO_NVAA_HEIGHT_SLOPES: Dict[str, float] = {
    "Fastball": 1.069932,
    "Sinker": 1.087719,
    "Cutter": 1.160101,
    "Slider": 1.093302,
    "Sweeper": 1.118156,
    "Curveball": 0.954621,
    "ChangeUp": 1.066646,
    "Splitter": 1.032672,
}
NONPRO_NVAA_HEIGHT_SLOPES: Dict[str, float] = {
    "Fastball": 1.080691,
    "Sinker": 1.099532,
    "Cutter": 1.084449,
    "Slider": 1.036482,
    "Sweeper": 1.050659,
    "Curveball": 0.989419,
    "ChangeUp": 1.046724,
    "Splitter": 1.038772,
    "Knuckleball": 1.406087,
}
PRO_NVAA_DEFAULT_HEIGHT_SLOPE = 1.076471
NONPRO_NVAA_DEFAULT_HEIGHT_SLOPE = 1.062770


def _nvaa_height_slope(pitch_type: Any, is_pro: bool) -> float:
    pitch_type_clean = str(pitch_type or "").strip()
    slopes = PRO_NVAA_HEIGHT_SLOPES if is_pro else NONPRO_NVAA_HEIGHT_SLOPES
    fallback = PRO_NVAA_DEFAULT_HEIGHT_SLOPE if is_pro else NONPRO_NVAA_DEFAULT_HEIGHT_SLOPE
    return float(slopes.get(pitch_type_clean, fallback))


def _normalized_vaa_value(
    vaa: Any,
    plate_height: Any,
    pitch_type: Any,
    *,
    is_pro: bool,
) -> Optional[float]:
    if not (_is_num(vaa) and _is_num(plate_height)):
        return None
    result = float(vaa) + (
        _nvaa_height_slope(pitch_type, is_pro)
        * (NVAA_REFERENCE_HEIGHT_FT - float(plate_height))
    )
    return result if isfinite(result) else None


def _nvaa_sql(
    vaa_sql: str,
    plate_height_sql: str,
    pitch_type_sql: str,
    *,
    is_pro: bool,
) -> str:
    slopes = PRO_NVAA_HEIGHT_SLOPES if is_pro else NONPRO_NVAA_HEIGHT_SLOPES
    fallback = PRO_NVAA_DEFAULT_HEIGHT_SLOPE if is_pro else NONPRO_NVAA_DEFAULT_HEIGHT_SLOPE
    slope_cases = " ".join(
        f"WHEN {pitch_type_sql} = '{pitch_type}' THEN {slope:.6f}"
        for pitch_type, slope in slopes.items()
    )
    slope_sql = f"(CASE {slope_cases} ELSE {fallback:.6f} END)"
    return f"""
      CASE
        WHEN ({vaa_sql}) IS NULL OR ({plate_height_sql}) IS NULL THEN NULL
        ELSE ({vaa_sql}) + (
          {slope_sql}
          * ({NVAA_REFERENCE_HEIGHT_FT} - ({plate_height_sql}))
        )
      END
    """.strip()


def _pro_approach_angle_sql(axis: str, row_alias: str = "pe") -> str:
    if axis == "vertical":
        component_velocity = "vz0"
        component_acceleration = "az"
    elif axis == "horizontal":
        component_velocity = "vx0"
        component_acceleration = "ax"
    else:
        raise ValueError(f"Unsupported approach-angle axis: {axis}")

    y_delta = f"({PRO_APPROACH_Y0_FT} - {PRO_APPROACH_PLATE_Y_FT})"
    discriminant = (
        f"((POWER({row_alias}.vy0, 2))"
        f" - (2.0 * {row_alias}.ay * {y_delta}))"
    )
    vy_final = f"(-SQRT(GREATEST(0.0, {discriminant})))"
    time_to_plate = (
        f"(({vy_final} - {row_alias}.vy0)"
        f" / NULLIF({row_alias}.ay, 0.0))"
    )
    component_final = (
        f"({row_alias}.{component_velocity}"
        f" + ({row_alias}.{component_acceleration} * {time_to_plate}))"
    )
    return f"""
      CASE
        WHEN {row_alias}.vy0 IS NOT NULL
          AND {row_alias}.ay IS NOT NULL
          AND ABS({row_alias}.ay) >= 1e-9
          AND {discriminant} >= 0.0
          AND ABS({vy_final}) >= 1e-9
          AND {row_alias}.{component_velocity} IS NOT NULL
          AND {row_alias}.{component_acceleration} IS NOT NULL
        THEN -DEGREES(ATAN({component_final} / {vy_final}))
        ELSE NULL
      END
    """.strip()


def _infer_pro_vaa_haa_from_kinematics(row: Dict[str, Any]) -> tuple[Optional[float], Optional[float]]:
    vy0 = row.get("vy0")
    ay = row.get("ay")
    if not (_is_num(vy0) and _is_num(ay)):
        return None, None
    vy0_f = float(vy0)
    ay_f = float(ay)
    if abs(ay_f) < 1e-9:
        return None, None
    y0 = PRO_APPROACH_Y0_FT
    yf = PRO_APPROACH_PLATE_Y_FT
    disc = (vy0_f * vy0_f) - (2.0 * ay_f * (y0 - yf))
    if disc < 0:
        return None, None
    vy_f = -sqrt(max(0.0, disc))
    if not isfinite(vy_f) or abs(vy_f) < 1e-9:
        return None, None
    t = (vy_f - vy0_f) / ay_f
    if not isfinite(t):
        return None, None

    vaa: Optional[float] = None
    haa: Optional[float] = None
    if _is_num(row.get("vx0")) and _is_num(row.get("ax")):
        vx_f = float(row.get("vx0")) + (float(row.get("ax")) * t)
        haa = -degrees(atan(vx_f / vy_f))
    if _is_num(row.get("vz0")) and _is_num(row.get("az")):
        vz_f = float(row.get("vz0")) + (float(row.get("az")) * t)
        vaa = -degrees(atan(vz_f / vy_f))
    return vaa, haa


COUNT_RE_0: Dict[str, float] = {
    "0-0": 0.53,
    "1-0": 0.56,
    "2-0": 0.63,
    "3-0": 0.74,
    "0-1": 0.49,
    "1-1": 0.52,
    "2-1": 0.59,
    "3-1": 0.70,
    "0-2": 0.41,
    "1-2": 0.44,
    "2-2": 0.50,
    "3-2": 0.67,
}
OUT_BASE_RE: Dict[int, float] = {0: 0.53, 1: 0.29, 2: 0.11, 3: 0.0}
OUT_COUNT_SCALE: Dict[int, float] = {0: 1.0, 1: 0.8, 2: 0.6, 3: 0.0}


def _count_key(balls: Any, strikes: Any) -> str:
    b = int(float(balls)) if _is_num(balls) else 0
    s = int(float(strikes)) if _is_num(strikes) else 0
    b = min(max(b, 0), 3)
    s = min(max(s, 0), 2)
    return f"{b}-{s}"


def _state_re_no_runners(outs: Any, balls: Any, strikes: Any) -> float:
    outs_i = int(float(outs)) if _is_num(outs) else 0
    outs_i = min(max(outs_i, 0), 3)
    count_key = _count_key(balls, strikes)
    count_adj = COUNT_RE_0.get(count_key, COUNT_RE_0["0-0"]) - COUNT_RE_0["0-0"]
    return OUT_BASE_RE.get(outs_i, 0.0) + (count_adj * OUT_COUNT_SCALE.get(outs_i, 0.0))


def _calc_run_value(
    pitch_call: Any,
    play_result: Any,
    korbb: Any,
    balls: Any = None,
    strikes: Any = None,
    outs: Any = None,
    outs_on_play: Any = None,
) -> float:
    pc = str(pitch_call or "")
    pr = str(play_result or "")
    kb = str(korbb or "")
    outs_i = int(float(outs)) if _is_num(outs) else 0
    outs_i = min(max(outs_i, 0), 3)
    curr_re = _state_re_no_runners(outs_i, balls, strikes)

    # Terminal plate-appearance events: linear weights for reaching base/hits,
    # and count->outs transition for outs/strikeouts (no baserunner state available).
    if kb and kb != "NA":
        if kb == "Strikeout":
            next_re = _state_re_no_runners(min(3, outs_i + 1), 0, 0)
            return next_re - curr_re
        if kb == "Walk":
            return 0.33
    if pc == "HitByPitch" or pr in {"Walk", "IntentionalWalk", "HitByPitch"}:
        return 0.33
    if pc == "InPlay":
        outs_on_play_i = int(float(outs_on_play)) if _is_num(outs_on_play) else 0
        if outs_on_play_i > 0:
            next_re = _state_re_no_runners(min(3, outs_i + outs_on_play_i), 0, 0)
            return next_re - curr_re
        if pr == "Single":
            return 0.47
        if pr == "Double":
            return 0.78
        if pr == "Triple":
            return 1.09
        if pr == "HomeRun":
            return 1.40
        if pr == "Error":
            return 0.33
        return 0.0

    # Non-terminal pitch outcomes: run expectancy change from current count state.
    b = int(float(balls)) if _is_num(balls) else 0
    s = int(float(strikes)) if _is_num(strikes) else 0
    if pc in {"BallCalled", "BallIntentional", "BallinDirt"}:
        if b >= 3:
            return 0.33
        next_re = _state_re_no_runners(outs_i, b + 1, s)
        return next_re - curr_re
    if pc in {"StrikeCalled", "StrikeSwinging", "FoulBall", "FoulBallFieldable", "FoulBallNotFieldable"}:
        if pc in {"FoulBall", "FoulBallFieldable", "FoulBallNotFieldable"} and s >= 2:
            return 0.0
        if s >= 2:
            next_re = _state_re_no_runners(min(3, outs_i + 1), 0, 0)
            return next_re - curr_re
        next_re = _state_re_no_runners(outs_i, b, s + 1)
        return next_re - curr_re
    return 0.0


def _pv_count_adjust(balls: Any, strikes: Any) -> float:
    b = int(float(balls)) if _is_num(balls) else 0
    s = int(float(strikes)) if _is_num(strikes) else 0
    b = min(max(b, 0), 3)
    s = min(max(s, 0), 2)
    return max(-0.08, min(0.08, (float(b - s) * 0.02)))

PV_BASELINE_SHIFT_PRO = 0.024
PV_BASELINE_SHIFT_COLLEGE = 0.031


def _pv_baseline_shift_for_school_code(school_code: Any) -> float:
    code = str(school_code or "").strip().upper()
    if code == "PRO":
        return PV_BASELINE_SHIFT_PRO
    return PV_BASELINE_SHIFT_COLLEGE


def _calc_pitch_value(
    pitch_call: Any,
    play_result: Any,
    korbb: Any,
    balls: Any = None,
    strikes: Any = None,
    outs: Any = None,
    outs_on_play: Any = None,
    school_code: Any = None,
) -> float:
    # Positive value favors hitter; negative favors pitcher.
    raw_pitch_call = str(pitch_call or "")
    desc_norm = _pro_norm_token(raw_pitch_call)
    pitch_call_norm = _pro_pitch_call_from_description(desc_norm) if desc_norm else raw_pitch_call
    pc = str(pitch_call_norm or raw_pitch_call or "")
    pr = _canonical_play_result(play_result)
    kb = str(korbb or "")
    count_adj = _pv_count_adjust(balls, strikes)
    pv_baseline_shift = _pv_baseline_shift_for_school_code(school_code)

    # Terminal outcomes.
    if kb == "Strikeout" or _pro_norm_token(play_result) in {"strikeout", "strikeoutdoubleplay", "strikeout_double_play"}:
        return (-0.18 + (0.35 * count_adj)) - pv_baseline_shift
    if kb == "Walk" or pr in {"Walk", "IntentionalWalk"}:
        return (0.36 + (0.35 * count_adj)) - pv_baseline_shift
    if pc == "HitByPitch" or pr == "HitByPitch":
        return (0.34 + (0.35 * count_adj)) - pv_baseline_shift

    if pc == "InPlay" or pr in {
        "Single",
        "Double",
        "Triple",
        "HomeRun",
        "Error",
        "Out",
        "FieldersChoice",
        "Sacrifice",
        "DoublePlay",
        "TriplePlay",
    }:
        if pr == "Single":
            return 0.48 - pv_baseline_shift
        if pr == "Double":
            return 0.78 - pv_baseline_shift
        if pr == "Triple":
            return 1.09 - pv_baseline_shift
        if pr == "HomeRun":
            return 1.40 - pv_baseline_shift
        if pr == "Error":
            return 0.33 - pv_baseline_shift
        outs_on_play_i = int(float(outs_on_play)) if _is_num(outs_on_play) else 0
        if outs_on_play_i > 0 or pr in {"Out", "FieldersChoice", "Sacrifice", "DoublePlay", "TriplePlay"}:
            return -0.10 - pv_baseline_shift
        return -0.10 - pv_baseline_shift

    # Non-terminal pitch outcomes with count leverage.
    if pc in {"BallCalled", "BallIntentional", "BallinDirt"}:
        return (0.02 + (0.35 * count_adj)) - pv_baseline_shift
    if pc == "StrikeCalled":
        return (-0.03 + (0.35 * count_adj)) - pv_baseline_shift
    if pc == "StrikeSwinging":
        return (-0.05 + (0.35 * count_adj)) - pv_baseline_shift
    if pc in {"FoulBall", "FoulBallFieldable", "FoulBallNotFieldable"}:
        s = int(float(strikes)) if _is_num(strikes) else 0
        base = -0.005 if s >= 2 else -0.02
        return (base + (0.3 * count_adj)) - pv_baseline_shift
    return 0.0 - pv_baseline_shift


def _sql_state_re_no_runners_expr(outs_expr: str, balls_expr: str, strikes_expr: str) -> str:
    outs_c = f"LEAST(3, GREATEST(0, COALESCE({outs_expr}, 0)))"
    balls_c = f"LEAST(3, GREATEST(0, COALESCE({balls_expr}, 0)))"
    strikes_c = f"LEAST(2, GREATEST(0, COALESCE({strikes_expr}, 0)))"
    count_adj = (
        f"(CASE "
        f"WHEN {balls_c}=0 AND {strikes_c}=0 THEN 0.0 "
        f"WHEN {balls_c}=1 AND {strikes_c}=0 THEN 0.03 "
        f"WHEN {balls_c}=2 AND {strikes_c}=0 THEN 0.10 "
        f"WHEN {balls_c}=3 AND {strikes_c}=0 THEN 0.21 "
        f"WHEN {balls_c}=0 AND {strikes_c}=1 THEN -0.04 "
        f"WHEN {balls_c}=1 AND {strikes_c}=1 THEN -0.01 "
        f"WHEN {balls_c}=2 AND {strikes_c}=1 THEN 0.06 "
        f"WHEN {balls_c}=3 AND {strikes_c}=1 THEN 0.17 "
        f"WHEN {balls_c}=0 AND {strikes_c}=2 THEN -0.12 "
        f"WHEN {balls_c}=1 AND {strikes_c}=2 THEN -0.09 "
        f"WHEN {balls_c}=2 AND {strikes_c}=2 THEN -0.03 "
        f"WHEN {balls_c}=3 AND {strikes_c}=2 THEN 0.14 "
        f"ELSE 0.0 END)"
    )
    out_base = f"(CASE {outs_c} WHEN 0 THEN 0.53 WHEN 1 THEN 0.29 WHEN 2 THEN 0.11 ELSE 0.0 END)"
    out_scale = f"(CASE {outs_c} WHEN 0 THEN 1.0 WHEN 1 THEN 0.8 WHEN 2 THEN 0.6 ELSE 0.0 END)"
    return f"(({out_base}) + ({count_adj} * ({out_scale})))"


def _sql_run_value_expr(alias: str) -> str:
    outs = f"{alias}.outs_num"
    outs_on_play = f"{alias}.outs_on_play_num"
    balls = f"{alias}.balls_num"
    strikes = f"{alias}.strikes_num"
    pitch_call = f"COALESCE({alias}.pitch_call, '')"
    play_result = f"COALESCE({alias}.play_result, '')"
    korbb = f"COALESCE({alias}.korbb, '')"
    outs_next_1 = f"LEAST(3, GREATEST(0, COALESCE({outs}, 0) + 1))"
    outs_next_play = f"LEAST(3, GREATEST(0, COALESCE({outs}, 0) + COALESCE({outs_on_play}, 0)))"
    balls_c = f"LEAST(3, GREATEST(0, COALESCE({balls}, 0)))"
    strikes_c = f"LEAST(2, GREATEST(0, COALESCE({strikes}, 0)))"
    curr_re = _sql_state_re_no_runners_expr(outs, balls, strikes)
    next_re_ball = _sql_state_re_no_runners_expr(outs, f"({balls_c} + 1)", strikes)
    next_re_strike = _sql_state_re_no_runners_expr(outs, balls, f"({strikes_c} + 1)")
    next_re_out1 = _sql_state_re_no_runners_expr(outs_next_1, "0", "0")
    next_re_out_play = _sql_state_re_no_runners_expr(outs_next_play, "0", "0")
    return (
        f"(CASE "
        f"WHEN {korbb} = 'Strikeout' THEN ({next_re_out1}) - ({curr_re}) "
        f"WHEN {korbb} = 'Walk' THEN 0.33 "
        f"WHEN {pitch_call} = 'HitByPitch' OR {play_result} IN ('Walk','IntentionalWalk','HitByPitch') THEN 0.33 "
        f"WHEN {pitch_call} = 'InPlay' THEN "
        f"  (CASE "
        f"    WHEN COALESCE({outs_on_play}, 0) > 0 THEN ({next_re_out_play}) - ({curr_re}) "
        f"    WHEN {play_result} = 'Single' THEN 0.47 "
        f"    WHEN {play_result} = 'Double' THEN 0.78 "
        f"    WHEN {play_result} = 'Triple' THEN 1.09 "
        f"    WHEN {play_result} = 'HomeRun' THEN 1.40 "
        f"    WHEN {play_result} = 'Error' THEN 0.33 "
        f"    ELSE 0.0 END) "
        f"WHEN {pitch_call} IN ('BallCalled','BallIntentional','BallinDirt') THEN "
        f"  (CASE WHEN {balls_c} >= 3 THEN 0.33 ELSE ({next_re_ball}) - ({curr_re}) END) "
        f"WHEN {pitch_call} IN ('StrikeCalled','StrikeSwinging','FoulBall','FoulBallFieldable','FoulBallNotFieldable') THEN "
        f"  (CASE "
        f"    WHEN {pitch_call} IN ('FoulBall','FoulBallFieldable','FoulBallNotFieldable') AND {strikes_c} >= 2 THEN 0.0 "
        f"    WHEN {strikes_c} >= 2 THEN ({next_re_out1}) - ({curr_re}) "
        f"    ELSE ({next_re_strike}) - ({curr_re}) END) "
        f"ELSE 0.0 END)"
    )


def _sql_pitch_value_expr(alias: str, baseline_shift: float = PV_BASELINE_SHIFT_PRO) -> str:
    pitch_call = f"COALESCE({alias}.pitch_call, '')"
    play_result = f"COALESCE({alias}.play_result, '')"
    korbb = f"COALESCE({alias}.korbb, '')"
    outs_on_play = f"COALESCE({alias}.outs_on_play_num, 0)"
    balls = f"LEAST(3, GREATEST(0, COALESCE({alias}.balls_num, 0)))"
    strikes = f"LEAST(2, GREATEST(0, COALESCE({alias}.strikes_num, 0)))"
    count_adj = f"GREATEST(-0.08, LEAST(0.08, (({balls} - {strikes}) * 0.02)))"
    return (
        f"((CASE "
        f"WHEN {korbb} = 'Strikeout' THEN (-0.18 + (0.35 * ({count_adj}))) "
        f"WHEN {korbb} = 'Walk' OR {play_result} IN ('Walk','IntentionalWalk') THEN (0.36 + (0.35 * ({count_adj}))) "
        f"WHEN {pitch_call} = 'HitByPitch' OR {play_result} = 'HitByPitch' THEN (0.34 + (0.35 * ({count_adj}))) "
        f"WHEN {pitch_call} = 'InPlay' OR {play_result} IN ('Single','Double','Triple','HomeRun','Error','Out','FieldersChoice','Sacrifice','DoublePlay','TriplePlay') THEN "
        f"  (CASE "
        f"    WHEN {play_result} = 'Single' THEN 0.48 "
        f"    WHEN {play_result} = 'Double' THEN 0.78 "
        f"    WHEN {play_result} = 'Triple' THEN 1.09 "
        f"    WHEN {play_result} = 'HomeRun' THEN 1.40 "
        f"    WHEN {play_result} = 'Error' THEN 0.33 "
        f"    WHEN {outs_on_play} > 0 OR {play_result} IN ('Out','FieldersChoice','Sacrifice','DoublePlay','TriplePlay') THEN -0.10 "
        f"    ELSE -0.10 END) "
        f"WHEN {pitch_call} IN ('BallCalled','BallIntentional','BallinDirt') THEN (0.02 + (0.35 * ({count_adj}))) "
        f"WHEN {pitch_call} = 'StrikeCalled' THEN (-0.03 + (0.35 * ({count_adj}))) "
        f"WHEN {pitch_call} = 'StrikeSwinging' THEN (-0.05 + (0.35 * ({count_adj}))) "
        f"WHEN {pitch_call} IN ('FoulBall','FoulBallFieldable','FoulBallNotFieldable') THEN "
        f"  ((CASE WHEN {strikes} >= 2 THEN -0.005 ELSE -0.02 END) + (0.3 * ({count_adj}))) "
        f"ELSE 0.0 END) - {float(baseline_shift)})"
    )


COMP_LEFT = -1.5
COMP_RIGHT = 1.5
COMP_BOTTOM = ((ZONE_BOTTOM + ZONE_TOP) / 2.0) - 1.5
COMP_TOP = ((ZONE_BOTTOM + ZONE_TOP) / 2.0) + 1.5
COMP_PCT_BOTTOM = 2.65 - 1.7
COMP_PCT_TOP = 2.65 + 1.3


def _count_state(balls: Any, strikes: Any) -> str:
    if not (_is_num(balls) and _is_num(strikes)):
        return "Even"
    b = int(float(balls))
    s = int(float(strikes))
    if (b, s) in {(0, 1), (0, 2), (1, 2)}:
        return "Ahead"
    if (b, s) in {(1, 0), (2, 0), (3, 0), (3, 1), (2, 1)}:
        return "Behind"
    return "Even"


def _zone9_square(x: Any, y: Any) -> Optional[int]:
    if not (_is_num(x) and _is_num(y)):
        return None
    xf = float(x)
    yf = float(y)
    if not (COMP_LEFT <= xf <= COMP_RIGHT and COMP_BOTTOM <= yf <= COMP_TOP):
        return None
    w = COMP_RIGHT - COMP_LEFT
    h = COMP_TOP - COMP_BOTTOM
    gx = min(max((xf - COMP_LEFT) / w, 0.0), 1.0)
    gy = min(max((yf - COMP_BOTTOM) / h, 0.0), 1.0)
    col = 1 if gx < (1 / 3) else (2 if gx < (2 / 3) else 3)
    row = 1 if gy >= (2 / 3) else (2 if gy >= (1 / 3) else 3)
    return (row - 1) * 3 + col


def _in_zone_label(plate_side: Any, plate_height: Any) -> str:
    if not (_is_num(plate_side) and _is_num(plate_height)):
        return "No"
    ps = float(plate_side)
    ph = float(plate_height)
    if ZONE_LEFT <= ps <= ZONE_RIGHT and ZONE_BOTTOM <= ph <= ZONE_TOP:
        return "Yes"
    if COMP_LEFT <= ps <= COMP_RIGHT and COMP_BOTTOM <= ph <= COMP_TOP:
        return "Competitive"
    return "No"


def _pro_zone_num_in_zone_flag(row: Dict[str, Any]) -> Optional[bool]:
    zone_num = row.get("zone_num")
    if _is_num(zone_num):
        return 1 <= int(float(zone_num)) <= 9
    return None


def _pro_in_zone_yes(row: Dict[str, Any]) -> bool:
    zone_flag = _pro_zone_num_in_zone_flag(row)
    if zone_flag is not None:
        return zone_flag
    if not (_is_num(row.get("plate_side")) and _is_num(row.get("plate_height"))):
        return False
    ps = float(row.get("plate_side"))
    ph = float(row.get("plate_height"))
    return (ZONE_LEFT <= ps <= ZONE_RIGHT) and (ZONE_BOTTOM <= ph <= ZONE_TOP)


def _pro_in_zone_bucket(row: Dict[str, Any]) -> str:
    zone_flag = _pro_zone_num_in_zone_flag(row)
    if zone_flag is not None:
        return "Yes" if zone_flag else "No"
    if not (_is_num(row.get("plate_side")) and _is_num(row.get("plate_height"))):
        return "No"
    ps = float(row.get("plate_side"))
    ph = float(row.get("plate_height"))
    if (ZONE_LEFT <= ps <= ZONE_RIGHT) and (ZONE_BOTTOM <= ph <= ZONE_TOP):
        return "Yes"
    if (-1.5 <= ps <= 1.5) and (COMP_PCT_BOTTOM <= ph <= COMP_PCT_TOP):
        return "Competitive"
    return "No"


def _sq_to_rc(sq: int) -> tuple[int, int]:
    row = ((sq - 1) // 3) + 1
    col = ((sq - 1) % 3) + 1
    return row, col


def _qp_decay(state: str) -> List[float]:
    if state == "Ahead":
        return [1.00, 0.35, 0.15, 0.05]
    if state == "Even":
        return [1.00, 0.55, 0.25, 0.10]
    return [1.00, 0.75, 0.45, 0.20]  # Behind


def _qp_seeds_for(pitch_type: str, hand: str) -> List[tuple[int, int, float]]:
    hand_norm = "Left" if str(hand or "").strip().lower().startswith("l") else "Right"
    glove_col = 3 if hand_norm == "Left" else 1
    arm_col = 1 if glove_col == 3 else 3
    r_top, r_mid, r_bot = 1, 2, 3
    c_mid, c_g, c_a = 2, glove_col, arm_col
    pt = str(pitch_type or "")
    mapping: Dict[str, List[tuple[int, int, float]]] = {
        "Fastball": [(r_top, c_mid, 1.00), (r_top, c_g, 1.00), (r_top, c_a, 1.00)],
        "Sinker": [(r_bot, c_mid, 0.80), (r_bot, c_a, 1.00), (r_bot, c_g, 0.90)],
        "Cutter": [(r_mid, c_g, 1.00), (r_top, c_g, 1.00), (r_top, c_mid, 0.75), (r_bot, c_g, 0.80)],
        "Slider": [(r_bot, c_g, 1.00), (r_bot, c_mid, 0.80), (r_mid, c_g, 0.70)],
        "Sweeper": [(r_bot, c_g, 1.00), (r_bot, c_mid, 0.75), (r_mid, c_g, 0.65)],
        "Curveball": [(r_bot, c_mid, 1.00), (r_bot, c_g, 1.00), (r_bot, c_a, 1.00)],
        "ChangeUp": [(r_bot, c_mid, 1.00), (r_bot, c_a, 0.90), (r_bot, c_g, 0.70)],
        "Splitter": [(r_bot, c_mid, 1.00), (r_bot, c_a, 1.00), (r_bot, c_g, 1.00)],
    }
    return mapping.get(pt, [(r_mid, c_mid, 0.60)])


def _qp_weight_for_square(sq: Optional[int], pitch_type: str, hand: str, state: str) -> float:
    if sq is None:
        return 0.0
    row, col = _sq_to_rc(sq)
    decay = _qp_decay(state)
    best = 0.0
    for sr, sc, w in _qp_seeds_for(pitch_type, hand):
        d = abs(sr - row) + abs(sc - col)
        di = 3 if d >= 3 else d
        best = max(best, float(w) * decay[di])
    return best


def _compute_qp_point(row: Dict[str, Any]) -> Optional[float]:
    st = str(row.get("session_type_norm") or "").strip()
    s = st.lower()
    if not (("live" in s) or ("game" in s) or ("ab" in s) or ("season" in s)):
        return None
    sq = _zone9_square(row.get("plate_side"), row.get("plate_height"))
    if sq is None:
        return 0.0
    state = _count_state(row.get("balls_num"), row.get("strikes_num"))
    pitch_type = str(row.get("pitch_type") or "Undefined")
    hand = str(row.get("pitcherthrows") or ("Left" if row.get("is_lefty") else "Right"))
    return _qp_weight_for_square(sq, pitch_type, hand, state)


def _is_competitive_row(row: Dict[str, Any]) -> bool:
    st = str(row.get("session_type_norm") or "").strip().lower()
    return ("live" in st) or ("game" in st) or ("ab" in st) or ("season" in st)


_MONTH_ABBR = {
    1: "Jan", 2: "Feb", 3: "Mar", 4: "Apr", 5: "May", 6: "Jun",
    7: "Jul", 8: "Aug", 9: "Sep", 10: "Oct", 11: "Nov", 12: "Dec",
}


_MONTH_ABBR_RANK = {abbr: num for num, abbr in _MONTH_ABBR.items()}


def _year_or_month_split_sort_key(split_value: str) -> tuple[int, int, str]:
    # "Year" values are plain "2026"; "Month" values are "Jan 2026". Both need
    # chronological ordering rather than the pitch-count-descending default
    # used for most other splits (e.g. Pitcher Hand), since browsing multiple
    # seasons/months only makes sense in time order.
    raw = str(split_value or "").strip()
    month_match = re.match(r"^([A-Za-z]{3})\s+(\d{4})$", raw)
    if month_match:
        month_num = _MONTH_ABBR_RANK.get(month_match.group(1), 99)
        return (int(month_match.group(2)), month_num, raw)
    if raw.isdigit() and len(raw) == 4:
        return (int(raw), 0, raw)
    return (9999, 99, raw)


def _split_key_from_row(row: Dict[str, Any], split_by: str) -> str:
    split = (split_by or "Pitch Types").strip()
    if split == "All":
        return "All"
    if split == "Pitch Types":
        return str(row.get("pitch_type") or "Unknown")
    if split == "Year":
        session_value = row.get("session_date")
        if isinstance(session_value, date):
            return str(session_value.year)
        session_str = str(session_value or "").strip()
        return session_str[:4] if len(session_str) >= 4 and session_str[:4].isdigit() else "Unknown"
    if split == "Month":
        session_value = row.get("session_date")
        if isinstance(session_value, date):
            return f"{_MONTH_ABBR[session_value.month]} {session_value.year:04d}"
        session_str = str(session_value or "").strip()
        if len(session_str) >= 7 and session_str[:4].isdigit() and session_str[5:7].isdigit():
            year_part = session_str[:4]
            month_part = int(session_str[5:7])
            if 1 <= month_part <= 12:
                return f"{_MONTH_ABBR[month_part]} {year_part}"
        return "Unknown"
    if split == "Pitcher Hand":
        return _norm_hand(row.get("pitcherthrows"))
    if split == "Batter Hand":
        return _norm_hand(row.get("batterside"))
    if split == "Count":
        b = row.get("balls_num")
        s = row.get("strikes_num")
        return f"{b}-{s}" if b is not None and s is not None else "Unknown"
    if split == "After Count":
        b = row.get("prev_balls")
        s = row.get("prev_strikes")
        return f"{b}-{s}" if b is not None and s is not None else "Unknown"
    if split == "Venue":
        return _venue_bucket_for_row(row)
    if split == "Zone Location":
        ph = row.get("plate_height")
        ps = row.get("plate_side")
        is_lefty = bool(row.get("is_lefty"))
        if not _is_num(ph) or not _is_num(ps):
            return "Unknown"
        phf = float(ph)
        psf = float(ps)
        vert = "Upper Half" if phf >= ZONE_MID_Y else "Bottom Half"
        if is_lefty:
            horiz = "Glove Side Half" if psf >= ZONE_MID_X else "Arm Side Half"
        else:
            horiz = "Glove Side Half" if psf <= ZONE_MID_X else "Arm Side Half"
        return f"{vert} / {horiz}"
    if split == "Times Through Order":
        return str(row.get("times_through_order") or "Unknown")
    if split == "Inning":
        if bool(row.get("_inning_split_use_game_inning")):
            game_inning = str(row.get("game_inning_derived") or "").strip()
            if game_inning:
                return game_inning
            inning_num = _parse_inning_number(row.get("inning"))
            if inning_num is not None:
                return str(inning_num)
            outing_inning = str(row.get("inning_of_outing") or "").strip()
            return outing_inning or "Unknown"
        return str(row.get("inning_of_outing") or "Unknown")
    if split == "Pitch Count":
        return str(row.get("pitch_count_bin") or "Unknown")
    if split == "Velocity":
        return _bucket_metric(row.get("rel_speed"), 5.0, "mph")
    if split == "IVB":
        return _bucket_metric(row.get("ivb"), 5.0, "")
    if split == "HB":
        return _bucket_metric(row.get("hb"), 5.0, "")
    if split == "Pitcher":
        return str(row.get("pitcher") or "Unknown")
    if split == "Source":
        # Only meaningful once PRO rows can be merged into a school request
        # (see player_pro_links / pro_link_name) -- rows projected from
        # pro_pitch_events are tagged school_code="PRO" so they group
        # separately from the player's own school-tagged rows here.
        return "PRO" if str(row.get("school_code") or "").strip().upper() == "PRO" else "School"
    if split in {"Team", "Pitcher Team"}:
        norm = str(row.get("pitcher_team_norm") or "").strip()
        if norm:
            return norm
        raw = str(row.get("pitcherteam") or row.get("pitcher_team_code") or "").strip()
        return _normalize_team_code(raw) or "Unknown"
    if split == "Batter":
        return str(row.get("batter") or "Unknown")
    if split == "Batter Team":
        norm = str(row.get("batter_team_norm_eff") or row.get("batter_team_norm") or "").strip()
        if norm:
            return norm
        raw = str(row.get("batterteam") or row.get("batter_team_code") or "").strip()
        return _normalize_team_code(raw) or "Unknown"
    if split == "Catcher":
        return str(row.get("catcher") or "Unknown")
    if split == "Game":
        def _team_match_token(value: Any) -> str:
            raw = str(value or "").strip()
            if not raw:
                return ""
            mapped = _normalize_team_code(_league_team_code_from_value(raw))
            if mapped and mapped != "ALL":
                return mapped
            return _normalize_team_code(raw)

        session_value = row.get("session_date")
        if isinstance(session_value, date):
            session_date = session_value.isoformat()
        else:
            session_date = str(session_value or "").strip()
        pitcher_team_code = (
            _team_match_token(row.get("pitcher_team_norm"))
            or _team_match_token(row.get("pitcherteam"))
            or _team_match_token(row.get("pitcher_team_code"))
            or "Unknown"
        )
        batter_team_code = (
            _team_match_token(row.get("batter_team_norm_eff"))
            or _team_match_token(row.get("batter_team_norm"))
            or _team_match_token(row.get("batterteam"))
            or _team_match_token(row.get("batter_team_code"))
            or "Unknown"
        )
        # Use the canonical league code->name mapping for game split display labels.
        # If a code is unmapped, _league_team_label returns the original code.
        pitcher_team = _league_team_label(pitcher_team_code) if pitcher_team_code != "Unknown" else "Unknown"
        batter_team = _league_team_label(batter_team_code) if batter_team_code != "Unknown" else "Unknown"
        raw_game_key = str(
            row.get("game_pk")
            or row.get("game_id")
            or row.get("game_uid")
            or row.get("game_foreign_id")
            or row.get("_source_game_key")
            or _source_game_key_from_filename(row.get("source_file_name"))
            or ""
        ).strip()
        low_quality_game_key = (
            not raw_game_key
            or raw_game_key in {"-", "0", "UNKNOWN"}
            or (session_date and (raw_game_key == session_date or raw_game_key.startswith(f"{session_date}-")))
        )
        game_key = str(
            row.get("_derived_game_key") if low_quality_game_key else raw_game_key
        ).strip() or raw_game_key or "-"
        pitcher_marker = "?"
        batter_marker = "?"
        half_raw = str(
            row.get("inning_topbot")
            or row.get("inningtopbot")
            or row.get("half_inning")
            or row.get("inning_half")
            or row.get("half")
            or ""
        ).strip().lower()
        pitcher_is_home: Optional[bool] = None
        if half_raw.startswith("top"):
            pitcher_is_home = True
        elif half_raw.startswith("bottom"):
            pitcher_is_home = False
        if pitcher_is_home is None:
            home_team = (
                _team_match_token(row.get("home_team_code"))
                or _team_match_token(row.get("hometeam"))
                or _team_match_token(row.get("home_team"))
            )
            away_team = (
                _team_match_token(row.get("away_team_code"))
                or _team_match_token(row.get("awayteam"))
                or _team_match_token(row.get("away_team"))
            )
            if home_team and away_team:
                if pitcher_team_code == home_team and batter_team_code == away_team:
                    pitcher_is_home = True
                elif pitcher_team_code == away_team and batter_team_code == home_team:
                    pitcher_is_home = False
                elif batter_team_code == home_team and pitcher_team_code == away_team:
                    pitcher_is_home = False
                elif batter_team_code == away_team and pitcher_team_code == home_team:
                    pitcher_is_home = True
        if pitcher_is_home is not None:
            pitcher_marker = "vs." if pitcher_is_home else "@"
            batter_marker = "@" if pitcher_is_home else "vs."
        return f"{session_date}||{pitcher_team}||{batter_team}||{game_key}||{pitcher_marker}||{batter_marker}"
    return str(row.get("pitch_type") or "Unknown")


def _times_through_order_label(pa_ord: int) -> str:
    if pa_ord <= 0:
        return "Unknown"
    if pa_ord <= 9:
        return "1"
    if pa_ord <= 18:
        return "2"
    if pa_ord <= 27:
        return "3"
    return "4+"


def _parse_inning_number(value: Any) -> Optional[int]:
    if _is_num(value):
        try:
            return int(float(value))
        except Exception:
            return None
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        return int(float(raw))
    except Exception:
        pass
    m = re.search(r"\d+", raw)
    if not m:
        return None
    try:
        return int(m.group(0))
    except Exception:
        return None


def _source_game_key_from_filename(value: Any) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    base = os.path.basename(raw)
    if base.lower().endswith(".csv"):
        base = base[:-4]
    # Strip ingest-status suffixes so reprocessed files map to the same game key.
    base = re.sub(r"_(verified|unverified)$", "", base, flags=re.IGNORECASE)
    m = re.search(r"(\d{8}-[A-Za-z0-9]+-\d+)$", base)
    if m:
        return m.group(1)
    return base


def _annotate_derived_game_keys(rows: List[Dict[str, Any]]) -> None:
    if not rows:
        return

    def _explicit_game_key(rr: Dict[str, Any]) -> str:
        return str(
            rr.get("game_pk")
            or rr.get("game_id")
            or rr.get("game_uid")
            or rr.get("game_foreign_id")
            or rr.get("_source_game_key")
            or _source_game_key_from_filename(rr.get("source_file_name"))
            or ""
        ).strip()

    def _order(rr: Dict[str, Any]) -> tuple:
        return (
            str(rr.get("session_date") or ""),
            str(_explicit_game_key(rr) or ""),
            int(rr.get("at_bat_index") or 0),
            int(rr.get("event_index") or 0),
            int(rr.get("pitch_number") or 0),
            int(rr.get("id") or rr.get("pitch_event_id") or 0),
        )

    rows_sorted = sorted(rows, key=_order)
    segments: Dict[str, int] = {}
    max_inning_by_cluster: Dict[str, int] = {}
    prev_ab_by_cluster: Dict[str, int] = {}

    def _is_low_quality_game_key(game_key: str, session_key: str) -> bool:
        gk = str(game_key or "").strip()
        if not gk or gk in {"-", "0", "UNKNOWN"}:
            return True
        if session_key and gk == session_key:
            return True
        if session_key and gk.startswith(session_key):
            # Date-prefixed placeholders (common in some feeds) are not reliable
            # as unique game identifiers for doubleheaders.
            tail = gk[len(session_key):]
            if tail in {"", "_", "-", "|"}:
                return True
        return False

    prev_inning_by_cluster: Dict[str, int] = {}
    prev_ticks_by_cluster: Dict[str, int] = {}
    tick_gap_reset_threshold = 20 * 60 * 10_000_000  # 20 minutes in UUID1 100ns ticks
    for rr in rows_sorted:
        explicit_key = _explicit_game_key(rr)
        session_key = _session_date_key(rr.get("session_date")) or "unknown-date"
        pitcher_code = _normalize_team_code(str(rr.get("pitcher_team_code") or rr.get("pitcherteam") or ""))
        batter_code = _normalize_team_code(str(rr.get("batter_team_code") or rr.get("batterteam") or ""))
        home_code = _normalize_team_code(str(rr.get("home_team_code") or rr.get("hometeam") or ""))
        away_code = _normalize_team_code(str(rr.get("away_team_code") or rr.get("awayteam") or ""))
        explicit_part = "" if _is_low_quality_game_key(explicit_key, session_key) else explicit_key
        cluster_key = f"{session_key}|{pitcher_code}|{batter_code}|{home_code}|{away_code}|{explicit_part}"
        is_fallback_cluster = explicit_part == ""

        current_segment = segments.get(cluster_key, 1)
        inning_num = _parse_inning_number(rr.get("inning"))
        prev_max_inning = max_inning_by_cluster.get(cluster_key, 0)
        prev_inning = prev_inning_by_cluster.get(cluster_key, 0)
        ab_idx = int(rr.get("at_bat_index") or 0)
        prev_ab = prev_ab_by_cluster.get(cluster_key, 0)
        curr_ticks = _uuid1_ticks(rr.get("pitch_uid"))
        prev_ticks = prev_ticks_by_cluster.get(cluster_key)

        inning_reset = (
            inning_num is not None
            and prev_max_inning >= 7
            and inning_num <= 2
            and inning_num < prev_max_inning
        )
        inning_drop_reset = False
        ab_reset = prev_ab >= 18 and ab_idx > 0 and ab_idx < prev_ab
        tick_gap_reset = (
            curr_ticks is not None
            and prev_ticks is not None
            and curr_ticks > prev_ticks
            and (curr_ticks - prev_ticks) >= tick_gap_reset_threshold
        )
        should_split = inning_reset or inning_drop_reset or ab_reset or tick_gap_reset
        if should_split and is_fallback_cluster and current_segment >= 2:
            should_split = False
        if should_split:
            current_segment += 1
            max_inning_by_cluster[cluster_key] = 0
            prev_ab_by_cluster[cluster_key] = 0

        segments[cluster_key] = current_segment
        if inning_num is not None:
            max_inning_by_cluster[cluster_key] = max(max_inning_by_cluster.get(cluster_key, 0), inning_num)
            prev_inning_by_cluster[cluster_key] = inning_num
        if ab_idx > 0:
            prev_ab_by_cluster[cluster_key] = ab_idx
        if curr_ticks is not None:
            prev_ticks_by_cluster[cluster_key] = curr_ticks

        rr["_derived_game_key"] = f"{session_key}|{pitcher_code or 'UNK'}|{batter_code or 'UNK'}|g{current_segment}"


def _uuid1_ticks(value: Any) -> Optional[int]:
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        u = uuid.UUID(raw)
        if u.version != 1:
            return None
        return int(u.time)
    except Exception:
        return None


def _annotate_game_inning(rows: List[Dict[str, Any]]) -> None:
    if not rows:
        return
    grouped: Dict[str, List[Dict[str, Any]]] = {}
    for row in rows:
        game_key = (
            str(row.get("game_id") or "").strip()
            or str(row.get("game_uid") or "").strip()
            or str(row.get("game_foreign_id") or "").strip()
            or str(row.get("session_date") or "").strip()
            or "unknown_game"
        )
        grouped.setdefault(game_key, []).append(row)

    def _row_sort_key(row: Dict[str, Any]) -> tuple:
        return (
            str(row.get("session_date") or ""),
            int(float(row.get("pitch_number"))) if _is_num(row.get("pitch_number")) else 0,
            int(float(row.get("pitch_no"))) if _is_num(row.get("pitch_no")) else 0,
            int(float(row.get("pitch_event_id"))) if _is_num(row.get("pitch_event_id")) else 0,
            int(float(row.get("id"))) if _is_num(row.get("id")) else 0,
        )

    for bucket in grouped.values():
        ordered = sorted(bucket, key=_row_sort_key)
        current_inning = 1
        cumulative_outs = 0
        last_explicit_inning: Optional[int] = None
        prev_uid_ticks: Optional[int] = None
        for row in ordered:
            explicit_inning = _parse_inning_number(row.get("inning"))
            curr_uid_ticks = _uuid1_ticks(row.get("pitch_uid"))

            if explicit_inning is not None:
                # Double-header/game-boundary reset:
                # when we see a fresh inning 1 after being deep into a prior game.
                if (
                    explicit_inning == 1
                    and last_explicit_inning is not None
                    and last_explicit_inning >= 7
                ):
                    cumulative_outs = 0
                current_inning = max(1, explicit_inning)
                last_explicit_inning = explicit_inning
                # Keep fallback-derived rows aligned to explicit inning when available.
                cumulative_outs = max(0, (current_inning - 1) * 3)
            else:
                # If game ids are missing, detect likely game boundary in double-headers
                # via large timestamp gap between UUIDv1 pitch ids.
                if (
                    curr_uid_ticks is not None
                    and prev_uid_ticks is not None
                    and curr_uid_ticks > prev_uid_ticks
                    and (curr_uid_ticks - prev_uid_ticks) > int(75 * 60 * 10_000_000)
                    and current_inning >= 7
                ):
                    cumulative_outs = 0
                    current_inning = 1
                    last_explicit_inning = None
                # All-pitchers game-level fallback requested:
                # treat the full game as one continuous outing and advance inning
                # every 3 recorded outs across terminal PAs.
                current_inning = max(1, (cumulative_outs // 3) + 1)

            row["game_inning_derived"] = str(max(1, current_inning))
            if _ab_is_terminal(row):
                add_outs = 0
                outs_on_play = row.get("outs_on_play_num")
                if _is_num(outs_on_play):
                    try:
                        add_outs = int(float(outs_on_play))
                    except Exception:
                        add_outs = 0
                if add_outs <= 0:
                    korbb = str(row.get("korbb") or "")
                    play_result = str(row.get("play_result") or "")
                    if korbb == "Strikeout":
                        add_outs = 1
                    elif play_result in {"Out", "FieldersChoice", "Sacrifice"}:
                        add_outs = 1
                    elif "DoublePlay" in play_result:
                        add_outs = 2
                    elif "TriplePlay" in play_result:
                        add_outs = 3
                if add_outs > 0:
                    cumulative_outs += add_outs
            if curr_uid_ticks is not None:
                prev_uid_ticks = curr_uid_ticks


def _annotate_times_through_order(rows: List[Dict[str, Any]]) -> None:
    if not rows:
        return
    grouped: Dict[str, List[Dict[str, Any]]] = {}
    for row in rows:
        game_key = (
            str(row.get("game_id") or "").strip()
            or str(row.get("game_uid") or "").strip()
            or str(row.get("game_foreign_id") or "").strip()
            or str(row.get("session_date") or "").strip()
            or "unknown_game"
        )
        pitcher_key = str(row.get("pitcher") or "").strip() or "unknown_pitcher"
        grouped.setdefault(f"{game_key}|{pitcher_key}", []).append(row)

    def _row_sort_key(row: Dict[str, Any]) -> tuple:
        return (
            str(row.get("session_date") or ""),
            int(float(row.get("pitch_number"))) if _is_num(row.get("pitch_number")) else 0,
            int(float(row.get("pitch_no"))) if _is_num(row.get("pitch_no")) else 0,
            int(float(row.get("pitch_event_id"))) if _is_num(row.get("pitch_event_id")) else 0,
            int(float(row.get("id"))) if _is_num(row.get("id")) else 0,
        )

    for bucket in grouped.values():
        ordered = sorted(bucket, key=_row_sort_key)
        pa_order_by_play: Dict[str, int] = {}
        pa_counter = 0
        prev_terminal = True
        prev_batter = ""
        # Per user rule: inning-of-outing should be based on the explicit inning value
        # for that pitcher/game, re-indexed to 1..N (relievers start at 1 automatically).
        inning_rank_map: Dict[int, int] = {}
        next_inning_rank = 0
        cumulative_outs_fallback = 0
        outs_reset_inning_rank = 1
        last_outs_num_for_reset: Optional[int] = None
        for idx, row in enumerate(ordered, start=1):
            row["pitch_count_in_game"] = idx
            bin_start = ((idx - 1) // 10) * 10 + 1
            row["pitch_count_bin"] = f"{bin_start}-{bin_start + 9}"
            is_pro_row = str(row.get("school_code") or "").strip().upper() == "PRO"
            pro_ab_idx = str(row.get("at_bat_index") or "").strip()
            pro_game_pk = str(row.get("game_pk") or "").strip()
            pa_key = ""
            if is_pro_row and pro_ab_idx:
                pa_key = f"ab:{pro_game_pk}|{pro_ab_idx}"
            else:
                pa_key = str(row.get("play_id") or "").strip()

            if pa_key:
                pa_ord = pa_order_by_play.get(pa_key)
                if pa_ord is None:
                    pa_counter += 1
                    pa_ord = pa_counter
                    pa_order_by_play[pa_key] = pa_ord
            else:
                batter = str(row.get("batter") or "").strip()
                starts_new_pa = prev_terminal or (bool(prev_batter) and bool(batter) and batter != prev_batter)
                if starts_new_pa:
                    pa_counter += 1
                if pa_counter <= 0:
                    pa_counter = 1
                pa_ord = pa_counter
                if batter:
                    prev_batter = batter
            row["times_through_order"] = _times_through_order_label(pa_ord)
            inning_num = _parse_inning_number(row.get("inning"))
            if inning_num is not None:
                if inning_num not in inning_rank_map:
                    next_inning_rank += 1
                    inning_rank_map[inning_num] = next_inning_rank
                row["inning_of_outing"] = str(inning_rank_map[inning_num])
            else:
                # College fallback requested: infer inning boundaries from outs reset.
                # New outing inning starts when outs goes from 1/2 back to 0.
                used_outs_reset = False
                if not is_pro_row and _is_num(row.get("outs_num")):
                    try:
                        curr_outs = int(float(row.get("outs_num")))
                    except Exception:
                        curr_outs = None
                    if curr_outs in {0, 1, 2}:
                        if last_outs_num_for_reset in {1, 2} and curr_outs == 0:
                            outs_reset_inning_rank += 1
                        last_outs_num_for_reset = curr_outs
                        row["inning_of_outing"] = str(max(1, outs_reset_inning_rank))
                        used_outs_reset = True

                if not used_outs_reset:
                    # Generic fallback when explicit inning and usable outs are unavailable.
                    row["inning_of_outing"] = str(max(1, int(cumulative_outs_fallback // 3) + 1))
                    if _ab_is_terminal(row):
                        add_outs = 0
                        outs_on_play = row.get("outs_on_play_num")
                        if _is_num(outs_on_play):
                            try:
                                add_outs = int(float(outs_on_play))
                            except Exception:
                                add_outs = 0
                        if add_outs <= 0:
                            korbb = str(row.get("korbb") or "")
                            play_result = str(row.get("play_result") or "")
                            if korbb == "Strikeout":
                                add_outs = 1
                            elif play_result in {"Out", "FieldersChoice", "Sacrifice"}:
                                add_outs = 1
                            elif "DoublePlay" in play_result:
                                add_outs = 2
                            elif "TriplePlay" in play_result:
                                add_outs = 3
                        if add_outs > 0:
                            cumulative_outs_fallback += add_outs
            prev_terminal = _ab_is_terminal(row)


def _pitch_type_sort_rank(name: str) -> int:
    order = {
        "Fastball": 1,
        "Sinker": 2,
        "Cutter": 3,
        "Slider": 4,
        "Sweeper": 5,
        "Curveball": 6,
        "ChangeUp": 7,
        "Splitter": 8,
        "Knuckleball": 9,
        "Undefined": 10,
    }
    return order.get((name or "").strip(), 99)


def _valid_pitch_types(values: List[str]) -> List[str]:
    return [value for value in values if str(value or "").strip() and str(value).strip() != "Undefined"]


