def _compute_siera_value(
    strikeouts: int,
    plate_appearances: int,
    walks: int,
    ground_balls: int,
    fly_balls: int,
    pop_ups: int,
) -> Optional[float]:
    pa = float(plate_appearances or 0)
    if pa <= 0:
        return None
    so_pa = float(strikeouts or 0) / pa
    bb_pa = float(walks or 0) / pa
    gb_fb_pu_pa = (float(ground_balls or 0) - float(fly_balls or 0) - float(pop_ups or 0)) / pa
    siera = (
        6.145
        - (16.986 * so_pa)
        + (11.434 * bb_pa)
        - (1.858 * gb_fb_pu_pa)
        + (7.653 * (so_pa ** 2))
        - (6.664 * (gb_fb_pu_pa ** 2))
        + (10.130 * so_pa * gb_fb_pu_pa)
        - (5.195 * bb_pa * gb_fb_pu_pa)
    )
    if not isfinite(siera):
        return None
    return round(float(siera), 2)


def _normalize_batted_ball_tag(value: Any) -> str:
    return re.sub(r"[^a-z0-9]+", "_", str(value or "").strip().lower()).strip("_")


def _is_ground_ball_tag(value: Any) -> bool:
    token = _normalize_batted_ball_tag(value)
    return ("ground_ball" in token) or ("groundball" in token)


def _is_popup_tag(value: Any) -> bool:
    token = _normalize_batted_ball_tag(value)
    return ("popup" in token) or ("pop_up" in token)


def _is_xfip_fly_ball_tag(value: Any) -> bool:
    token = _normalize_batted_ball_tag(value)
    # xFIP should use fly balls only (exclude pop-ups and line drives).
    return (
        ("fly_ball" in token)
        or ("flyball" in token)
    )


def _is_fly_ball_for_siera_tag(value: Any) -> bool:
    token = _normalize_batted_ball_tag(value)
    # Treat line drives as fly balls for SIERA/fly-ball family metrics.
    return (
        ("fly_ball" in token)
        or ("flyball" in token)
        or ("line_drive" in token)
        or ("linedrive" in token)
    )


def _is_fastball_or_sinker_pitch_type(value: Any) -> bool:
    token = re.sub(r"[^a-z0-9]+", "", str(value or "").strip().lower())
    return token in {
        "fastball",
        "fourseamfastball",
        "4seamfastball",
        "fourseam",
        "ff",
        "fa",
        "sinker",
        "oneseamfastball",
        "twoseamfastball",
        "twoseamfasball",
        "twoseam",
        "si",
        "ft",
    }


def _fps_swing_count_from_rollup_row(row: Dict[str, Any]) -> int:
    return int(row.get("fps_swing_num") or row.get("fps_num") or 0)


def _pitch_type_family(value: Any) -> str:
    token = re.sub(r"[^a-z0-9]+", "", str(value or "").strip().lower())
    if token in {"fastball", "fourseamfastball", "4seamfastball", "fourseam", "ff", "fa"}:
        return "Fastball"
    if token in {"sinker", "oneseamfastball", "twoseamfastball", "twoseamfasball", "twoseam", "si", "ft"}:
        return "Sinker"
    if token in {"cutter", "fc"}:
        return "Cutter"
    if token in {"slider", "sl"}:
        return "Slider"
    if token in {"sweeper", "st"}:
        return "Sweeper"
    if token in {"curveball", "curve", "cu", "kc", "slurve", "sv"}:
        return "Curveball"
    if token in {"changeup", "change", "ch", "circlechange"}:
        return "ChangeUp"
    if token in {"splitter", "split", "splitfinger", "sp", "fs"}:
        return "Splitter"
    return "Other"


def _derive_pro_fip_context(rows: List[Dict[str, Any]]) -> tuple[float, float]:
    """Return (FIP constant, league HR/FB) derived from current PRO row set."""
    fallback_fip_const = 3.2
    fallback_lg_hr_fb = 0.12
    pro_rows = [r for r in rows if str(r.get("school_code") or "").strip().upper() == "PRO"]
    if not pro_rows:
        return fallback_fip_const, fallback_lg_hr_fb

    # Filtered PRO views (single pitcher/team or very short windows) can produce
    # unstable "league" constants that inflate/deflate xFIP materially. For narrow
    # subsets, keep constants fixed to the standard fallback values.
    unique_pitchers = {
        _normalize_name_key(str(r.get("pitcher") or ""))
        for r in pro_rows
        if str(r.get("pitcher") or "").strip()
    }
    unique_teams = {
        str(r.get("pitcher_team_code") or r.get("pitcher_team_norm") or "").strip().upper()
        for r in pro_rows
        if str(r.get("pitcher_team_code") or r.get("pitcher_team_norm") or "").strip()
    }
    if len(unique_pitchers) < 20 or len(unique_teams) < 10:
        return fallback_fip_const, fallback_lg_hr_fb

    def _norm_desc_local(value: Any) -> str:
        normalized = re.sub(r"[^a-z0-9]+", "_", str(value or "").strip().lower()).strip("_")
        if normalized == "swinging_strike_blocked":
            return "swinging_strike"
        return normalized

    def _pa_key_local(r: Dict[str, Any]) -> str:
        game_pk = str(r.get("game_pk") or r.get("game_id") or "").strip()
        ab_idx = str(r.get("at_bat_index") or "").strip()
        if game_pk and ab_idx:
            return f"{game_pk}|ab|{ab_idx}"
        fallback = str(r.get("id") or r.get("pitch_no") or r.get("pitch_number") or "").strip()
        return f"{game_pk}|pitch|{fallback or 'unknown'}"

    pa_result_by_key: Dict[str, str] = {}
    pa_hbp_by_pitch_call: Set[str] = set()
    for r in pro_rows:
        key = _pa_key_local(r)
        play_result = _canonical_play_result(r.get("play_result"))
        if play_result:
            pa_result_by_key[key] = play_result
        if str(r.get("pitch_call") or "").strip() == "HitByPitch":
            pa_hbp_by_pitch_call.add(key)

    # League totals for FIP/xFIP components (PA-distinct terminal outcomes).
    result_values = list(pa_result_by_key.values())
    k_total = sum(1 for pr in result_values if pr == "Strikeout")
    bb_total = sum(1 for pr in result_values if pr in {"Walk", "IntentionalWalk"})
    hbp_total = max(sum(1 for pr in result_values if pr == "HitByPitch"), len(pa_hbp_by_pitch_call))
    hr_total = sum(1 for pr in result_values if pr == "HomeRun")

    pa_flyball_keys: Set[str] = set()
    for r in pro_rows:
        if _is_xfip_fly_ball_tag(r.get("tagged_hit_type")):
            pa_flyball_keys.add(_pa_key_local(r))
    fb_total = len(pa_flyball_keys)
    lg_hr_fb = (float(hr_total) / float(fb_total)) if fb_total > 0 else fallback_lg_hr_fb

    # Prefer official boxscore totals for league ERA/IP.
    official_er = 0.0
    official_outs = 0
    per_game_pitcher: Dict[tuple[str, str], tuple[Optional[float], Optional[int]]] = {}
    for r in pro_rows:
        game_key = str(r.get("game_pk") or r.get("game_id") or "").strip()
        pitcher_key = _normalize_name_key(str(r.get("pitcher") or ""))
        if not game_key or not pitcher_key:
            continue
        key = (game_key, pitcher_key)
        er_v = r.get("official_earned_runs")
        outs_v = r.get("official_outs_recorded")
        prev_er, prev_outs = per_game_pitcher.get(key, (None, None))
        next_er = float(er_v) if _is_num(er_v) else prev_er
        next_outs = int(round(float(outs_v))) if _is_num(outs_v) else prev_outs
        if prev_er is not None and next_er is not None:
            next_er = max(prev_er, next_er)
        if prev_outs is not None and next_outs is not None:
            next_outs = max(prev_outs, next_outs)
        per_game_pitcher[key] = (next_er, next_outs)
    for er_v, outs_v in per_game_pitcher.values():
        if _is_num(er_v):
            official_er += float(er_v)
        if _is_num(outs_v):
            official_outs += int(round(float(outs_v)))

    if official_outs > 0:
        lg_ip = official_outs / 3.0
        lg_era = (9.0 * official_er) / lg_ip if lg_ip > 0 else 0.0
    else:
        # Fallback when official lines are unavailable.
        outs_on_play = sum(int(r.get("outs_on_play_num") or 0) for r in pro_rows if r.get("outs_on_play_num") is not None)
        k_with_out = sum(
            1
            for r in pro_rows
            if str(r.get("korbb") or "").strip() == "Strikeout" and int(r.get("outs_on_play_num") or 0) > 0
        )
        lg_outs = outs_on_play + max(0, k_total - k_with_out)
        lg_ip = lg_outs / 3.0 if lg_outs > 0 else 0.0
        h1_total = sum(1 for pr in result_values if pr == "Single")
        h2_total = sum(1 for pr in result_values if pr == "Double")
        h3_total = sum(1 for pr in result_values if pr == "Triple")
        er_est = (
            (0.47 * h1_total)
            + (0.78 * h2_total)
            + (1.09 * h3_total)
            + (1.40 * hr_total)
            + (0.33 * (bb_total + hbp_total))
            - (0.10 * k_total)
        )
        lg_era = (9.0 * er_est / lg_ip) if lg_ip > 0 else 0.0

    if lg_ip <= 0:
        return fallback_fip_const, lg_hr_fb
    lg_fip_component = ((13.0 * hr_total) + (3.0 * (bb_total + hbp_total)) - (2.0 * k_total)) / lg_ip
    fip_const = lg_era - lg_fip_component
    if not isfinite(fip_const):
        fip_const = fallback_fip_const
    return float(fip_const), float(lg_hr_fb)


def _normalize_custom_columns(custom_columns: Optional[List[str]]) -> List[str]:
    if not custom_columns:
        return []
    allowed = set(ALL_TABLE_COLUMNS)
    seen: set[str] = set()
    out: List[str] = []
    for raw in custom_columns:
        col = (raw or "").strip()
        if not col or col not in allowed or col in seen:
            continue
        out.append(col)
        seen.add(col)
    return out


def _build_dynamic_table(
    rows: List[Dict[str, Any]],
    mode: str,
    split_by: str,
    avg_stuff_by_pitch_type: Dict[str, float],
    custom_columns: Optional[List[str]] = None,
) -> tuple[List[str], List[Dict[str, Any]], List[str]]:
    mode_key = (mode or "Stuff").strip()
    split_col_map: Dict[str, str] = {
        "All": "All",
        "Pitch Types": "Pitch",
        "Pitcher Hand": "Pitcher Hand",
        "Batter Hand": "Batter Hand",
        "Count": "Count",
        "After Count": "After Count",
        "Venue": "Venue",
        "Zone Location": "Zone Location",
        "Times Through Order": "Times Through Order",
        "Inning": "Inning of Appearance",
        "Pitch Count": "Pitch Count",
        "Velocity": "Velocity",
        "IVB": "InducedVert",
        "HB": "HorzBreak",
        "Pitcher": "Pitcher",
        "Source": "Source",
        "Team": "Team",
        "Pitcher Team": "Pitcher Team",
        "Batter": "Batter",
        "Catcher": "Catcher",
        "Game": "Game",
    }
    split_col_name = split_col_map.get((split_by or "Pitch Types").strip(), "Pitch")
    groups: Dict[str, List[Dict[str, Any]]] = {}

    def _pa_key_for_split_row(r: Dict[str, Any]) -> str:
        game_key = str(
            r.get("game_pk")
            or r.get("game_id")
            or r.get("game_uid")
            or r.get("game_foreign_id")
            or r.get("session_date")
            or ""
        ).strip()
        ab_idx = str(r.get("at_bat_index") or "").strip()
        play_id = str(r.get("play_id") or "").strip()
        inning = str(r.get("inning") or "").strip()
        outs = str(r.get("outs_num") or "").strip()
        batter_norm = _normalize_name_key(str(r.get("batter") or ""))
        pitcher_norm = _normalize_name_key(str(r.get("pitcher") or ""))
        if game_key and ab_idx:
            return f"{game_key}|ab|{ab_idx}"
        if game_key and inning and batter_norm:
            return f"{game_key}|inn|{inning}|outs|{outs}|bat|{batter_norm}"
        if game_key and inning and pitcher_norm:
            return f"{game_key}|inn|{inning}|outs|{outs}|pit|{pitcher_norm}"
        if game_key and play_id:
            return f"{game_key}|play|{play_id}"
        event_id = str(r.get("pitch_event_id") or r.get("id") or "").strip()
        return event_id or f"row-{id(r)}"

    def _global_outcome_baseline(source_rows: List[Dict[str, Any]]) -> Dict[str, Optional[str]]:
        if not source_rows:
            return {"BF": None, "K%": None, "BB%": None, "HR%": None}

        def _order(rr: Dict[str, Any]) -> tuple:
            return (
                str(rr.get("session_date") or ""),
                int(rr.get("game_pk") or rr.get("game_id") or 0),
                int(rr.get("at_bat_index") or 0),
                int(rr.get("event_index") or 0),
                int(rr.get("pitch_number") or 0),
                int(rr.get("id") or 0),
            )

        def _explicit(rr: Dict[str, Any]) -> str:
            game_key = str(
                rr.get("game_pk")
                or rr.get("game_id")
                or rr.get("game_uid")
                or rr.get("game_foreign_id")
                or ""
            ).strip()
            ab_idx = str(rr.get("at_bat_index") or "").strip()
            inning = str(rr.get("inning") or "").strip()
            outs = str(rr.get("outs_num") or "").strip()
            batter_norm = _normalize_name_key(str(rr.get("batter") or ""))
            pitcher_norm = _normalize_name_key(str(rr.get("pitcher") or ""))
            if game_key and ab_idx:
                return f"{game_key}|ab|{ab_idx}"
            if game_key and inning and batter_norm:
                return f"{game_key}|inn|{inning}|outs|{outs}|bat|{batter_norm}"
            if game_key and inning and pitcher_norm:
                return f"{game_key}|inn|{inning}|outs|{outs}|pit|{pitcher_norm}"
            return ""

        def _infer_terminal(rr: Dict[str, Any]) -> str:
            kor = _korbb_bucket(rr.get("korbb"))
            if kor == "Strikeout":
                return "Strikeout"
            if kor == "Walk":
                return "Walk"
            pr = _canonical_play_result(rr.get("play_result"))
            if pr in {"Strikeout", "Walk", "IntentionalWalk", "HomeRun", "Single", "Double", "Triple", "Out", "FieldersChoice", "Sacrifice", "Error", "HitByPitch"}:
                return pr
            call = str(rr.get("pitch_call") or "").strip()
            b = int(float(rr.get("balls_num"))) if _is_num(rr.get("balls_num")) else None
            s = int(float(rr.get("strikes_num"))) if _is_num(rr.get("strikes_num")) else None
            if call == "HitByPitch":
                return "HitByPitch"
            if call in {"BallCalled", "BallinDirt", "BallIntentional", "Ball"} and b == 3:
                return "Walk"
            if call in {"StrikeSwinging", "StrikeCalled"} and s == 2:
                return "Strikeout"
            if call == "InPlay":
                return "Out"
            return ""

        fallback_pa_counters: Dict[str, int] = {}
        fallback_pa_current: Dict[str, int] = {}
        pa_rows: Dict[str, List[Dict[str, Any]]] = {}

        for rr in sorted(source_rows, key=_order):
            pa_key = _explicit(rr)
            if not pa_key:
                date_key = str(rr.get("session_date") or "")
                inning = str(rr.get("inning") or "").strip()
                batter_norm = _normalize_name_key(str(rr.get("batter") or ""))
                pitcher_norm = _normalize_name_key(str(rr.get("pitcher") or ""))
                cluster = f"{date_key}|{inning}|{pitcher_norm}|{batter_norm}"
                b = int(float(rr.get("balls_num"))) if _is_num(rr.get("balls_num")) else None
                s = int(float(rr.get("strikes_num"))) if _is_num(rr.get("strikes_num")) else None
                if b == 0 and s == 0:
                    next_idx = fallback_pa_counters.get(cluster, 0) + 1
                    fallback_pa_counters[cluster] = next_idx
                    fallback_pa_current[cluster] = next_idx
                cur_idx = fallback_pa_current.get(cluster)
                if cur_idx is None:
                    cur_idx = fallback_pa_counters.get(cluster, 0) + 1
                    fallback_pa_counters[cluster] = cur_idx
                    fallback_pa_current[cluster] = cur_idx
                pa_key = f"syn|{cluster}|{cur_idx}"
            pa_rows.setdefault(pa_key, []).append(rr)

        outcomes: List[str] = []
        for _, pa_group in pa_rows.items():
            outcome = ""
            for rr in sorted(pa_group, key=_order, reverse=True):
                inferred = _infer_terminal(rr)
                if inferred:
                    outcome = inferred
                    break
            if outcome:
                outcomes.append(outcome)

        bf = len(outcomes)
        if bf <= 0:
            return {"BF": None, "K%": None, "BB%": None, "HR%": None}
        k_n = sum(1 for out in outcomes if out == "Strikeout")
        bb_n = sum(1 for out in outcomes if out in {"Walk", "IntentionalWalk"})
        hr_n = sum(1 for out in outcomes if out == "HomeRun")
        return {
            "BF": bf,
            "K%": f"{round(100.0 * k_n / bf, 1)}%",
            "BB%": f"{round(100.0 * bb_n / bf, 1)}%",
            "HR%": f"{round(100.0 * hr_n / bf, 1)}%",
        }

    split_clean_for_grouping = (split_by or "").strip()
    if split_clean_for_grouping == "Game":
        _annotate_derived_game_keys(rows)
    if split_clean_for_grouping == "After Count":
        # After Count semantics: each bucket is all PA/BF that reached that
        # count at any point during the plate appearance, and includes only
        # pitches from that point forward in the PA.
        pa_rows: Dict[str, List[Dict[str, Any]]] = {}
        fallback_pa_counters: Dict[str, int] = {}
        fallback_pa_current: Dict[str, int] = {}

        def _explicit_pa_key(rr: Dict[str, Any]) -> str:
            game_key = str(
                rr.get("game_pk")
                or rr.get("game_id")
                or rr.get("game_uid")
                or rr.get("game_foreign_id")
                or ""
            ).strip()
            ab_idx = str(rr.get("at_bat_index") or "").strip()
            inning = str(rr.get("inning") or "").strip()
            outs = str(rr.get("outs_num") or "").strip()
            batter_norm = _normalize_name_key(str(rr.get("batter") or ""))
            pitcher_norm = _normalize_name_key(str(rr.get("pitcher") or ""))
            if game_key and ab_idx:
                return f"{game_key}|ab|{ab_idx}"
            if game_key and inning and batter_norm:
                return f"{game_key}|inn|{inning}|outs|{outs}|bat|{batter_norm}"
            if game_key and inning and pitcher_norm:
                return f"{game_key}|inn|{inning}|outs|{outs}|pit|{pitcher_norm}"
            return ""

        def _synthetic_pa_key(rr: Dict[str, Any]) -> str:
            # College feeds often lack explicit PA ids. Build a stable PA key
            # from ordered pitch sequence, starting new PA on 0-0 counts.
            date_key = str(rr.get("session_date") or "")
            inning = str(rr.get("inning") or "").strip()
            batter_norm = _normalize_name_key(str(rr.get("batter") or ""))
            pitcher_norm = _normalize_name_key(str(rr.get("pitcher") or ""))
            cluster = f"{date_key}|{inning}|{pitcher_norm}|{batter_norm}"
            b = int(float(rr.get("balls_num"))) if _is_num(rr.get("balls_num")) else None
            s = int(float(rr.get("strikes_num"))) if _is_num(rr.get("strikes_num")) else None
            if b == 0 and s == 0:
                next_idx = fallback_pa_counters.get(cluster, 0) + 1
                fallback_pa_counters[cluster] = next_idx
                fallback_pa_current[cluster] = next_idx
            cur_idx = fallback_pa_current.get(cluster)
            if cur_idx is None:
                cur_idx = fallback_pa_counters.get(cluster, 0) + 1
                fallback_pa_counters[cluster] = cur_idx
                fallback_pa_current[cluster] = cur_idx
            return f"syn|{cluster}|{cur_idx}"
        def _after_row_order_key(rr: Dict[str, Any]) -> tuple:
            return (
                str(rr.get("session_date") or ""),
                int(rr.get("game_pk") or rr.get("game_id") or 0),
                int(rr.get("at_bat_index") or 0),
                int(rr.get("event_index") or 0),
                int(rr.get("pitch_number") or 0),
                int(rr.get("id") or 0),
            )

        def _count_token_from_pair(bv: Any, sv: Any) -> str:
            if not _is_num(bv) or not _is_num(sv):
                return ""
            return f"{int(float(bv))}-{int(float(sv))}"

        for row in rows:
            pa_key = _explicit_pa_key(row) or _synthetic_pa_key(row)
            pa_rows.setdefault(pa_key, []).append(row)

        for _, pa_group_rows in pa_rows.items():
            ordered = sorted(pa_group_rows, key=_after_row_order_key)
            first_idx_by_count: Dict[str, int] = {"0-0": 0}
            for idx, rr in enumerate(ordered):
                tok_curr = _count_token_from_pair(rr.get("balls_num"), rr.get("strikes_num"))
                tok_prev = _count_token_from_pair(rr.get("prev_balls"), rr.get("prev_strikes"))
                if tok_curr and tok_curr not in first_idx_by_count:
                    first_idx_by_count[tok_curr] = idx
                if tok_prev and tok_prev not in first_idx_by_count:
                    first_idx_by_count[tok_prev] = idx
            for count_key, start_idx in first_idx_by_count.items():
                tail_rows = ordered[start_idx:]
                if tail_rows:
                    groups.setdefault(count_key, []).extend(tail_rows)
    else:
        for row in rows:
            key = _split_key_from_row(row, split_by)
            groups.setdefault(key, []).append(row)
    if (split_by or "").strip() == "Inning":
        numeric_inning_keys_present = any(
            str(k).strip().isdigit() for k in groups.keys()
        )
        if numeric_inning_keys_present and "Unknown" in groups:
            groups.pop("Unknown", None)

    out_rows: List[Dict[str, Any]] = []
    total = sum(len(v) for v in groups.values()) or 1
    def _count_pair(r: Dict[str, Any]) -> tuple[Optional[int], Optional[int]]:
        b_raw = r.get("balls_num")
        s_raw = r.get("strikes_num")
        b = int(float(b_raw)) if _is_num(b_raw) else None
        s = int(float(s_raw)) if _is_num(s_raw) else None
        return b, s

    usage_count_00_total = 0
    usage_count_behind_total = 0
    usage_count_even_total = 0
    usage_count_ahead_total = 0
    usage_count_lt2k_total = 0
    usage_count_2k_total = 0
    for r in rows:
        b, s = _count_pair(r)
        if b is None or s is None:
            continue
        if (b, s) == (0, 0):
            usage_count_00_total += 1
        if (b, s) in {(1, 0), (2, 0), (3, 0), (3, 1), (2, 1)}:
            usage_count_behind_total += 1
        if (b, s) in {(0, 0), (1, 1), (2, 2), (3, 2)}:
            usage_count_even_total += 1
        if (b, s) in {(0, 1), (0, 2), (1, 2)}:
            usage_count_ahead_total += 1
        if s < 2:
            usage_count_lt2k_total += 1
        if s == 2:
            usage_count_2k_total += 1
    pro_fip_const, pro_lg_hr_fb = _derive_pro_fip_context(rows)

    def _row_for_group(key: str, grp: List[Dict[str, Any]]) -> Dict[str, Any]:
        n = len(grp)
        strike_calls = {"StrikeCalled", "StrikeSwinging", "FoulBall", "FoulBallFieldable", "FoulBallNotFieldable", "InPlay", "RapsodoStrike"}
        swing_calls = {"StrikeSwinging", "FoulBall", "FoulBallFieldable", "FoulBallNotFieldable", "InPlay"}
        ahead_strike_calls = {"StrikeCalled", "StrikeSwinging", "FoulBall", "FoulBallFieldable", "FoulBallNotFieldable"}
        ea_strike_calls = {"StrikeCalled", "StrikeSwinging", "FoulBall", "FoulBallFieldable", "FoulBallNotFieldable", "InPlay"}
        one_one_strike_calls = {"StrikeCalled", "StrikeSwinging", "FoulBall", "FoulBallFieldable", "FoulBallNotFieldable", "InPlay"}
        def _effective_pitch_call_for_metrics(r: Dict[str, Any]) -> str:
            call = str(r.get("pitch_call") or "").strip()
            call_norm = _pro_norm_token(call)
            if call_norm:
                mapped_from_call = _pro_pitch_call_from_description(call_norm)
                if mapped_from_call:
                    return str(mapped_from_call)
            desc_norm = _pro_norm_token(
                r.get("description_raw")
                or r.get("description")
                or r.get("pro_desc_norm")
                or ""
            )
            mapped = _pro_pitch_call_from_description(desc_norm)
            return str(mapped or "")
        velo_vals = [r.get("rel_speed") for r in grp if _is_num(r.get("rel_speed"))]
        ivb_vals = [r.get("ivb") for r in grp if _is_num(r.get("ivb"))]
        hb_vals = [r.get("hb") for r in grp if _is_num(r.get("hb"))]
        avg_ivb = (sum(float(v) for v in ivb_vals) / len(ivb_vals)) if ivb_vals else None
        avg_hb = (sum(float(v) for v in hb_vals) / len(hb_vals)) if hb_vals else None
        spin_vals = [r.get("spin_rate") for r in grp if _is_num(r.get("spin_rate"))]
        r_tilt_vals = [r.get("release_tilt") for r in grp]
        b_tilt_vals = [r.get("break_tilt") for r in grp]
        b_tilt_clock = _tilt_values_to_clock(b_tilt_vals)
        is_pro_group = any(str(r.get("school_code") or "").strip().upper() == "PRO" for r in grp) or any(
            _is_num(r.get("vy0")) and _is_num(r.get("ay")) for r in grp
        )
        if not b_tilt_clock and is_pro_group:
            b_tilt_clock = _movement_to_break_tilt_clock(avg_ivb, avg_hb)
        live_rows = [r for r in grp if _is_competitive_row(r)]
        ev_vals = [r.get("exit_speed") for r in live_rows if _is_num(r.get("exit_speed"))]
        la_vals = [r.get("angle") for r in live_rows if _is_num(r.get("angle"))]
        height_vals = [r.get("rel_height") for r in grp if _is_num(r.get("rel_height"))]
        side_vals = [r.get("rel_side") for r in grp if _is_num(r.get("rel_side"))]
        ext_vals = [r.get("ext_value") for r in grp if _is_num(r.get("ext_value"))]
        vaa_vals: List[float] = []
        nvaa_vals: List[float] = []
        haa_vals: List[float] = []
        for r in grp:
            row_vaa = float(r.get("vaa")) if _is_num(r.get("vaa")) else None
            row_haa = float(r.get("haa")) if _is_num(r.get("haa")) else None
            if _is_num(r.get("haa")):
                haa_vals.append(float(r.get("haa")))
            if is_pro_group and (row_vaa is None or row_haa is None):
                inferred_vaa, inferred_haa = _infer_pro_vaa_haa_from_kinematics(r)
                if row_vaa is None and _is_num(inferred_vaa):
                    row_vaa = float(inferred_vaa)
                if row_haa is None and _is_num(inferred_haa):
                    row_haa = float(inferred_haa)
                    haa_vals.append(float(inferred_haa))
            if row_vaa is not None:
                vaa_vals.append(row_vaa)
                row_nvaa = _normalized_vaa_value(
                    row_vaa,
                    r.get("plate_height"),
                    r.get("pitch_type"),
                    is_pro=is_pro_group,
                )
                if _is_num(row_nvaa):
                    nvaa_vals.append(float(row_nvaa))
        spin_eff_vals = [r.get("spin_eff") for r in grp if _is_num(r.get("spin_eff"))]
        expected_pairs: List[tuple[float, float, float, float]] = []
        tilt_dev_vals: List[float] = []
        for r in grp:
            expected = _expected_movement_values(r)
            if (
                expected is not None
                and _is_num(r.get("ivb"))
                and _is_num(r.get("hb"))
            ):
                expected_ivb, expected_hb = expected
                expected_pairs.append(
                    (
                        expected_ivb,
                        expected_hb,
                        float(r.get("ivb")) - expected_ivb,
                        float(r.get("hb")) - expected_hb,
                    )
                )
            tilt_dev = _tilt_deviation_minutes(
                r.get("release_tilt"),
                r.get("break_tilt"),
                r.get("ivb"),
                r.get("hb"),
            )
            if _is_num(tilt_dev):
                tilt_dev_vals.append(float(tilt_dev))
        in_zone_n = sum(
            1
            for r in grp
            if _is_num(r.get("plate_side"))
            and _is_num(r.get("plate_height"))
            and (ZONE_LEFT <= float(r["plate_side"]) <= ZONE_RIGHT)
            and (ZONE_BOTTOM <= float(r["plate_height"]) <= ZONE_TOP)
        )
        green_half = 7.0 / 24.0
        green_left = ZONE_MID_X - green_half
        green_right = ZONE_MID_X + green_half
        green_bottom = ZONE_MID_Y - green_half
        green_top = ZONE_MID_Y + green_half

        called_strikes = 0
        takes = 0
        swings_count = 0
        fps_count = 0
        fps_fb_opp = 0
        fps_fb_yes = 0
        fps_os_opp = 0
        fps_os_yes = 0
        chase_den = 0
        chase_num = 0
        gozone_den = 0
        gozone_sw_num = 0
        iz_den = 0
        iz_sw_num = 0
        edge_den = 0
        edge_sw_num = 0
        possd_points = 0
        def _row_is_swing_for_fps_metric(r: Dict[str, Any]) -> bool:
            pitch_call = str(r.get("pitch_call") or "").strip()
            if pitch_call in swing_calls:
                return True
            desc_norm = _pro_norm_token(
                r.get("description_raw")
                or r.get("description")
                or r.get("pro_desc_norm")
                or pitch_call
            )
            if not desc_norm:
                return False
            if desc_norm in {
                "swinging_strike",
                "swinging_strike_blocked",
                "swinging_strike_pitchout",
                "strikeswinging",
                "missed_bunt",
                "foul",
                "foul_tip",
                "foultip",
                "foul_bunt",
                "foul_pitchout",
                "foulball",
                "foulballfieldable",
                "foulballnotfieldable",
            }:
                return True
            return (
                desc_norm.startswith("foul")
                or desc_norm.startswith("in_play")
                or desc_norm.startswith("hit_into_play")
                or desc_norm == "inplay"
            )
        for r in grp:
            pitch_call = _effective_pitch_call_for_metrics(r)
            is_swing = pitch_call in swing_calls
            if is_swing:
                swings_count += 1
            if pitch_call == "StrikeCalled":
                called_strikes += 1
            if pitch_call in {"BallCalled", "StrikeCalled", "Ball"}:
                takes += 1
            if (
                (r.get("balls_num") == 0 and r.get("strikes_num") == 0)
                and pitch_call in {"StrikeCalled", "StrikeSwinging", "FoulBall", "FoulBallFieldable", "FoulBallNotFieldable", "InPlay"}
            ):
                fps_count += 1
            if r.get("balls_num") == 0 and r.get("strikes_num") == 0:
                is_fb_or_si = _is_fastball_or_sinker_pitch_type(r.get("pitch_type"))
                if is_fb_or_si:
                    fps_fb_opp += 1
                    if _row_is_swing_for_fps_metric(r):
                        fps_fb_yes += 1
                else:
                    fps_os_opp += 1
                    if _row_is_swing_for_fps_metric(r):
                        fps_os_yes += 1
            if not (_is_num(r.get("plate_side")) and _is_num(r.get("plate_height"))):
                continue
            ps = float(r.get("plate_side"))
            ph = float(r.get("plate_height"))
            is_in_zone = (ZONE_LEFT <= ps <= ZONE_RIGHT) and (ZONE_BOTTOM <= ph <= ZONE_TOP)
            is_green = (green_left <= ps <= green_right) and (green_bottom <= ph <= green_top)
            is_outside = not is_in_zone
            is_edge = is_in_zone and (not is_green)
            if is_outside:
                chase_den += 1
                if is_swing:
                    chase_num += 1
            if is_green:
                gozone_den += 1
                if is_swing:
                    gozone_sw_num += 1
            if is_in_zone:
                iz_den += 1
                if is_swing:
                    iz_sw_num += 1
            if is_edge:
                edge_den += 1
                if is_swing:
                    edge_sw_num += 1
            if (is_swing and is_green) or ((not is_swing) and is_outside):
                possd_points += 1
        qp_n = sum(
            1
            for r in grp
            if _is_num(r.get("plate_side"))
            and _is_num(r.get("plate_height"))
            and (-1.5 <= float(r["plate_side"]) <= 1.5)
            and (COMP_PCT_BOTTOM <= float(r["plate_height"]) <= COMP_PCT_TOP)
        )
        loc_n = sum(1 for r in grp if _is_num(r.get("plate_side")) and _is_num(r.get("plate_height")))
        strike_n = sum(1 for r in grp if _effective_pitch_call_for_metrics(r) in strike_calls)
        called_strike_n = sum(1 for r in grp if _effective_pitch_call_for_metrics(r) == "StrikeCalled")
        swing_n = sum(1 for r in grp if _effective_pitch_call_for_metrics(r) in swing_calls)
        whiff_n = sum(
            1
            for r in grp
            if (
                _effective_pitch_call_for_metrics(r) == "StrikeSwinging"
                or _pro_pitch_call_from_description(_pro_norm_token(r.get("description"))) == "StrikeSwinging"
            )
        )
        bb_n = sum(
            1
            for r in grp
            if _korbb_bucket(r.get("korbb")) == "Walk"
            or _canonical_play_result(r.get("play_result")) in {"Walk", "IntentionalWalk"}
        )
        k_n = sum(
            1
            for r in grp
            if _korbb_bucket(r.get("korbb")) == "Strikeout"
            or _canonical_play_result(r.get("play_result")) == "Strikeout"
        )
        hbp_n = sum(
            1
            for r in grp
            if _effective_pitch_call_for_metrics(r) == "HitByPitch"
            or _canonical_play_result(r.get("play_result")) == "HitByPitch"
        )
        gb_n = sum(
            1
            for r in grp
            if (
                _effective_pitch_call_for_metrics(r) == "InPlay"
                or _pro_norm_token(r.get("description")) in {"in_play", "inplay"}
                or _pro_norm_token(r.get("description")).startswith("hit_into_play")
            )
            and _is_ground_ball_tag(r.get("tagged_hit_type"))
        )
        fb_n = sum(
            1
            for r in grp
            if (
                _effective_pitch_call_for_metrics(r) == "InPlay"
                or _pro_norm_token(r.get("description")) in {"in_play", "inplay"}
                or _pro_norm_token(r.get("description")).startswith("hit_into_play")
            )
            and _is_fly_ball_for_siera_tag(r.get("tagged_hit_type"))
        )
        pu_n = sum(
            1
            for r in grp
            if (
                _effective_pitch_call_for_metrics(r) == "InPlay"
                or _pro_norm_token(r.get("description")) in {"in_play", "inplay"}
                or _pro_norm_token(r.get("description")).startswith("hit_into_play")
            )
            and _is_popup_tag(r.get("tagged_hit_type"))
        )
        in_play_n = sum(
            1
            for r in grp
            if _effective_pitch_call_for_metrics(r) == "InPlay"
            or _pro_norm_token(r.get("description")) in {"in_play", "inplay"}
            or _pro_norm_token(r.get("description")).startswith("hit_into_play")
        )
        in_play_live_n = sum(
            1
            for r in live_rows
            if _effective_pitch_call_for_metrics(r) == "InPlay"
            or _pro_norm_token(r.get("description")) in {"in_play", "inplay"}
            or _pro_norm_token(r.get("description")).startswith("hit_into_play")
        )
        csw_n = called_strike_n + whiff_n
        hit_n = sum(1 for r in grp if _canonical_play_result(r.get("play_result")) in {"Single", "Double", "Triple", "HomeRun"})
        xbh_n = sum(1 for r in grp if _canonical_play_result(r.get("play_result")) in {"Double", "Triple", "HomeRun"})
        barrel_n_all = 0
        for r in grp:
            ev = r.get("exit_speed")
            la = r.get("angle")
            if _is_num(ev) and _is_num(la):
                evf = float(ev)
                laf = float(la)
                if evf >= 95.0 and 10.0 <= laf <= 30.0:
                    barrel_n_all += 1
        barrel_n_live = 0
        for r in live_rows:
            ev = r.get("exit_speed")
            la = r.get("angle")
            if _is_num(ev) and _is_num(la):
                evf = float(ev)
                laf = float(la)
                if evf >= 95.0 and 10.0 <= laf <= 35.0:
                    barrel_n_live += 1

        fps_opp = sum(1 for r in grp if r.get("balls_num") == 0 and r.get("strikes_num") == 0)
        fps_yes = sum(
            1
            for r in grp
            if r.get("balls_num") == 0
            and r.get("strikes_num") == 0
            and _effective_pitch_call_for_metrics(r) in {"StrikeCalled", "StrikeSwinging", "FoulBall", "FoulBallFieldable", "InPlay"}
        )
        count_00 = sum(1 for r in grp if r.get("balls_num") == 0 and r.get("strikes_num") == 0)
        count_behind = sum(1 for r in grp if (r.get("balls_num"), r.get("strikes_num")) in {(1, 0), (2, 0), (3, 0), (3, 1), (2, 1)})
        count_even = sum(1 for r in grp if (r.get("balls_num"), r.get("strikes_num")) in {(0, 0), (1, 1), (2, 2), (3, 2)})
        count_ahead = sum(1 for r in grp if (r.get("balls_num"), r.get("strikes_num")) in {(0, 1), (0, 2), (1, 2)})
        count_lt2k = sum(1 for r in grp if (r.get("strikes_num") is not None and int(r.get("strikes_num")) < 2))
        count_2k = sum(1 for r in grp if r.get("strikes_num") == 2)
        lt2k_strike_n = sum(
            1
            for r in grp
            if _is_num(r.get("strikes_num"))
            and int(float(r.get("strikes_num"))) < 2
            and _effective_pitch_call_for_metrics(r) in strike_calls
        )
        k2_strike_n = sum(
            1
            for r in grp
            if _is_num(r.get("strikes_num"))
            and int(float(r.get("strikes_num"))) == 2
            and _effective_pitch_call_for_metrics(r) in strike_calls
        )
        lt2k_loc_n = sum(
            1
            for r in grp
            if _is_num(r.get("strikes_num"))
            and int(float(r.get("strikes_num"))) < 2
            and _is_num(r.get("plate_side"))
            and _is_num(r.get("plate_height"))
        )
        k2_loc_n = sum(
            1
            for r in grp
            if _is_num(r.get("strikes_num"))
            and int(float(r.get("strikes_num"))) == 2
            and _is_num(r.get("plate_side"))
            and _is_num(r.get("plate_height"))
        )
        lt2k_in_zone_n = sum(
            1
            for r in grp
            if _is_num(r.get("strikes_num"))
            and int(float(r.get("strikes_num"))) < 2
            and _in_zone_label(r.get("plate_side"), r.get("plate_height")) == "Yes"
        )
        k2_in_zone_n = sum(
            1
            for r in grp
            if _is_num(r.get("strikes_num"))
            and int(float(r.get("strikes_num"))) == 2
            and _in_zone_label(r.get("plate_side"), r.get("plate_height")) == "Yes"
        )
        pitch_usage_fastball = 0
        pitch_usage_sinker = 0
        pitch_usage_cutter = 0
        pitch_usage_slider = 0
        pitch_usage_sweeper = 0
        pitch_usage_curveball = 0
        pitch_usage_changeup = 0
        pitch_usage_splitter = 0
        pitch_usage_2k = 0
        pitch_usage_2k_fb = 0
        for r in grp:
            family = _pitch_type_family(r.get("pitch_type"))
            if family == "Fastball":
                pitch_usage_fastball += 1
            elif family == "Sinker":
                pitch_usage_sinker += 1
            elif family == "Cutter":
                pitch_usage_cutter += 1
            elif family == "Slider":
                pitch_usage_slider += 1
            elif family == "Sweeper":
                pitch_usage_sweeper += 1
            elif family == "Curveball":
                pitch_usage_curveball += 1
            elif family == "ChangeUp":
                pitch_usage_changeup += 1
            elif family == "Splitter":
                pitch_usage_splitter += 1
            if r.get("strikes_num") == 2:
                pitch_usage_2k += 1
                if family in {"Fastball", "Sinker"}:
                    pitch_usage_2k_fb += 1
        one_one_total = sum(1 for r in grp if r.get("balls_num") == 1 and r.get("strikes_num") == 1)
        one_one_success = sum(
            1
            for r in grp
            if r.get("balls_num") == 1
            and r.get("strikes_num") == 1
            and _effective_pitch_call_for_metrics(r) in one_one_strike_calls
        )
        outs_on_play_n = sum(int(r.get("outs_on_play_num") or 0) for r in grp if r.get("outs_on_play_num") is not None)
        # Avoid double counting K-outs when outs_on_play already includes them.
        k_with_out_recorded_n = sum(
            1
            for r in grp
            if _korbb_bucket(r.get("korbb")) == "Strikeout" and int(r.get("outs_on_play_num") or 0) > 0
        )
        outs_n = outs_on_play_n + max(0, k_n - k_with_out_recorded_n)

        pa_keys: set[str] = set()
        pa_keys_all: set[str] = set()
        pa_terminal_rows_by_key: Dict[str, Dict[str, Any]] = {}
        def _row_order_key_for_pa(rr: Dict[str, Any]) -> tuple:
            return (
                str(rr.get("session_date") or ""),
                int(rr.get("game_pk") or rr.get("game_id") or 0),
                int(rr.get("at_bat_index") or 0),
                int(rr.get("event_index") or 0),
                int(rr.get("pitch_number") or 0),
                int(rr.get("id") or 0),
            )
        def _is_terminal_pa_row(rr: Dict[str, Any]) -> bool:
            pr = _canonical_play_result(rr.get("play_result"))
            if pr and pr != "Undefined":
                return True
            if _korbb_bucket(rr.get("korbb")) in {"Strikeout", "Walk"}:
                return True
            if _effective_pitch_call_for_metrics(rr) == "HitByPitch":
                return True
            return False
        for r in grp:
            pa_key_all = _pa_key_for_split_row(r)
            if pa_key_all:
                pa_keys_all.add(pa_key_all)
                existing_terminal = pa_terminal_rows_by_key.get(pa_key_all)
                if _is_terminal_pa_row(r) and (
                    existing_terminal is None
                    or _row_order_key_for_pa(r) >= _row_order_key_for_pa(existing_terminal)
                ):
                    pa_terminal_rows_by_key[pa_key_all] = r
            # Non-PRO BF is based on PA starts (0-0 counts), not all pitch rows.
            if not (r.get("balls_num") == 0 and r.get("strikes_num") == 0):
                continue
            game_key = str(
                r.get("game_pk")
                or r.get("game_id")
                or r.get("game_uid")
                or r.get("game_foreign_id")
                or r.get("session_date")
                or ""
            ).strip()
            ab_idx = str(r.get("at_bat_index") or "").strip()
            play_id = str(r.get("play_id") or "").strip()
            inning = str(r.get("inning") or "").strip()
            outs = str(r.get("outs_num") or "").strip()
            batter_norm = _normalize_name_key(str(r.get("batter") or ""))
            pa_key = ""
            if game_key and ab_idx:
                pa_key = f"{game_key}|ab|{ab_idx}"
            elif game_key and inning and batter_norm:
                pa_key = f"{game_key}|inn|{inning}|outs|{outs}|bat|{batter_norm}"
            elif game_key and play_id:
                pa_key = f"{game_key}|play|{play_id}"
            if pa_key:
                pa_keys.add(pa_key)
        if split_clean_for_grouping == "After Count":
            # After Count outcome rates must be PA-based (one terminal outcome per PA).
            pa_rows_for_outcome: Dict[str, List[Dict[str, Any]]] = {}
            def _infer_terminal_outcome(rr: Dict[str, Any]) -> str:
                kor = _korbb_bucket(rr.get("korbb"))
                if kor == "Strikeout":
                    return "Strikeout"
                if kor == "Walk":
                    return "Walk"
                pr = _canonical_play_result(rr.get("play_result"))
                if pr in {"Strikeout", "Walk", "IntentionalWalk", "HomeRun", "Single", "Double", "Triple", "Out", "FieldersChoice", "Sacrifice", "Error", "HitByPitch"}:
                    return pr
                call = _effective_pitch_call_for_metrics(rr)
                b = int(float(rr.get("balls_num"))) if _is_num(rr.get("balls_num")) else None
                s = int(float(rr.get("strikes_num"))) if _is_num(rr.get("strikes_num")) else None
                if call == "HitByPitch":
                    return "HitByPitch"
                if call in {"BallCalled", "BallinDirt", "BallIntentional", "Ball"} and b == 3:
                    return "Walk"
                if call in {"StrikeSwinging", "StrikeCalled"} and s == 2:
                    return "Strikeout"
                if call == "InPlay":
                    return "Out"
                return ""
            for rr in grp:
                pa_k = _pa_key_for_split_row(rr)
                if not pa_k or pa_k.startswith("row-"):
                    continue
                pa_rows_for_outcome.setdefault(pa_k, []).append(rr)

            terminal_outcomes: List[str] = []
            for _, pa_group in pa_rows_for_outcome.items():
                ordered = sorted(pa_group, key=_row_order_key_for_pa)
                outcome = ""
                for rr in reversed(ordered):
                    inferred = _infer_terminal_outcome(rr)
                    if inferred:
                        outcome = inferred
                        break
                if outcome:
                    terminal_outcomes.append(outcome)

            if terminal_outcomes:
                bf_starts = len(terminal_outcomes)
                k_n = sum(1 for out in terminal_outcomes if out == "Strikeout")
                bb_n = sum(1 for out in terminal_outcomes if out in {"Walk", "IntentionalWalk"})
                hr = sum(1 for out in terminal_outcomes if out == "HomeRun")
            else:
                terminal_rows_for_split = list(pa_terminal_rows_by_key.values())
                bf_starts = len(terminal_rows_for_split) if terminal_rows_for_split else (len(pa_keys_all) if pa_keys_all else len(pa_keys))
                if bf_starts == 0:
                    bf_starts = sum(1 for r in grp if _is_num(r.get("balls_num")) and _is_num(r.get("strikes_num")))
                k_n = sum(
                    1
                    for rr in terminal_rows_for_split
                    if _korbb_bucket(rr.get("korbb")) == "Strikeout"
                    or _canonical_play_result(rr.get("play_result")) == "Strikeout"
                )
                bb_n = sum(
                    1
                    for rr in terminal_rows_for_split
                    if _korbb_bucket(rr.get("korbb")) == "Walk"
                    or _canonical_play_result(rr.get("play_result")) in {"Walk", "IntentionalWalk"}
                )
                hr = sum(1 for rr in terminal_rows_for_split if _canonical_play_result(rr.get("play_result")) == "HomeRun")
        elif split_clean_for_grouping == "Count":
            terminal_rows_for_split = list(pa_terminal_rows_by_key.values())
            bf_starts = len(terminal_rows_for_split) if terminal_rows_for_split else (len(pa_keys_all) if pa_keys_all else len(pa_keys))
            if bf_starts == 0:
                bf_starts = sum(1 for r in grp if _is_num(r.get("balls_num")) and _is_num(r.get("strikes_num")))
            k_n = sum(
                1
                for rr in terminal_rows_for_split
                if _korbb_bucket(rr.get("korbb")) == "Strikeout"
                or _canonical_play_result(rr.get("play_result")) == "Strikeout"
            )
            bb_n = sum(
                1
                for rr in terminal_rows_for_split
                if _korbb_bucket(rr.get("korbb")) == "Walk"
                or _canonical_play_result(rr.get("play_result")) in {"Walk", "IntentionalWalk"}
            )
            hr = sum(1 for rr in terminal_rows_for_split if _canonical_play_result(rr.get("play_result")) == "HomeRun")
        else:
            bf_starts = len(pa_keys) if pa_keys else sum(
                1 for r in grp if r.get("balls_num") == 0 and r.get("strikes_num") == 0
            )
        qp_points = [q for q in (_compute_qp_point(r) for r in grp) if q is not None]
        qp_count = sum(1 for q in qp_points if (q * 200.0) >= 100.0)
        qp_mean = (sum(qp_points) / len(qp_points)) if qp_points else None
        ctrl_scores: List[float] = []
        for r in grp:
            ps = r.get("plate_side")
            ph = r.get("plate_height")
            if not (_is_num(ps) and _is_num(ph)):
                continue
            psv = float(ps)
            phv = float(ph)
            if (ZONE_LEFT <= psv <= ZONE_RIGHT) and (ZONE_BOTTOM <= phv <= ZONE_TOP):
                ctrl_scores.append(1.47)
            elif (-1.5 <= psv <= 1.5) and (COMP_PCT_BOTTOM <= phv <= COMP_PCT_TOP):
                ctrl_scores.append(0.73)
            else:
                ctrl_scores.append(0.0)
        ctrl_plus = round((sum(ctrl_scores) / len(ctrl_scores)) * 100.0, 1) if ctrl_scores else None

        stuff_vals: List[float] = []
        for r in grp:
            if _is_num(r.get("stuff_plus")):
                stuff_vals.append(float(r.get("stuff_plus")))
                continue
            pt = str(r.get("pitch_type") or "")
            mapped = avg_stuff_by_pitch_type.get(pt)
            if _is_num(mapped):
                stuff_vals.append(float(mapped))
        fps_opp = sum(1 for r in grp if _is_competitive_row(r) and r.get("balls_num") == 0 and r.get("strikes_num") == 0)
        fps_yes = sum(
            1
            for r in grp
            if _is_competitive_row(r)
            and r.get("balls_num") == 0
            and r.get("strikes_num") == 0
            and _effective_pitch_call_for_metrics(r) in strike_calls
        )
        early_n = sum(
            1
            for r in grp
            if _is_competitive_row(r)
            and (
                (r.get("balls_num"), r.get("strikes_num")) in {(0, 0), (0, 1), (1, 0), (1, 1)}
            )
            and _effective_pitch_call_for_metrics(r) == "InPlay"
        )
        ahead_state_n = sum(
            1
            for r in grp
            if _is_competitive_row(r)
            and (r.get("balls_num"), r.get("strikes_num")) in {(0, 1), (1, 1)}
            and _effective_pitch_call_for_metrics(r) in ahead_strike_calls
        )
        ea_yes = sum(
            1
            for r in grp
            if r.get("balls_num") == 0
            and r.get("strikes_num") == 0
            and _is_competitive_row(r)
            and _effective_pitch_call_for_metrics(r) == "InPlay"
        ) + sum(
            1
            for r in grp
            if (
                _is_competitive_row(r)
                and (
                    (
                        (r.get("balls_num"), r.get("strikes_num")) in {(0, 1), (1, 1)}
                        and _effective_pitch_call_for_metrics(r) in ea_strike_calls
                    )
                    or (
                        r.get("balls_num") == 1 and r.get("strikes_num") == 0 and _effective_pitch_call_for_metrics(r) == "InPlay"
                    )
                )
            )
        )
        rv_rows = live_rows if live_rows else grp
        rv_vals = [
            _calc_run_value(
                r.get("pitch_call"),
                r.get("play_result"),
                r.get("korbb"),
                r.get("balls_num"),
                r.get("strikes_num"),
                r.get("outs_num"),
                r.get("outs_on_play_num"),
            )
            for r in rv_rows
        ]
        rv100 = (((sum(rv_vals) / len(rv_vals)) * 100.0) - 0.43) if rv_vals else None
        pv_vals = [
            _calc_pitch_value(
                r.get("pitch_call"),
                r.get("play_result"),
                r.get("korbb"),
                r.get("balls_num"),
                r.get("strikes_num"),
                r.get("outs_num"),
                r.get("outs_on_play_num"),
                r.get("school_code"),
            )
            for r in grp
        ]
        pv100 = ((sum(pv_vals) / len(pv_vals)) * 100.0) if pv_vals else None

        terminal_rows = [
            r
            for r in grp
            if (str(r.get("play_result") or "") not in {"", "Undefined"})
            or (_korbb_bucket(r.get("korbb")) in {"Strikeout", "Walk"})
        ]
        is_pro_group = any(str(r.get("school_code") or "").strip().upper() == "PRO" for r in grp)
        terminal_pr = [
            (_canonical_play_result(r.get("play_result")) if is_pro_group else str(r.get("play_result") or ""))
            for r in terminal_rows
        ]
        live_pr = [
            (_canonical_play_result(r.get("play_result")) if is_pro_group else str(r.get("play_result") or ""))
            for r in live_rows
        ]
        pa_ct = len(terminal_rows)
        h1 = sum(1 for pr in terminal_pr if pr == "Single")
        h2 = sum(1 for pr in terminal_pr if pr == "Double")
        h3 = sum(1 for pr in terminal_pr if pr == "Triple")
        hr = sum(1 for pr in terminal_pr if pr == "HomeRun")
        bb_term = sum(
            1
            for idx, pr in enumerate(terminal_pr)
            if _korbb_bucket(terminal_rows[idx].get("korbb")) == "Walk" or pr == "Walk"
        )
        ibb = sum(1 for pr in terminal_pr if pr == "IntentionalWalk")
        hbp_term = sum(1 for pr in terminal_pr if pr == "HitByPitch")
        sf = sum(1 for pr in terminal_pr if pr == "Sacrifice")
        ab = pa_ct - (bb_term + hbp_term + sf)
        h = h1 + h2 + h3 + hr
        tb = h1 + 2 * h2 + 3 * h3 + 4 * hr
        avg = round(h / ab, 3) if ab > 0 else None
        slg = round(tb / ab, 3) if ab > 0 else None
        obp = round((h + bb_term + hbp_term) / pa_ct, 3) if pa_ct > 0 else None
        ops = round((slg or 0) + (obp or 0), 3) if (slg is not None and obp is not None) else None
        ubb = bb_term - ibb
        woba_num = 0.690 * ubb + 0.722 * hbp_term + 0.888 * h1 + 1.271 * h2 + 1.616 * h3 + 2.101 * hr
        woba_den = ab + bb_term - ibb + sf + hbp_term
        woba = round(woba_num / woba_den, 3) if woba_den > 0 else None
        iso = round((slg - avg), 3) if (slg is not None and avg is not None) else None
        # User-defined BABIP: (1B + 2B + 3B + HR) / total balls in play.
        # Denominator uses in-play rows (school: pitch_call=InPlay, pro: description=hit_into_play).
        babip = round(h / in_play_n, 3) if in_play_n > 0 else None
        bf_live = sum(1 for r in live_rows if r.get("balls_num") == 0 and r.get("strikes_num") == 0)
        xwoba_num = (
            0.69 * sum(1 for r in live_rows if str(r.get("korbb") or "") == "Walk")
            + 0.90 * sum(1 for pr in live_pr if pr == "Single")
            + 1.24 * sum(1 for pr in live_pr if pr == "Double")
            + 1.56 * sum(1 for pr in live_pr if pr == "Triple")
            + 1.95 * sum(1 for pr in live_pr if pr == "HomeRun")
        )
        xwoba = round(xwoba_num / bf_live, 3) if bf_live > 0 else None
        # xISO model (all schools): -0.358973*GB - 0.108255*EV + 0.00066305*EV^2 + 4.66285
        # GB is ground-ball rate as fraction (0-1), EV is average exit velocity.
        xiso = None
        if in_play_n > 0 and ev_vals:
            gb_rate = float(gb_n) / float(in_play_n)
            ev_avg = sum(float(v) for v in ev_vals) / len(ev_vals)
            xiso_calc = (-0.358973 * gb_rate) - (0.108255 * ev_avg) + (0.00066305 * (ev_avg ** 2)) + 4.66285
            xiso = round(xiso_calc, 3)

        # PRO override: wOBA/xWOBA are straight averages from enriched Savant fields when present.
        if is_pro_group:
            woba_vals = [float(r.get("woba_value")) for r in grp if _is_num(r.get("woba_value"))]
            xwoba_vals = [
                float(r.get("estimated_woba_using_speedangle"))
                for r in grp
                if _is_num(r.get("estimated_woba_using_speedangle"))
            ]
            woba = round(sum(woba_vals) / len(woba_vals), 3) if woba_vals else None
            xwoba = round(sum(xwoba_vals) / len(xwoba_vals), 3) if xwoba_vals else None

        # Advanced pitching metrics (ERA/FIP/xFIP) for custom-table use.
        # Note: ERA here is an event-weight estimate because earned-runs is not tracked directly.
        fip_const = pro_fip_const if is_pro_group else 3.2
        lg_hr_fb = pro_lg_hr_fb if is_pro_group else 0.12
        fip_val: Optional[float] = None
        x_fip_val: Optional[float] = None
        era_val: Optional[float] = None
        siera_val: Optional[float] = None
        official_er = 0.0
        official_outs = 0
        # PRO-only: use official pitcher game line totals when available.
        # (earned runs + outs recorded from StatsAPI boxscore)
        # is_pro_group (any-row check, not grp[0]) so a merged group containing
        # both school and linked-PRO rows still picks up official stats from
        # its PRO rows instead of silently skipping them because the first
        # row in the group happened to be a school row.
        if is_pro_group:
            # Collect per-game official totals robustly (some rows may have null
            # official_* while other rows for the same game/pitcher have values).
            per_game_official: dict[tuple[str, str], tuple[Optional[float], Optional[int]]] = {}
            for r in grp:
                game_key = str(r.get("game_pk") or r.get("game_id") or "").strip()
                pitcher_key = _normalize_name_key(str(r.get("pitcher") or ""))
                if not game_key or not pitcher_key:
                    continue
                official_key = (game_key, pitcher_key)
                er_v = r.get("official_earned_runs")
                outs_v = r.get("official_outs_recorded")
                prev_er, prev_outs = per_game_official.get(official_key, (None, None))
                next_er = float(er_v) if _is_num(er_v) else prev_er
                next_outs = int(round(float(outs_v))) if _is_num(outs_v) else prev_outs
                # Prefer maximum non-null values if rows disagree.
                if prev_er is not None and next_er is not None:
                    next_er = max(prev_er, next_er)
                if prev_outs is not None and next_outs is not None:
                    next_outs = max(prev_outs, next_outs)
                per_game_official[official_key] = (next_er, next_outs)
            for er_v, outs_v in per_game_official.values():
                if _is_num(er_v):
                    official_er += float(er_v)
                if _is_num(outs_v):
                    official_outs += int(round(float(outs_v)))
            if official_outs > 0:
                official_ip = official_outs / 3.0
                era_val = max(0.0, (9.0 * official_er) / official_ip)
        outs_for_ip = official_outs if (is_pro_group and official_outs > 0) else outs_n
        ip_whole = outs_for_ip // 3
        ip_rem = outs_for_ip % 3
        ip_display = f"{ip_whole}.{ip_rem}" if ip_rem else str(ip_whole)
        ip_num = (outs_for_ip / 3.0) if outs_for_ip else 0.0
        if ip_num > 0:
            fip_val = ((13.0 * hr) + (3.0 * (bb_n + hbp_n)) - (2.0 * k_n)) / ip_num + fip_const
            fb_source = live_rows if live_rows else grp
            fb_n = sum(1 for r in fb_source if _is_xfip_fly_ball_tag(r.get("tagged_hit_type")))
            x_hr = fb_n * lg_hr_fb
            x_fip_val = ((13.0 * x_hr) + (3.0 * (bb_n + hbp_n)) - (2.0 * k_n)) / ip_num + fip_const
            if not _is_num(era_val):
                # Non-PRO fallback: event-weight run estimate, converted to ERA scale.
                er_est = (
                    (0.47 * h1)
                    + (0.78 * h2)
                    + (1.09 * h3)
                    + (1.40 * hr)
                    + (0.33 * (bb_n + hbp_n))
                    - (0.10 * k_n)
                )
                era_val = max(0.0, (9.0 * er_est) / ip_num)
        siera_val = _compute_siera_value(
            strikeouts=k_n,
            plate_appearances=bf_starts,
            walks=bb_n,
            ground_balls=gb_n,
            fly_balls=fb_n,
            pop_ups=pu_n,
        )

        row_out: Dict[str, Any] = {
            split_col_name: key,
            "#": n,
            "P": n,
            "Usage": f"{round(100.0 * n / total, 1)}%",
            "Overall": f"{round(100.0 * n / total, 1)}%",
            "BF": bf_starts,
            "Velo": round(sum(float(v) for v in velo_vals) / len(velo_vals), 1) if velo_vals else None,
            "FBvelo": (
                round(
                    sum(float(r.get("rel_speed")) for r in grp if _is_num(r.get("rel_speed")) and _is_fastball_or_sinker_pitch_type(r.get("pitch_type")))
                    / sum(1 for r in grp if _is_num(r.get("rel_speed")) and _is_fastball_or_sinker_pitch_type(r.get("pitch_type"))),
                    1,
                )
                if any(_is_num(r.get("rel_speed")) and _is_fastball_or_sinker_pitch_type(r.get("pitch_type")) for r in grp)
                else None
            ),
            "Max": round(max(float(v) for v in velo_vals), 1) if velo_vals else None,
            "IVB": round(avg_ivb, 1) if _is_num(avg_ivb) else None,
            "HB": round(avg_hb, 1) if _is_num(avg_hb) else None,
            "xIVB": round(sum(v[0] for v in expected_pairs) / len(expected_pairs), 1) if expected_pairs else None,
            "xHB": round(sum(v[1] for v in expected_pairs) / len(expected_pairs), 1) if expected_pairs else None,
            "dIVB": (
                round(avg_ivb - (sum(v[0] for v in expected_pairs) / len(expected_pairs)), 1)
                if expected_pairs and _is_num(avg_ivb)
                else None
            ),
            "dHB": (
                round(avg_hb - (sum(v[1] for v in expected_pairs) / len(expected_pairs)), 1)
                if expected_pairs and _is_num(avg_hb)
                else None
            ),
            "MagAngle": (
                round(
                    _magnus_angle(
                        sum(v[0] for v in expected_pairs) / len(expected_pairs),
                        sum(v[1] for v in expected_pairs) / len(expected_pairs),
                    ),
                    1,
                )
                if expected_pairs
                else None
            ),
            "Spin": round(sum(float(v) for v in spin_vals) / len(spin_vals), 0) if spin_vals else None,
            "rTilt": _tilt_values_to_clock(r_tilt_vals),
            "bTilt": b_tilt_clock,
            "TiltDev": _format_tilt_deviation(
                _tilt_deviation_from_averages(_tilt_values_to_clock(r_tilt_vals), b_tilt_clock)
            ),
            "SpinEff": f"{round(100.0 * (sum(float(v) for v in spin_eff_vals) / len(spin_eff_vals)), 1)}%" if spin_eff_vals else None,
            "Height": round(sum(float(v) for v in height_vals) / len(height_vals), 1) if height_vals else None,
            "Side": round(sum(float(v) for v in side_vals) / len(side_vals), 1) if side_vals else None,
            "Ext": round(sum(float(v) for v in ext_vals) / len(ext_vals), 1) if ext_vals else None,
            "VAA": round(sum(float(v) for v in vaa_vals) / len(vaa_vals), 4) if vaa_vals else None,
            "nVAA": round(sum(float(v) for v in nvaa_vals) / len(nvaa_vals), 4) if nvaa_vals else None,
            "HAA": round(sum(float(v) for v in haa_vals) / len(haa_vals), 4) if haa_vals else None,
            "Strike%": f"{round(100.0 * strike_n / n, 1)}%" if n else None,
            "Swing%": f"{round(100.0 * swing_n / n, 1)}%" if n else None,
            "FPS%": f"{round(100.0 * fps_yes / fps_opp, 1)}%" if fps_opp else None,
            "FPS(FB)%": f"{round(100.0 * fps_fb_yes / fps_fb_opp, 1)}%" if fps_fb_opp else None,
            "FPS(OS)%": f"{round(100.0 * fps_os_yes / fps_os_opp, 1)}%" if fps_os_opp else None,
            "Called-S%": f"{round(100.0 * called_strikes / n, 1)}%" if n else None,
            "Take%": f"{round(100.0 * takes / n, 1)}%" if n else None,
            "Chase%": f"{round(100.0 * chase_num / chase_den, 1)}%" if chase_den else None,
            "GoZoneSw%": f"{round(100.0 * gozone_sw_num / gozone_den, 1)}%" if gozone_den else None,
            "IZswing%": f"{round(100.0 * iz_sw_num / iz_den, 1)}%" if iz_den else None,
            "EdgeSwing%": f"{round(100.0 * edge_sw_num / edge_den, 1)}%" if edge_den else None,
            "PosSD%": f"{round(100.0 * possd_points / n, 1)}%" if n else None,
            "Early%": f"{round(100.0 * early_n / fps_opp, 1)}%" if fps_opp else None,
            "Ahead%": f"{round(100.0 * ahead_state_n / fps_opp, 1)}%" if fps_opp else None,
            "E+A%": f"{round(100.0 * ea_yes / fps_opp, 1)}%" if fps_opp else None,
            "1-1W%": f"{round(100.0 * one_one_success / one_one_total, 1)}%" if one_one_total else None,
            "InZone%": f"{round(100.0 * in_zone_n / loc_n, 1)}%" if loc_n else None,
            "Comp%": f"{round(100.0 * qp_n / loc_n, 1)}%" if loc_n else None,
            "QP%": f"{round(100.0 * qp_count / n, 1)}%" if n else None,
            "Whiff%": f"{round(100.0 * whiff_n / swing_n, 1)}%" if swing_n else None,
            "SwStrk%": f"{round(100.0 * whiff_n / n, 1)}%" if n else None,
            "K%": f"{round(100.0 * k_n / bf_starts, 1)}%" if bf_starts else None,
            "BB%": f"{round(100.0 * bb_n / bf_starts, 1)}%" if bf_starts else None,
            "K-BB%": f"{round(100.0 * (k_n - bb_n) / bf_starts, 1)}%" if bf_starts else None,
            "HR%": f"{round(100.0 * hr / bf_starts, 1)}%" if bf_starts else None,
            "GB%": f"{round(100.0 * gb_n / in_play_n, 1)}%" if in_play_n else None,
            "FB%": f"{round(100.0 * fb_n / in_play_n, 1)}%" if in_play_n else None,
            "Barrel%": f"{round(100.0 * barrel_n_live / in_play_live_n, 1)}%" if in_play_live_n else (f"{round(100.0 * barrel_n_all / in_play_n, 1)}%" if in_play_n else None),
            "CSW%": f"{round(100.0 * csw_n / n, 1)}%" if n else None,
            "EV": round(sum(float(v) for v in ev_vals) / len(ev_vals), 1) if ev_vals else None,
            "MaxEV": round(max(float(v) for v in ev_vals), 1) if ev_vals else None,
            "LA": round(sum(float(v) for v in la_vals) / len(la_vals), 1) if la_vals else None,
            "VertAttack": (
                round(
                    sum(float(r.get("vertical_attack_angle")) for r in grp if _is_num(r.get("vertical_attack_angle")))
                    / sum(1 for r in grp if _is_num(r.get("vertical_attack_angle"))),
                    1,
                )
                if any(_is_num(r.get("vertical_attack_angle")) for r in grp)
                else None
            ),
            "HorzAttack": (
                round(
                    sum(float(r.get("horizontal_attack_angle")) for r in grp if _is_num(r.get("horizontal_attack_angle")))
                    / sum(1 for r in grp if _is_num(r.get("horizontal_attack_angle"))),
                    1,
                )
                if any(_is_num(r.get("horizontal_attack_angle")) for r in grp)
                else None
            ),
            "BatSpeed": (
                round(
                    sum(float(r.get("bat_speed")) for r in grp if _is_num(r.get("bat_speed")))
                    / sum(1 for r in grp if _is_num(r.get("bat_speed"))),
                    1,
                )
                if any(_is_num(r.get("bat_speed")) for r in grp)
                else None
            ),
            "MaxBatSpeed": (
                round(max(float(r.get("bat_speed")) for r in grp if _is_num(r.get("bat_speed"))), 1)
                if any(_is_num(r.get("bat_speed")) for r in grp)
                else None
            ),
            "Stuff+": round(sum(float(v) for v in stuff_vals) / len(stuff_vals), 1) if stuff_vals else None,
            "Ctrl+": ctrl_plus,
            "QP+": round((qp_mean * 200.0), 1) if _is_num(qp_mean) else None,
            "Pitching+": None,
            "RV/100": round(rv100, 1) if _is_num(rv100) else None,
            "PV/100": round(pv100, 1) if _is_num(pv100) else None,
            "IP": ip_display if outs_for_ip else None,
            "P": n,
            "P/IP": round(float(n) / ip_num, 2) if ip_num > 0 else None,
            "P/BF": round(float(n) / bf_starts, 2) if bf_starts else None,
            "H": hit_n,
            "1B": h1,
            "2B": h2,
            "3B": h3,
            "HR": hr,
            "XBH": xbh_n,
            "Barrels": barrel_n_live if in_play_live_n else barrel_n_all,
            "BB": bb_n,
            "HBP": hbp_n,
            "K": k_n,
            "Whiffs": whiff_n,
            "ERA": round(era_val, 2) if _is_num(era_val) else None,
            "FIP": round(fip_val, 2) if _is_num(fip_val) else None,
            "xFIP": round(x_fip_val, 2) if _is_num(x_fip_val) else None,
            "SIERA": siera_val,
            "WHIP": round((bb_n + hit_n) / ip_num, 2) if ip_num > 0 else None,
            "Swings": swings_count,
            "Takes": takes,
            "Called-S": called_strikes,
            "Chases": chase_num,
            "IZswings": iz_sw_num,
            "FPS": fps_count,
            "EdgeSwings": edge_sw_num,
            "PosSD": possd_points,
            "GoZoneSw": gozone_sw_num,
            "0-0": f"{round(100.0 * count_00 / usage_count_00_total, 1)}%" if usage_count_00_total else None,
            "Behind": f"{round(100.0 * count_behind / usage_count_behind_total, 1)}%" if usage_count_behind_total else None,
            "Even": f"{round(100.0 * count_even / usage_count_even_total, 1)}%" if usage_count_even_total else None,
            "Ahead": f"{round(100.0 * count_ahead / usage_count_ahead_total, 1)}%" if usage_count_ahead_total else None,
            "<2K": f"{round(100.0 * count_lt2k / usage_count_lt2k_total, 1)}%" if usage_count_lt2k_total else None,
            "2K": f"{round(100.0 * count_2k / usage_count_2k_total, 1)}%" if usage_count_2k_total else None,
            "<2Kstrike%": f"{round(100.0 * lt2k_strike_n / count_lt2k, 1)}%" if count_lt2k else None,
            "2Kstrike%": f"{round(100.0 * k2_strike_n / count_2k, 1)}%" if count_2k else None,
            "<2kInZone%": f"{round(100.0 * lt2k_in_zone_n / lt2k_loc_n, 1)}%" if lt2k_loc_n else None,
            "2kInZone%": f"{round(100.0 * k2_in_zone_n / k2_loc_n, 1)}%" if k2_loc_n else None,
            "Fastball%": f"{round(100.0 * pitch_usage_fastball / n, 1)}%" if n else None,
            "Sinker%": f"{round(100.0 * pitch_usage_sinker / n, 1)}%" if n else None,
            "Cutter%": f"{round(100.0 * pitch_usage_cutter / n, 1)}%" if n else None,
            "Slider%": f"{round(100.0 * pitch_usage_slider / n, 1)}%" if n else None,
            "Sweeper%": f"{round(100.0 * pitch_usage_sweeper / n, 1)}%" if n else None,
            "Curveball%": f"{round(100.0 * pitch_usage_curveball / n, 1)}%" if n else None,
            "ChangeUp%": f"{round(100.0 * pitch_usage_changeup / n, 1)}%" if n else None,
            "Splitter%": f"{round(100.0 * pitch_usage_splitter / n, 1)}%" if n else None,
            "FastSink%": f"{round(100.0 * (pitch_usage_fastball + pitch_usage_sinker) / n, 1)}%" if n else None,
            "Breaking%": f"{round(100.0 * (pitch_usage_cutter + pitch_usage_slider + pitch_usage_sweeper + pitch_usage_curveball) / n, 1)}%" if n else None,
            "Change/Split%": f"{round(100.0 * (pitch_usage_changeup + pitch_usage_splitter) / n, 1)}%" if n else None,
            "2kFB%": f"{round(100.0 * pitch_usage_2k_fb / pitch_usage_2k, 1)}%" if pitch_usage_2k else None,
            "2kOS%": f"{round(100.0 * (pitch_usage_2k - pitch_usage_2k_fb) / pitch_usage_2k, 1)}%" if pitch_usage_2k else None,
            "PA": pa_ct,
            "AB": ab,
            "AVG": avg,
            "SLG": slg,
            "OBP": obp,
            "OPS": ops,
            "wOBA": woba,
            "xWOBA": xwoba,
            "ISO": iso,
            "xISO": xiso,
            "BABIP": babip,
        }
        if _is_num(row_out.get("Stuff+")) and row_out.get("QP+"):
            try:
                row_out["Pitching+"] = round((float(row_out["Stuff+"]) + float(row_out["QP+"])) / 2.0, 1)
            except Exception:
                row_out["Pitching+"] = None
        return row_out

    ordered_items: List[tuple[str, List[Dict[str, Any]]]]
    split_clean = (split_by or "Pitch Types").strip()
    if split_clean == "Pitch Types":
        ordered_items = sorted(groups.items(), key=lambda kv: (_pitch_type_sort_rank(kv[0]), kv[0]))
    elif split_clean == "Times Through Order":
        tto_rank = {"1": 0, "2": 1, "3": 2, "4+": 3}
        ordered_items = sorted(groups.items(), key=lambda kv: (tto_rank.get(str(kv[0]), 9), str(kv[0])))
    elif split_clean == "Inning":
        def _inning_rank(v: str) -> tuple[int, int]:
            raw = str(v or "").strip()
            if not raw or raw.lower() == "unknown":
                return (1, 10**9)
            try:
                return (0, int(float(raw)))
            except Exception:
                m = re.search(r"\d+", raw)
                if m:
                    try:
                        return (0, int(m.group(0)))
                    except Exception:
                        pass
                return (1, 10**9)
        ordered_items = sorted(groups.items(), key=lambda kv: (_inning_rank(str(kv[0])), str(kv[0])))
    elif split_clean == "Pitch Count":
        def _pitch_count_rank(v: str) -> tuple[int, int]:
            raw = str(v or "").strip()
            if not raw or raw.lower() == "unknown":
                return (1, 10**9)
            m = re.match(r"^\s*(\d+)\s*-\s*(\d+)\s*$", raw)
            if m:
                try:
                    return (0, int(m.group(1)))
                except Exception:
                    return (1, 10**9)
            m = re.search(r"\d+", raw)
            if m:
                try:
                    return (0, int(m.group(0)))
                except Exception:
                    return (1, 10**9)
            return (1, 10**9)
        ordered_items = sorted(groups.items(), key=lambda kv: (_pitch_count_rank(str(kv[0])), str(kv[0])))
    elif split_clean in {"Count", "After Count"}:
        def _count_rank(v: str) -> tuple[int, int, int]:
            raw = str(v or "").strip()
            m = re.match(r"^([0-3])-([0-2])$", raw)
            if not m:
                return (1, 9, 9)
            return (0, int(m.group(2)), int(m.group(1)))
        ordered_items = sorted(groups.items(), key=lambda kv: (_count_rank(str(kv[0])), str(kv[0])))
    elif split_clean == "Game":
        def _game_rank(v: str) -> tuple[str, str]:
            raw = str(v or "").strip()
            parts = raw.split("||")
            date_part = parts[0].strip() if parts else ""
            key_part = parts[3].strip() if len(parts) > 3 else raw
            return (date_part, key_part)
        ordered_items = sorted(groups.items(), key=lambda kv: _game_rank(str(kv[0])), reverse=True)
    else:
        ordered_items = sorted(groups.items(), key=lambda kv: (-len(kv[1]), kv[0]))
    for key, grp in ordered_items:
        out_rows.append(_row_for_group(key, grp))

    # Always add an All row at the bottom for split views.
    if split_clean == "After Count":
        # Count splits use overlapping PA cohorts; avoid duplicate inflation.
        all_group = list(rows)
    else:
        all_group = [r for group_rows in groups.values() for r in group_rows]
    if all_group and split_clean != "All":
        out_rows.append(_row_for_group("All", all_group))

    # Keep All-row BF/K%/BB%/HR% consistent across split modes.
    row_all = next((row for row in out_rows if str(row.get(split_col_name) or "") == "All"), None)
    if row_all is not None:
        baseline = _global_outcome_baseline(rows)
        for metric in ["BF", "K%", "BB%", "HR%"]:
            row_all[metric] = baseline.get(metric)

    # By definition, every PA reaches 0-0; After Count 0-0 outcome rates must
    # match the All row baseline for BF-based outcome metrics.
    if split_clean == "After Count":
        row_all = next((row for row in out_rows if str(row.get(split_col_name) or "") == "All"), None)
        row_zero = next((row for row in out_rows if str(row.get(split_col_name) or "") == "0-0"), None)
        if row_all and row_zero:
            for metric in ["BF", "K%", "BB%", "HR%"]:
                row_zero[metric] = row_all.get(metric)

    column_map: Dict[str, List[str]] = {
        "Stuff": [split_col_name, "#", "Velo", "Max", "IVB", "HB", "rTilt", "bTilt", "TiltDev", "SpinEff", "Spin", "Height", "Side", "Ext", "VAA", "nVAA", "HAA", "Stuff+"],
        "Expected Movement": [split_col_name, "P", "Velo", "Max", "IVB", "xIVB", "dIVB", "HB", "xHB", "dHB", "MagAngle", "rTilt", "bTilt", "TiltDev", "SpinEff", "Spin", "Height", "Side", "Ext", "VAA", "nVAA", "HAA"],
        "Process": [split_col_name, "#", "BF", "RV/100", "PV/100", "InZone%", "<2kInZone%", "2kInZone%", "Strike%", "<2Kstrike%", "2Kstrike%", "Comp%", "Swing%", "FPS%", "Early%", "Ahead%", "E+A%", "1-1W%", "HR%"],
        "Results": [split_col_name, "#", "BF", "K%", "BB%", "HR%", "GB%", "FB%", "Barrel%", "Whiff%", "SwStrk%", "CSW%", "EV", "LA", "ERA", "FIP", "xFIP", "SIERA"],
        "Banny": [split_col_name, "#", "Usage", "Velo", "Max", "IVB", "HB", "Strike%", "Whiff%", "K%", "BB%", "QP+"],
        "Hitting Results": [split_col_name, "PA", "AB", "AVG", "SLG", "OBP", "OPS", "wOBA", "xWOBA", "ISO", "xISO", "BABIP", "Swing%", "FPS(FB)%", "FPS(OS)%", "Whiff%", "GB%", "K%", "BB%", "Barrel%", "EV", "LA"],
        "Swing Metrics": [split_col_name, "VertAttack", "HorzAttack", "BatSpeed", "MaxBatSpeed", "EV", "MaxEV", "LA"],
        "Bullpen": [split_col_name, "#", "Velo", "Max", "IVB", "HB", "Spin", "bTilt", "Height", "Side", "Ext", "InZone%", "Comp%", "Ctrl+", "Stuff+"],
        "Live": [split_col_name, "#", "Velo", "Max", "IVB", "HB", "FPS%", "E+A%", "InZone%", "Strike%", "Whiff%", "K%", "BB%", "HR%", "QP+"],
        "Usage": [split_col_name, "#", "Usage", "0-0", "Behind", "Even", "Ahead", "<2K", "2K"],
        "Pitch Usage": _pitch_usage_mode_columns(split_col_name),
        "Raw Data": [split_col_name, "IP", "P", "BF", "P/IP", "P/BF", "H", "1B", "2B", "3B", "HR", "XBH", "Barrels", "BB", "HBP", "K", "Whiffs"],
        "Batted Ball Data": [split_col_name, "PA", "AB", "AVG", "SLG", "OBP", "OPS", "wOBA", "xWOBA", "ISO", "xISO", "BABIP", "FPS(FB)%", "FPS(OS)%", "Barrel%"],
        "Swing Decisions": [split_col_name, "Swing%", "FPS%", "FPS(FB)%", "FPS(OS)%", "Called-S%", "Take%", "Chase%", "GoZoneSw%", "IZswing%", "EdgeSwing%", "PosSD%"],
        "Custom": [split_col_name],
    }
    if mode_key == "Custom":
        normalized_custom = _normalize_custom_columns(custom_columns)
        columns = [split_col_name, *normalized_custom]
    else:
        columns = column_map.get(mode_key, column_map["Stuff"])
    return columns, out_rows, ALL_TABLE_COLUMNS


def _pitch_action_payload(row: Dict[str, Any], avg_stuff_by_pitch_type: Dict[str, float]) -> Dict[str, Any]:
    qp = _compute_qp_point(row)
    school_code = str(row.get("school_code") or "").strip().upper()
    if school_code == "PRO":
        # PRO prefers hitter-side Statcast delta_run_exp when enriched rows exist.
        # During live API fallback windows (before Savant enrichment), use
        # legacy event-based run value so charts don't go blank.
        if _is_num(row.get("delta_run_exp")):
            run_value = float(row.get("delta_run_exp"))
        else:
            run_value = _calc_run_value(
                row.get("pitch_call"),
                row.get("play_result"),
                row.get("korbb"),
                row.get("balls_num"),
                row.get("strikes_num"),
                row.get("outs_num"),
                row.get("outs_on_play_num"),
            )
    else:
        run_value = _calc_run_value(
            row.get("pitch_call"),
            row.get("play_result"),
            row.get("korbb"),
            row.get("balls_num"),
            row.get("strikes_num"),
            row.get("outs_num"),
            row.get("outs_on_play_num"),
        )
    pitch_value = _calc_pitch_value(
        row.get("pitch_call"),
        row.get("play_result"),
        row.get("korbb"),
        row.get("balls_num"),
        row.get("strikes_num"),
        row.get("outs_num"),
        row.get("outs_on_play_num"),
        school_code,
    )
    break_tilt_raw = str(row.get("break_tilt") or "").strip()
    if school_code == "PRO" and not break_tilt_raw:
        break_tilt_raw = _movement_to_break_tilt_clock(row.get("ivb"), row.get("hb")) or ""
    action_vaa = row.get("vaa")
    action_haa = row.get("haa")
    if school_code == "PRO" and (not _is_num(action_vaa) or not _is_num(action_haa)):
        inferred_vaa, inferred_haa = _infer_pro_vaa_haa_from_kinematics(row)
        if not _is_num(action_vaa) and _is_num(inferred_vaa):
            action_vaa = inferred_vaa
        if not _is_num(action_haa) and _is_num(inferred_haa):
            action_haa = inferred_haa
    action_nvaa = _normalized_vaa_value(
        action_vaa,
        row.get("plate_height"),
        row.get("pitch_type"),
        is_pro=(school_code == "PRO"),
    )
    return {
        "pitch_event_id": row.get("id"),
        "pitch_uid": str(row.get("pitch_uid") or ""),
        "play_id": str(row.get("play_id") or ""),
        "game_id": str(row.get("game_id") or ""),
        "game_uid": str(row.get("game_uid") or ""),
        "game_foreign_id": str(row.get("game_foreign_id") or ""),
        "inning": str(row.get("inning") or ""),
        "pitch_no": row.get("pitch_no"),
        "pitch_number": row.get("pitch_number"),
        "session_date": row.get("session_date").isoformat() if row.get("session_date") else None,
        "pitcher": str(row.get("pitcher") or ""),
        "batter": str(row.get("batter") or ""),
        "catcher": str(row.get("catcher") or ""),
        "pitcherthrows": str(row.get("pitcherthrows") or ""),
        "batterside": str(row.get("batterside") or ""),
        "pitcher_team_code": str(row.get("pitcher_team_code") or ""),
        "batter_team_code": str(row.get("batter_team_code") or ""),
        "pitcher_team_norm": str(row.get("pitcher_team_norm") or ""),
        "batter_team_norm": str(row.get("batter_team_norm_eff") or row.get("batter_team_norm") or ""),
        "pitch_type": str(row.get("pitch_type") or "Undefined"),
        "session_type": str(row.get("session_type_norm") or ""),
        "pitch_call": str(row.get("pitch_call") or ""),
        "play_result": str(row.get("play_result") or ""),
        "korbb": str(row.get("korbb") or ""),
        "tagged_hit_type": str(row.get("tagged_hit_type") or ""),
        "balls_num": row.get("balls_num"),
        "strikes_num": row.get("strikes_num"),
        "outs_num": row.get("outs_num"),
        "outs_on_play_num": row.get("outs_on_play_num"),
        "run_value": run_value,
        "pitch_value": pitch_value,
        "release_side": row.get("rel_side"),
        "release_height": row.get("rel_height"),
        "extension": row.get("ext_value"),
        "hb": row.get("hb"),
        "ivb": row.get("ivb"),
        "plate_side": row.get("plate_side"),
        "plate_height": row.get("plate_height"),
        "velo": row.get("rel_speed"),
        "spin": row.get("spin_rate"),
        "release_tilt": str(row.get("release_tilt") or ""),
        "break_tilt": break_tilt_raw,
        "spin_eff": row.get("spin_eff"),
        "exit_speed": row.get("exit_speed"),
        "angle": row.get("angle"),
        "vaa": action_vaa,
        "nvaa": action_nvaa,
        "haa": action_haa,
        "estimated_woba_using_speedangle": (
            float(row.get("estimated_woba_using_speedangle"))
            if _is_num(row.get("estimated_woba_using_speedangle"))
            else None
        ),
        "estimated_ba_using_speedangle": (
            float(row.get("estimated_ba_using_speedangle"))
            if _is_num(row.get("estimated_ba_using_speedangle"))
            else None
        ),
        "iso_value": (
            float(row.get("iso_value"))
            if _is_num(row.get("iso_value"))
            else None
        ),
        "stuff_plus": avg_stuff_by_pitch_type.get(str(row.get("pitch_type") or "")),
        "qp_plus": (round(float(qp) * 200.0, 1) if _is_num(qp) else None),
        "video_clip_1": str(row.get("video_clip_1") or ""),
        "video_clip_2": str(row.get("video_clip_2") or ""),
        "video_clip_3": str(row.get("video_clip_3") or ""),
    }


def _build_chart_points(
    rows: List[Dict[str, Any]], avg_stuff_by_pitch_type: Dict[str, float], max_points: int = 3500
) -> List[Dict[str, Any]]:
    if not rows:
        return []
    step = max(1, len(rows) // max_points) if len(rows) > max_points else 1
    sampled = rows[::step]
    points: List[Dict[str, Any]] = []
    for row in sampled[:max_points]:
        points.append(_pitch_action_payload(row, avg_stuff_by_pitch_type))
    return points


def _build_trend_rows(
    rows: List[Dict[str, Any]],
    avg_stuff_by_pitch_type: Dict[str, float],
    use_osu_date_session_rules: bool = False,
) -> List[Dict[str, Any]]:
    if not rows:
        return []
    is_pro_dataset = any(str(row.get("school_code") or "").strip().upper() == "PRO" for row in rows)

    def _pro_norm_desc(value: Any) -> str:
        normalized = re.sub(r"[^a-z0-9]+", "_", str(value or "").strip().lower()).strip("_")
        if normalized == "swinging_strike_blocked":
            return "swinging_strike"
        return normalized

    def _bucket(row: Dict[str, Any]) -> Optional[str]:
        st = str(row.get("session_type_norm") or "").lower()
        st_compact = re.sub(r"[\s_-]+", "", st)
        if "bull" in st_compact or "prac" in st_compact:
            return "Bullpen"
        if "season" in st_compact or "game" in st_compact:
            return "Season"
        if "live" in st_compact or "ab" in st_compact:
            return "Live BP"
        dt = row.get("session_date")
        dt_val: Optional[date]
        if isinstance(dt, date):
            dt_val = dt
        else:
            dt_str = str(dt or "")[:10]
            if not dt_str:
                dt_val = None
            else:
                try:
                    dt_val = date.fromisoformat(dt_str)
                except ValueError:
                    dt_val = None
        if use_osu_date_session_rules and dt_val is not None:
            if dt_val < OSU_SEASON_START:
                return "Live BP"
            if dt_val <= OSU_SEASON_END:
                return "Season"
            return "Season"
        return None

    grouped: Dict[tuple[str, str], Dict[str, Any]] = {}
    for row in rows:
        is_pro_row = str(row.get("school_code") or "").strip().upper() == "PRO"
        dt = row.get("session_date")
        date_key = dt.isoformat() if hasattr(dt, "isoformat") else str(dt or "")[:10]
        if not date_key:
            continue
        bucket = _bucket(row)
        if not bucket:
            continue
        gkey = (bucket, date_key)
        agg = grouped.get(gkey)
        if agg is None:
            agg = {
                "session_bucket": bucket,
                "date": date_key,
                "pitches": 0,
                "velo_sum": 0.0,
                "velo_n": 0,
                "velo_max": None,
                "spin_sum": 0.0,
                "spin_n": 0,
                "ivb_sum": 0.0,
                "ivb_n": 0,
                "hb_sum": 0.0,
                "hb_n": 0,
                "rel_height_sum": 0.0,
                "rel_height_n": 0,
                "rel_side_sum": 0.0,
                "rel_side_n": 0,
                "extension_sum": 0.0,
                "extension_n": 0,
                "stuff_sum": 0.0,
                "stuff_n": 0,
                "qp_sum": 0.0,
                "qp_n": 0,
                "in_zone_n": 0,
                "comp_n": 0,
                "strike_n": 0,
                "swing_n": 0,
                "whiff_n": 0,
                "csw_n": 0,
                "fps_den": 0,
                "fps_num": 0,
                "early_den": 0,
                "early_num": 0,
                "ahead_den": 0,
                "ahead_num": 0,
                "ea_den": 0,
                "ea_num": 0,
                "oneone_den": 0,
                "oneone_num": 0,
                "qp_den": 0,
                "qp_num": 0,
                "in_play_n": 0,
                "gb_n": 0,
                "barrel_n": 0,
                "ev_sum": 0.0,
                "ev_n": 0,
                "la_sum": 0.0,
                "la_n": 0,
                "rv_sum": 0.0,
                "pv_sum": 0.0,
                "whiffs": 0,
                "bf_keys": set(),
                "k_keys": set(),
                "bb_keys": set(),
                "rows": [],
            }
            grouped[gkey] = agg
        agg["rows"].append(row)

        pitch_call = str(row.get("pitch_call") or "")
        play_result = str(row.get("play_result") or "")
        korbb = str(row.get("korbb") or "")
        balls = row.get("balls_num")
        strikes = row.get("strikes_num")
        if is_pro_row:
            game_pk = str(row.get("game_pk") or row.get("game_id") or row.get("game_uid") or row.get("game_foreign_id") or "g").strip()
            ab_idx = str(row.get("at_bat_index") or "").strip()
            pa_key = f"{game_pk}|ab|{ab_idx}" if ab_idx else f"{game_pk}|pitch|{row.get('id') or row.get('pitch_no') or row.get('pitch_number') or 'p'}"
        else:
            game_key = str(
                row.get("game_pk")
                or row.get("game_id")
                or row.get("game_uid")
                or row.get("game_foreign_id")
                or row.get("session_date")
                or "g"
            ).strip()
            ab_idx = str(row.get("at_bat_index") or "").strip()
            play_id = str(row.get("play_id") or "").strip()
            inning = str(row.get("inning") or "").strip()
            batter_norm = _normalize_name_key(str(row.get("batter") or ""))
            if game_key and ab_idx:
                pa_key = f"{game_key}|ab|{ab_idx}"
            elif game_key and play_id:
                pa_key = f"{game_key}|play|{play_id}"
            elif game_key and inning and batter_norm:
                pa_key = f"{game_key}|inn|{inning}|bat|{batter_norm}"
            else:
                pa_key = f"{game_key}|pitch|{row.get('id') or row.get('pitch_no') or row.get('pitch_number') or 'p'}"

        agg["pitches"] += 1
        if _is_num(row.get("rel_speed")):
            v = float(row.get("rel_speed"))
            agg["velo_sum"] += v
            agg["velo_n"] += 1
            agg["velo_max"] = v if agg["velo_max"] is None else max(float(agg["velo_max"]), v)
        if _is_num(row.get("spin_rate")):
            agg["spin_sum"] += float(row.get("spin_rate"))
            agg["spin_n"] += 1
        if _is_num(row.get("ivb")):
            agg["ivb_sum"] += float(row.get("ivb"))
            agg["ivb_n"] += 1
        if _is_num(row.get("hb")):
            agg["hb_sum"] += float(row.get("hb"))
            agg["hb_n"] += 1
        if _is_num(row.get("rel_height")):
            agg["rel_height_sum"] += float(row.get("rel_height"))
            agg["rel_height_n"] += 1
        if _is_num(row.get("rel_side")):
            agg["rel_side_sum"] += float(row.get("rel_side"))
            agg["rel_side_n"] += 1
        if _is_num(row.get("ext_value")):
            agg["extension_sum"] += float(row.get("ext_value"))
            agg["extension_n"] += 1

        stuff = avg_stuff_by_pitch_type.get(str(row.get("pitch_type") or ""))
        if _is_num(stuff):
            agg["stuff_sum"] += float(stuff)
            agg["stuff_n"] += 1

        qp = _compute_qp_point(row)
        if _is_num(qp):
            qp_plus = float(qp) * 200.0
            agg["qp_sum"] += qp_plus
            agg["qp_n"] += 1
            agg["qp_den"] += 1
            if qp_plus >= 100.0:
                agg["qp_num"] += 1

        if is_pro_row:
            zone_num = row.get("zone_num")
            in_zone_yes = _is_num(zone_num) and 1 <= int(float(zone_num)) <= 9
            if in_zone_yes:
                agg["in_zone_n"] += 1
            # For PRO, keep Comp% aligned to InZone% (no separate competitive zone definition).
            if in_zone_yes:
                agg["comp_n"] += 1
        else:
            inz = _in_zone_label(row.get("plate_side"), row.get("plate_height"))
            if inz == "Yes":
                agg["in_zone_n"] += 1
            if inz in {"Yes", "Competitive"}:
                agg["comp_n"] += 1

        if is_pro_row:
            d = _pro_norm_desc(pitch_call)
            pr_norm = _pro_norm_desc(play_result)
            strike_excluded = {"ball", "hit_by_pitch", "blocked_ball"}
            is_strike = bool(d) and d not in strike_excluded
            is_in_play_desc = d.startswith("in_play") or d.startswith("hit_into_play")
            is_swing = (
                d in {
                    "swinging_strike",
                    "swinging_strike_blocked",
                    "swinging_strike_pitchout",
                    "foul",
                    "foul_tip",
                    "foul_bunt",
                    "foul_pitchout",
                    "missed_bunt",
                }
                or d.startswith("foul")
                or is_in_play_desc
            )
            is_whiff = d in {"swinging_strike", "swinging_strike_blocked", "foul_tip"}
            is_csw = d in {"called_strike", "swinging_strike", "swinging_strike_blocked", "foul_tip"}
        else:
            is_strike = pitch_call in {"StrikeCalled", "StrikeSwinging", "FoulBall", "FoulBallFieldable", "FoulBallNotFieldable", "InPlay"}
            is_swing = pitch_call in {"StrikeSwinging", "FoulBall", "FoulBallFieldable", "FoulBallNotFieldable", "InPlay"}
            is_whiff = pitch_call == "StrikeSwinging"
            is_csw = pitch_call == "StrikeCalled" or is_whiff
        if is_strike:
            agg["strike_n"] += 1
        if is_swing:
            agg["swing_n"] += 1
        if is_whiff:
            agg["whiff_n"] += 1
            agg["whiffs"] += 1
        if is_csw:
            agg["csw_n"] += 1

        if _is_num(balls) and _is_num(strikes):
            b = int(float(balls))
            s = int(float(strikes))
            if is_pro_row:
                is_in_play_desc = d.startswith("in_play") or d.startswith("hit_into_play")
                if (b == 0 and s == 1) or (b == 0 and s == 0 and is_in_play_desc):
                    agg["fps_num"] += 1
                if b == 1 and s == 1:
                    agg["oneone_den"] += 1
                    if d and d not in {"ball", "hit_by_pitch", "blocked_ball"}:
                        agg["oneone_num"] += 1
                if (b, s) in {(0, 0), (1, 0), (1, 1), (0, 1)} and is_in_play_desc:
                    agg["early_num"] += 1
                if (b, s) in {(0, 1), (1, 1)} and d in {"swinging_strike", "foul", "foul_tip", "called_strike"}:
                    agg["ahead_num"] += 1
            else:
                if b == 0 and s == 0:
                    agg["fps_den"] += 1
                    if is_strike:
                        agg["fps_num"] += 1
                if b + s <= 1:
                    agg["early_den"] += 1
                    if is_strike:
                        agg["early_num"] += 1
                if s > b:
                    agg["ahead_den"] += 1
                    if is_strike:
                        agg["ahead_num"] += 1
                if b == 1 and s == 1:
                    agg["oneone_den"] += 1
                    if is_strike:
                        agg["oneone_num"] += 1
                if (b + s <= 1) or (s > b):
                    agg["ea_den"] += 1
                    if is_strike:
                        agg["ea_num"] += 1

        if (is_pro_row and (d.startswith("in_play") or d.startswith("hit_into_play"))) or (not is_pro_row and pitch_call == "InPlay"):
            agg["in_play_n"] += 1
            tagged = str(row.get("tagged_hit_type") or "").lower()
            if is_pro_row:
                if _is_ground_ball_tag(tagged):
                    agg["gb_n"] += 1
            elif "ground" in tagged:
                agg["gb_n"] += 1
            if _is_num(row.get("exit_speed")):
                agg["ev_sum"] += float(row.get("exit_speed"))
                agg["ev_n"] += 1
            if _is_num(row.get("angle")):
                la_val = float(row.get("angle"))
                agg["la_sum"] += la_val
                agg["la_n"] += 1
                if is_pro_row and _is_num(row.get("exit_speed")):
                    ev_val = float(row.get("exit_speed"))
                    if ev_val >= 95.0 and 10.0 <= la_val <= 35.0:
                        agg["barrel_n"] += 1
            elif not is_pro_row and "barrel" in tagged:
                agg["barrel_n"] += 1
        if is_pro_row:
            if _is_num(row.get("delta_run_exp")):
                agg["rv_sum"] += float(row.get("delta_run_exp"))
        else:
            agg["rv_sum"] += _calc_run_value(
                pitch_call,
                play_result,
                korbb,
                balls,
                strikes,
                row.get("outs_num"),
                row.get("outs_on_play_num"),
            )
        agg["pv_sum"] += _calc_pitch_value(
            pitch_call,
            play_result,
            korbb,
            balls,
            strikes,
            row.get("outs_num"),
            row.get("outs_on_play_num"),
            row.get("school_code"),
        )
        if is_pro_row:
            agg["bf_keys"].add(pa_key)
        else:
            # Non-PRO BF uses only PA-start rows (0-0).
            if balls == 0 and strikes == 0:
                agg["bf_keys"].add(pa_key)
        if is_pro_row:
            if pr_norm in {"strikeout", "strikeout_double_play"}:
                agg["k_keys"].add(pa_key)
            if pr_norm == "walk":
                agg["bb_keys"].add(pa_key)
        else:
            if korbb == "Strikeout":
                agg["k_keys"].add(pa_key)
            if korbb == "Walk":
                agg["bb_keys"].add(pa_key)

    def _pct(num: float, den: float) -> Optional[float]:
        return (100.0 * float(num) / float(den)) if den and den > 0 else None

    out: List[Dict[str, Any]] = []
    for (_, _), agg in grouped.items():
        bf = len(agg["bf_keys"])
        k = len(agg["k_keys"])
        bb = len(agg["bb_keys"])
        pitches = int(agg["pitches"])
        # Derive denominators for PRO using BF-based formulas while keeping non-PRO behavior unchanged.
        if is_pro_dataset:
            pro_rows = list(agg.get("rows") or [])
            pa_keys: set[str] = set()
            for r in pro_rows:
                game_pk = str(r.get("game_pk") or r.get("game_id") or r.get("game_uid") or r.get("game_foreign_id") or "").strip()
                ab_idx = str(r.get("at_bat_index") or "").strip()
                if game_pk and ab_idx:
                    pa_keys.add(f"{game_pk}|ab|{ab_idx}")
            terminal_rows = [
                r
                for r in pro_rows
                if (str(r.get("play_result") or "").strip() not in {"", "Undefined"})
                or (str(r.get("korbb") or "").strip() in {"Strikeout", "Walk"})
                or (_pro_norm_desc(r.get("pitch_call")) == "hit_by_pitch")
            ]
            def _pro_row_order_key(rr: Dict[str, Any]) -> tuple:
                return (
                    str(rr.get("session_date") or ""),
                    int(rr.get("game_pk") or rr.get("game_id") or 0),
                    int(rr.get("at_bat_index") or 0),
                    int(rr.get("event_index") or 0),
                    int(rr.get("pitch_number") or 0),
                    int(rr.get("id") or 0),
                )

            bf_fallback = 0
            prev: Optional[Dict[str, Any]] = None
            for r in sorted(pro_rows, key=_pro_row_order_key):
                b = r.get("balls_num")
                s = r.get("strikes_num")
                if b == 0 and s == 0:
                    skip = False
                    if prev is not None:
                        pb = prev.get("balls_num")
                        ps = prev.get("strikes_num")
                        prev_event_blank = str(prev.get("play_result") or "").strip() == ""
                        if pb == 0 and ps == 0 and prev_event_blank:
                            skip = True
                    if not skip:
                        bf_fallback += 1
                prev = r
            if terminal_rows:
                bf = len(terminal_rows)
            else:
                bf = max(len(pa_keys), bf_fallback)
            k = sum(
                1
                for r in pro_rows
                if _pro_norm_desc(r.get("play_result")) in {"strikeout", "strikeout_double_play"}
            )
            bb = sum(1 for r in pro_rows if _pro_norm_desc(r.get("play_result")) == "walk")
            fps_den = bf if bf > 0 else agg["fps_den"]
            early_den = bf if bf > 0 else agg["early_den"]
            ahead_den = bf if bf > 0 else agg["ahead_den"]
            ea_num = (agg["early_num"] + agg["ahead_num"]) if bf > 0 else agg["ea_num"]
            ea_den = bf if bf > 0 else agg["ea_den"]
        else:
            fps_den = agg["fps_den"]
            early_den = agg["early_den"]
            ahead_den = agg["ahead_den"]
            ea_num = agg["ea_num"]
            ea_den = agg["ea_den"]
        out.append(
            {
                "session_bucket": agg["session_bucket"],
                "date": agg["date"],
                "values": {
                    "Velocity (Avg)": (agg["velo_sum"] / agg["velo_n"]) if agg["velo_n"] else None,
                    "Velocity (Max)": agg["velo_max"],
                    "Spin": (agg["spin_sum"] / agg["spin_n"]) if agg["spin_n"] else None,
                    "IVB": (agg["ivb_sum"] / agg["ivb_n"]) if agg["ivb_n"] else None,
                    "HB": (agg["hb_sum"] / agg["hb_n"]) if agg["hb_n"] else None,
                    "Release Height": (agg["rel_height_sum"] / agg["rel_height_n"]) if agg["rel_height_n"] else None,
                    "Release Side": (agg["rel_side_sum"] / agg["rel_side_n"]) if agg["rel_side_n"] else None,
                    "Extension": (agg["extension_sum"] / agg["extension_n"]) if agg["extension_n"] else None,
                    "Stuff+": (agg["stuff_sum"] / agg["stuff_n"]) if agg["stuff_n"] else None,
                    "QP+": (agg["qp_sum"] / agg["qp_n"]) if agg["qp_n"] else None,
                    "InZone%": _pct(agg["in_zone_n"], pitches),
                    "Comp%": _pct(agg["comp_n"], pitches),
                    "Strike%": _pct(agg["strike_n"], pitches),
                    "Swing%": _pct(agg["swing_n"], pitches),
                    "FPS%": _pct(agg["fps_num"], fps_den),
                    "Early%": _pct(agg["early_num"], early_den),
                    "Ahead%": _pct(agg["ahead_num"], ahead_den),
                    "E+A%": _pct(ea_num, ea_den),
                    "1-1W%": _pct(agg["oneone_num"], agg["oneone_den"]),
                    "QP%": _pct(agg["qp_num"], agg["qp_den"]),
                    "Whiff%": _pct(agg["whiff_n"], agg["swing_n"]),
                    "CSW%": _pct(agg["csw_n"], pitches),
                    "K%": _pct(k, bf),
                    "BB%": _pct(bb, bf),
                    "GB%": _pct(agg["gb_n"], agg["in_play_n"]),
                    "Barrel%": _pct(agg["barrel_n"], agg["in_play_n"]),
                    "Exit Velocity": (agg["ev_sum"] / agg["ev_n"]) if agg["ev_n"] else None,
                    "Launch Angle": (agg["la_sum"] / agg["la_n"]) if agg["la_n"] else None,
                    "RV/100": ((agg["rv_sum"] / pitches) * 100.0) if pitches else None,
                    "PV/100": ((agg["pv_sum"] / pitches) * 100.0) if pitches else None,
                    "P": pitches,
                    "BF": bf,
                    "Whiffs": int(agg["whiffs"]),
                    "K": k,
                    "BB": bb,
                },
            }
        )
    out.sort(key=lambda row: (str(row.get("session_bucket") or ""), str(row.get("date") or "")))
    return out


def _build_row_pitch_map(
    rows: List[Dict[str, Any]],
    split_by: str,
    avg_stuff_by_pitch_type: Dict[str, float],
    max_per_row: int = 220,
) -> Dict[str, List[Dict[str, Any]]]:
    grouped: Dict[str, List[Dict[str, Any]]] = {}
    for row in rows:
        key = _split_key_from_row(row, split_by)
        bucket = grouped.setdefault(key, [])
        if len(bucket) >= max_per_row:
            continue
        bucket.append(_pitch_action_payload(row, avg_stuff_by_pitch_type))
    return grouped


def _normalize_name_key(value: str) -> str:
    return re.sub(r"[^a-z0-9]", "", (value or "").strip().lower())


def _legacy_uppercase_stripped_name_key(value: str) -> str:
    """Match legacy PRO rollup keys written before lowercasing the name first."""
    return re.sub(r"[^a-z0-9]", "", (value or "").strip()).lower()


def _name_filter_keys(values: List[str]) -> List[str]:
    keys = set()
    for raw_value in values:
        raw = (raw_value or "").strip()
        if not raw:
            continue
        candidates = [raw]
        if "," in raw:
            parts = [part.strip() for part in raw.split(",") if part.strip()]
            if len(parts) >= 2:
                candidates.append(" ".join([*parts[1:], parts[0]]))
        else:
            parts = [part for part in raw.split() if part]
            if len(parts) >= 2:
                candidates.append(" ".join([*parts[1:], parts[0]]))
        for candidate in candidates:
            base = _normalize_name_key(candidate)
            if base:
                keys.add(base)
            legacy = _legacy_uppercase_stripped_name_key(candidate)
            if legacy:
                keys.add(legacy)
    return sorted(keys)


def _ab_is_terminal(row: Dict[str, Any]) -> bool:
    play_result = str(row.get("play_result") or "")
    korbb = str(row.get("korbb") or "")
    pitch_call = str(row.get("pitch_call") or "")
    return (
        (play_result != "" and play_result != "Undefined")
        or (korbb in {"Strikeout", "Walk"})
        or (pitch_call == "HitByPitch")
    )


def _ab_pa_result_label(row: Dict[str, Any]) -> str:
    play_result = str(row.get("play_result") or "")
    korbb = str(row.get("korbb") or "")
    pitch_call = str(row.get("pitch_call") or "")
    if pitch_call == "HitByPitch":
        return "HitByPitch"
    if korbb in {"Strikeout", "Walk"}:
        return korbb
    if play_result and play_result != "Undefined":
        if play_result == "HomeRun":
            return "HomeRun"
        return play_result
    if play_result:
        return play_result
    if pitch_call:
        return pitch_call
    return "Result"


def _ab_group_rows(rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    if not rows:
        return []
    grouped: List[List[Dict[str, Any]]] = []
    current: List[Dict[str, Any]] = []
    prev_row: Optional[Dict[str, Any]] = None
    prev_terminal = False
    for row in rows:
        batter = str(row.get("batter") or "")
        start_new = False
        if not current:
            start_new = True
        elif prev_terminal:
            start_new = True
        elif str(prev_row.get("batter") or "") != batter if prev_row else False:
            start_new = True
        else:
            b = row.get("balls_num")
            s = row.get("strikes_num")
            pb = prev_row.get("balls_num") if prev_row else None
            ps = prev_row.get("strikes_num") if prev_row else None
            if _is_num(b) and _is_num(s) and _is_num(pb) and _is_num(ps):
                if int(float(b)) == 0 and int(float(s)) == 0 and not (int(float(pb)) == 0 and int(float(ps)) == 0):
                    start_new = True
        if start_new:
            if current:
                grouped.append(current)
            current = [row]
        else:
            current.append(row)
        prev_terminal = _ab_is_terminal(row)
        prev_row = row
    if current:
        grouped.append(current)
    # Keep completed PAs only.
    return [g for g in grouped if any(_ab_is_terminal(r) for r in g)]


def _extract_r_vector(text: str, key: str) -> List[str]:
    match = re.search(rf"{re.escape(key)}\s*=\s*c\((.*?)\)", text, re.DOTALL)
    if not match:
        return []
    block = match.group(1)
    return [item.strip() for item in re.findall(r'"([^"]+)"', block) if item.strip()]


def _extract_r_scalar(text: str, key: str) -> Optional[str]:
    match = re.search(rf"{re.escape(key)}\s*=\s*\"([^\"]+)\"", text)
    if not match:
        return None
    value = (match.group(1) or "").strip()
    return value or None


def _normalize_team_code(value: str) -> str:
    return re.sub(r"[^A-Z0-9_]", "", (value or "").strip().upper())


_TEAM_PLACEHOLDER_CODES = {"", "ALL", "OPP", "OPPONENTS", "CAMPERS", "PRO"}
_LEAGUE_EXCLUDED_SCHOOL_CODES = ("PRO", "LEAGUE", "TRIAL")
_LEAGUE_EXCLUDED_TEAM_CODES = ("TRIAL", "DASHBOARDTRIAL")
LEAGUE_SCHOOL_SCOPE_SQL = "school_code = 'LEAGUE'"
LEAGUE_ROLLUP_TEAM_EXCLUSION_SQL = """
(
  UPPER(regexp_replace(COALESCE(NULLIF(TRIM(pitcher_team_norm), ''), ''), '[^A-Za-z0-9]', '', 'g')) NOT IN ('TRIAL', 'DASHBOARDTRIAL')
  AND UPPER(regexp_replace(COALESCE(NULLIF(TRIM(batter_team_norm_eff), ''), ''), '[^A-Za-z0-9]', '', 'g')) NOT IN ('TRIAL', 'DASHBOARDTRIAL')
)
"""


def _is_placeholder_team_code(value: Any) -> bool:
    return _normalize_team_code(str(value or "")) in _TEAM_PLACEHOLDER_CODES


def _session_date_key(value: Any) -> str:
    if isinstance(value, date):
        return value.isoformat()
    return str(value or "").strip()


def _row_game_group_key(row: Dict[str, Any]) -> Optional[str]:
    session_key = _session_date_key(row.get("session_date"))
    if not session_key:
        return None
    game_id = str(row.get("game_id") or "").strip()
    game_uid = str(row.get("game_uid") or "").strip()
    game_foreign_id = str(row.get("game_foreign_id") or "").strip()
    if game_uid:
        return f"{session_key}|uid:{game_uid}"
    if game_id:
        return f"{session_key}|gid:{game_id}"
    if game_foreign_id:
        return f"{session_key}|fgid:{game_foreign_id}"
    home_code = _normalize_team_code(str(row.get("home_team_code") or ""))
    away_code = _normalize_team_code(str(row.get("away_team_code") or ""))
    if home_code and away_code:
        return f"{session_key}|ha:{home_code}|{away_code}"
    return None


def _resolve_college_opp_placeholders(
    rows: List[Dict[str, Any]],
    school_code: str,
    team_markers_norm: set[str],
) -> List[Dict[str, Any]]:
    # PRO and PCU intentionally keep their existing team-code behavior.
    if not rows or school_code in {"PRO", "PCU"}:
        return rows
    markers = {
        _normalize_team_code(code)
        for code in ({*team_markers_norm, school_code})
        if _normalize_team_code(code)
    }
    if not markers:
        return rows

    opponent_code_by_group: Dict[str, str] = {}
    candidates_by_group: Dict[str, set[str]] = {}
    for row in rows:
        group_key = _row_game_group_key(row)
        if not group_key:
            continue
        candidate_set = candidates_by_group.setdefault(group_key, set())
        for raw in (
            row.get("pitcher_team_code"),
            row.get("batter_team_code"),
            row.get("home_team_code"),
            row.get("away_team_code"),
        ):
            code = _normalize_team_code(str(raw or ""))
            if not code or code in markers or _is_placeholder_team_code(code):
                continue
            candidate_set.add(code)
    for group_key, codes in candidates_by_group.items():
        if len(codes) == 1:
            opponent_code_by_group[group_key] = next(iter(codes))

    if not opponent_code_by_group:
        return rows

    for row in rows:
        group_key = _row_game_group_key(row)
        if not group_key:
            continue
        opponent_code = opponent_code_by_group.get(group_key)
        if not opponent_code:
            continue
        pitcher_code = _normalize_team_code(str(row.get("pitcher_team_code") or ""))
        batter_code = _normalize_team_code(str(row.get("batter_team_code") or ""))
        home_code = _normalize_team_code(str(row.get("home_team_code") or ""))
        away_code = _normalize_team_code(str(row.get("away_team_code") or ""))

        marker_hint_on_row = (
            (pitcher_code in markers)
            or (batter_code in markers)
            or (home_code in markers)
            or (away_code in markers)
        )
        if not marker_hint_on_row:
            continue

        if _is_placeholder_team_code(pitcher_code):
            row["pitcher_team_code"] = opponent_code
            pitcher_code = opponent_code
        if _is_placeholder_team_code(batter_code):
            row["batter_team_code"] = opponent_code
            batter_code = opponent_code
        if _is_placeholder_team_code(home_code) and away_code in markers:
            row["home_team_code"] = opponent_code
            home_code = opponent_code
        if _is_placeholder_team_code(away_code) and home_code in markers:
            row["away_team_code"] = opponent_code
            away_code = opponent_code

        if "pitcher_team_norm" in row:
            row["pitcher_team_norm"] = _normalize_team_code(str(row.get("pitcher_team_code") or ""))
        if "batter_team_norm" in row:
            row["batter_team_norm"] = _normalize_team_code(str(row.get("batter_team_code") or ""))
        if "batter_team_norm_eff" in row:
            batter_eff = _normalize_team_code(str(row.get("batter_team_code") or ""))
            if not batter_eff:
                pitcher_eff = _normalize_team_code(str(row.get("pitcher_team_code") or ""))
                home_eff = _normalize_team_code(str(row.get("home_team_code") or ""))
                away_eff = _normalize_team_code(str(row.get("away_team_code") or ""))
                if pitcher_eff and home_eff and away_eff:
                    if pitcher_eff == home_eff and away_eff:
                        batter_eff = away_eff
                    elif pitcher_eff == away_eff and home_eff:
                        batter_eff = home_eff
            row["batter_team_norm_eff"] = batter_eff
    return rows


