LEAGUE_TEAM_CODE_BY_NAME = {value.lower(): code for code, value in LEAGUE_TEAM_NAME_BY_CODE.items()}
LEAGUE_TEAM_CODE_BY_NAME_NORMALIZED = {
    re.sub(r"[^a-z0-9]", "", value.lower()): code
    for code, value in LEAGUE_TEAM_NAME_BY_CODE.items()
    if re.sub(r"[^a-z0-9]", "", value.lower())
}


def _league_team_label(team_code: str) -> str:
    code = _normalize_team_code(team_code)
    if not code:
        return ""
    return LEAGUE_TEAM_NAME_BY_CODE.get(code, code)


def _league_team_code_from_value(team_value: Optional[str]) -> str:
    raw = str(team_value or "").strip()
    if not raw:
        return ""
    if raw.lower() == "all":
        return "ALL"
    as_code = _normalize_team_code(raw)
    if as_code in LEAGUE_TEAM_NAME_BY_CODE:
        return as_code
    by_name = LEAGUE_TEAM_CODE_BY_NAME.get(raw.lower())
    if by_name:
        return by_name
    by_name_normalized = LEAGUE_TEAM_CODE_BY_NAME_NORMALIZED.get(re.sub(r"[^a-z0-9]", "", raw.lower()))
    if by_name_normalized:
        return by_name_normalized
    return as_code


def _league_team_types_from_codes(team_codes: List[str]) -> List[str]:
    out: List[str] = ["All"]
    seen: set[str] = {"All"}
    for code in team_codes:
        label = _league_team_label(code)
        if not label or label in seen:
            continue
        out.append(label)
        seen.add(label)
    return out


def _league_add_labeled_team_keys(by_team_code: Dict[str, List[str]]) -> Dict[str, List[str]]:
    out: Dict[str, List[str]] = {}
    for team_code, names in by_team_code.items():
        code = _normalize_team_code(team_code)
        label = _league_team_label(code)
        out[code] = names
        out[label] = names
    return out


def _add_school_team_filter_keys(
    by_team_code: Dict[str, List[str]],
    *,
    school_code: str,
    team_markers_norm: set[str],
) -> Dict[str, List[str]]:
    if not by_team_code or not team_markers_norm or school_code in {"LEAGUE", "PRO"}:
        return by_team_code
    out = dict(by_team_code)
    school_names: set[str] = set()
    opponent_names: set[str] = set()
    for team_code, names in by_team_code.items():
        code = _normalize_team_code(team_code)
        target = school_names if code in team_markers_norm else opponent_names
        for name in names:
            cleaned = str(name or "").strip()
            if cleaned:
                target.add(cleaned)
    if school_names:
        out[school_code] = sorted(school_names)
    if opponent_names:
        out["Opponents"] = sorted(opponent_names)
    return out


def _filter_pitching_rows_by_team_type(
    rows: List[Dict[str, Any]],
    team_type_value: str,
    school_code: str,
    team_pitcher_norm: set[str],
    campers_norm: set[str],
    team_markers_norm: set[str],
) -> List[Dict[str, Any]]:
    if team_type_value in {"", "All"}:
        return rows
    if school_code == "LEAGUE":
        selected_code = _normalize_team_code(_league_team_code_from_value(team_type_value))
        if not selected_code:
            return rows
        return [
            row
            for row in rows
            if _normalize_team_code(str(row.get("pitcher_team_code") or "")) == selected_code
        ]
    if school_code == "PRO":
        selected_code = _normalize_team_code(_pro_team_code_from_value(team_type_value))
        if not selected_code:
            return rows
        return [
            row
            for row in rows
            if _normalize_team_code(str(row.get("pitcher_team_code") or "")) == selected_code
        ]

    filtered: List[Dict[str, Any]] = []
    for row in rows:
        pitcher_key = _normalize_name_key(str(row.get("pitcher") or ""))
        pitcher_team_code = _normalize_team_code(str(row.get("pitcher_team_code") or ""))
        batter_team_code = _normalize_team_code(str(row.get("batter_team_code") or ""))
        pitcher_is_marker = pitcher_team_code in team_markers_norm if pitcher_team_code else False
        batter_is_marker = batter_team_code in team_markers_norm if batter_team_code else False
        is_pcu_blank_team_row = (
            school_code == "PCU"
            and not pitcher_team_code
            and not batter_team_code
            and bool(pitcher_key)
            and pitcher_key in (team_pitcher_norm | campers_norm)
        )
        # Treat intra-squad team-vs-team rows (both team codes match markers) as team rows.
        is_team_pitching_row = pitcher_is_marker or is_pcu_blank_team_row
        is_opponent_pitching_row = batter_is_marker and bool(pitcher_team_code) and not pitcher_is_marker

        if team_type_value == "Opponents":
            row_team_bucket = "Opponents" if is_opponent_pitching_row else None
        elif team_type_value == "Campers":
            row_team_bucket = "Campers" if (pitcher_key in campers_norm and is_team_pitching_row) else None
        elif team_type_value == school_code:
            if pitcher_key in campers_norm:
                row_team_bucket = "Campers" if is_team_pitching_row else None
            else:
                row_team_bucket = school_code if is_team_pitching_row else None
        else:
            row_team_bucket = None

        if row_team_bucket == team_type_value:
            filtered.append(row)
    return filtered


def _league_team_codes_sql_expr() -> str:
    return """
    SELECT team_code
    FROM (
      SELECT DISTINCT
        CASE WHEN NULLIF(TRIM(level), '') = 'USA Baseball' THEN 'USABASEBALL'
             ELSE NULLIF(UPPER(COALESCE(NULLIF(TRIM(pitcherteam), ''), '')), '') END AS team_code
      FROM public.pitch_events
      WHERE school_code = %(school_code)s
      UNION
      SELECT DISTINCT
        CASE WHEN NULLIF(TRIM(level), '') = 'USA Baseball' THEN 'USABASEBALL'
             ELSE NULLIF(UPPER(COALESCE(NULLIF(TRIM(batterteam), ''), '')), '') END AS team_code
      FROM public.pitch_events
      WHERE school_code = %(school_code)s
    ) t
    WHERE team_code IS NOT NULL
    ORDER BY team_code
    """


def _league_name_map_sql_expr(team_col: str, name_col: str) -> str:
    # Tournament/showcase events (USA Baseball) mint a fresh, one-off team
    # code per squad/pool per event, so hardcoding a display name per code in
    # LEAGUE_TEAM_NAME_BY_CODE isn't sustainable -- new codes appear with
    # every new event. Any row whose `level` says "USA Baseball" is grouped
    # under the synthetic "USABASEBALL" code instead of its raw per-event
    # code; that code is mapped to the display name "USA Baseball" in
    # LEAGUE_TEAM_NAME_BY_CODE like every other team, so it flows through the
    # existing normalized-code pipeline instead of needing special-casing.
    return f"""
    SELECT team_code, array_agg(name ORDER BY name) AS names
    FROM (
      SELECT DISTINCT
        CASE
          WHEN NULLIF(TRIM(level), '') = 'USA Baseball' THEN 'USABASEBALL'
          ELSE NULLIF(UPPER(COALESCE(NULLIF(TRIM({team_col}), ''), '')), '')
        END AS team_code,
        NULLIF(TRIM({name_col}), '') AS name
      FROM public.pitch_events
      WHERE school_code = %(school_code)s
    ) t
    WHERE team_code IS NOT NULL AND name IS NOT NULL
    GROUP BY team_code
    ORDER BY team_code
    """


_API_DIR = os.path.dirname(__file__)
_BUNDLED_SCHOOL_CONFIG_ROOT = os.path.normpath(os.path.join(_API_DIR, "..", "config", "schools"))


@lru_cache(maxsize=16)
def _load_school_roster(school_code: str) -> Dict[str, List[str]]:
    env_path = (os.getenv(f"DASHBOARD_SCHOOL_CONFIG_PATH_{school_code.upper()}", "") or "").strip()
    default_path_by_school = {
        "CBU": os.path.join(_BUNDLED_SCHOOL_CONFIG_ROOT, "CBU", "school_config.R"),
        "OSU": os.path.join(_BUNDLED_SCHOOL_CONFIG_ROOT, "OSU", "school_config.R"),
        "PCU": os.path.join(_BUNDLED_SCHOOL_CONFIG_ROOT, "PCU", "school_config.R"),
        "CNU": os.path.join(_BUNDLED_SCHOOL_CONFIG_ROOT, "CNU", "school_config.R"),
        "GCU": os.path.join(_BUNDLED_SCHOOL_CONFIG_ROOT, "GCU", "school_config.R"),
        "GMU": os.path.join(_BUNDLED_SCHOOL_CONFIG_ROOT, "GMU", "school_config.R"),
        "LSU": os.path.join(_BUNDLED_SCHOOL_CONFIG_ROOT, "LSU", "school_config.R"),
        "TRIAL": os.path.join(_BUNDLED_SCHOOL_CONFIG_ROOT, "TRIAL", "school_config.R"),
        "UNM": os.path.join(_BUNDLED_SCHOOL_CONFIG_ROOT, "UNM", "school_config.R"),
        "SEMO": os.path.join(_BUNDLED_SCHOOL_CONFIG_ROOT, "SEMO", "school_config.R"),
        "CREIGHTON": os.path.join(_BUNDLED_SCHOOL_CONFIG_ROOT, "CREIGHTON", "school_config.R"),
        "HARVARD": os.path.join(_BUNDLED_SCHOOL_CONFIG_ROOT, "HARVARD", "school_config.R"),
        "PRO": os.path.join(_BUNDLED_SCHOOL_CONFIG_ROOT, "PRO", "school_config.R"),
    }
    config_path = env_path or default_path_by_school.get(school_code.upper(), "")
    if not config_path or not os.path.exists(config_path):
        fallback_marker = _normalize_team_code(school_code)
        return {
            "team_only_norm": [],
            "hitter_norm": [],
            "campers_norm": [],
            "team_markers_norm": [fallback_marker] if fallback_marker else [],
        }

    try:
        text = open(config_path, "r", encoding="utf-8").read()
    except Exception:
        fallback_marker = _normalize_team_code(school_code)
        return {
            "team_only_norm": [],
            "hitter_norm": [],
            "campers_norm": [],
            "team_markers_norm": [fallback_marker] if fallback_marker else [],
        }

    allowed_pitchers = _extract_r_vector(text, "allowed_pitchers")
    allowed_hitters = _extract_r_vector(text, "allowed_hitters")
    allowed_campers = _extract_r_vector(text, "allowed_campers")
    if school_code.upper() == "PCU":
        pcu_additions = [
            "Heather, Connor",
            "Carr, Jordan",
            "King, Stan",
            "Jones, Grady",
            "Birt, Henry",
            "Zuniga, Guillermo",
            "Kaufman, Rylan",
            "Mixey, Ryan",
            "Hutchison, Daniel",
            "Clark, Hunter",
            "Luna, Cael",
            "Rodriguez, Diego",
            "Jensen, Tyler",
            "Liguori, Luke",
            "Masi, Jack",
            "Jacobs, Brody",
            "Stevenson, Townsend",
            "Tipton, Jonathan",
            "Lambright, Gavin",
            "Moorhouse, Richard",
            "Bates, Tyler",
        ]
        allowed_pitchers = sorted({*allowed_pitchers, *pcu_additions})
        allowed_hitters = sorted({*allowed_hitters, *pcu_additions})
    team_code = _extract_r_scalar(text, "team_code")
    team_code_markers = _extract_r_vector(text, "team_code_markers")
    team_norm = {_normalize_name_key(name) for name in allowed_pitchers if _normalize_name_key(name)}
    hitter_norm = {_normalize_name_key(name) for name in allowed_hitters if _normalize_name_key(name)}
    campers_norm = {_normalize_name_key(name) for name in allowed_campers if _normalize_name_key(name)}
    # LSU config currently uses allowed_campers as a full-roster mirror, which collapses
    # team bucketing into "Campers". Ignore campers there so Team/Opponent filters work.
    if school_code.upper() == "LSU":
        campers_norm = set()
    team_only_norm = sorted(team_norm - campers_norm)
    marker_source = [*(team_code_markers or []), *([team_code] if team_code else []), school_code]
    team_markers_norm = sorted({_normalize_team_code(code) for code in marker_source if _normalize_team_code(code)})
    return {
        "team_only_norm": team_only_norm,
        "hitter_norm": sorted(hitter_norm),
        "campers_norm": sorted(campers_norm),
        "team_markers_norm": team_markers_norm,
    }


def _load_dashboard_csv_pitchers(school_code: str) -> List[str]:
    school = (school_code or "").strip().upper()
    if not school or school in {"PRO", "LEAGUE"}:
        return []
    try:
        with get_conn() as conn, conn.cursor() as cur:
            cur.execute("SELECT to_regclass('public.dashboard_csv_uploads')::text AS table_name")
            if not (cur.fetchone() or {}).get("table_name"):
                return []
            cur.execute(
                """
                SELECT DISTINCT NULLIF(TRIM(pitcher_name), '') AS pitcher_name
                FROM public.dashboard_csv_uploads
                WHERE school_code = %(school_code)s
                  AND status = 'complete'
                  AND NULLIF(TRIM(pitcher_name), '') IS NOT NULL
                ORDER BY pitcher_name
                """,
                {"school_code": school},
            )
            return [str(row.get("pitcher_name") or "").strip() for row in cur.fetchall() if str(row.get("pitcher_name") or "").strip()]
    except Exception:
        return []


def _merge_dashboard_csv_pitchers_into_filters_payload(
    payload: Dict[str, Any],
    school_code: str,
) -> Dict[str, Any]:
    csv_pitchers = _load_dashboard_csv_pitchers(school_code)
    if not csv_pitchers:
        return payload

    merged_payload = dict(payload)
    existing_pitchers = [str(name).strip() for name in (payload.get("pitchers") or []) if str(name).strip()]
    pitchers_by_key = {_normalize_name_key(name): name for name in existing_pitchers if _normalize_name_key(name)}
    for name in csv_pitchers:
        key = _normalize_name_key(name)
        if key and key not in pitchers_by_key:
            pitchers_by_key[key] = name
    merged_pitchers = sorted(pitchers_by_key.values(), key=lambda name: _display_name_first_last(name).lower())
    merged_payload["pitchers"] = merged_pitchers

    school = (school_code or "").strip().upper()
    team_map_raw = payload.get("pitchers_by_team_code")
    team_map = dict(team_map_raw) if isinstance(team_map_raw, dict) else {}
    school_names = [str(name).strip() for name in (team_map.get(school) or []) if str(name).strip()]
    school_names_by_key = {_normalize_name_key(name): name for name in school_names if _normalize_name_key(name)}
    for name in csv_pitchers:
        key = _normalize_name_key(name)
        if key and key not in school_names_by_key:
            school_names_by_key[key] = name
    team_map[school] = sorted(school_names_by_key.values(), key=lambda name: _display_name_first_last(name).lower())
    merged_payload["pitchers_by_team_code"] = team_map
    return merged_payload


